  // --- the patch notes: what the latest updates brought, newest first; a new id at the top shows a badge until the app is opened
  const PATCH = [
    ['g2-281026', '28.10.2026', 'Innsjøer, elver og himmel', 'Lakes, rivers and sky', [
       ['Innsjøene, tjernene, elvene, bekkene og fossene ligger der kartet har dem, med mørkt vann som speiler himmelen, stryk og is om vinteren.', 'The lakes, tarns, rivers, streams and waterfalls lie where the map has them, with dark water mirroring the sky, rapids, and ice in winter.'],
       ['Skyene lyses av sola, med lyse kanter og mørkere undersider, og når sola står lavt, kommer det rosa beltet over jordskyggen.', 'The clouds are lit by the sun, with bright edges and darker undersides, and when the sun is low the pink belt rises over the earth\'s shadow.'],
       ['Brenningene ligger ved strandkanten og på grunnene, ikke i et bånd et stykke ut fra land.', 'The surf breaks at the shore and on the shoals, not in a band some way out from land.'],
       ['Fangstfeltene har bare navnet sitt i kartet, ingen sirkel.', 'The fishing grounds have only their name on the chart, no circle.']]],
    ['g1-281026', '28.10.2026', 'Naturen etter kartet', 'Nature from the map', [
       ['Bakken følger Kartverkets og satellittenes kart over naturen: myrene, jordene, lyngheiene, vidda, bart fjell, ur og breene ligger der de ligger i virkeligheten.', 'The ground follows Kartverket\'s and the satellites\' maps of nature: the bogs, the fields, the heaths, the fells, bare rock, scree and the glaciers lie where they lie in life.'],
       ['Skogen står der det er skog, med spredte bjørker i lyngen, og ingen trær på myr, vidde eller berg.', 'The woods stand where there are woods, with scattered birches in the heath, and no trees on bogs, fells or rock.'],
       ['Om høsten kommer ruska: lyngen blir rødbrun og bjørkeskogen gul.', 'In autumn the colours turn: the heath goes red-brown and the birch woods yellow.'],
       ['Myrene har tjern og tuer, og åkrene har kjørespor, når du er nær.', 'The bogs have pools and tussocks, and the fields have tram lines, when you are close.']]],
    ['p147', '28.10.2026', 'Skatten for aksjeselskap', 'The tax of a limited company', [
       ['Stifter du aksjeselskap, gjelder det hele året fra 1. januar, slik det gjør når et enkeltpersonforetak omdannes: hele årets overskudd skattlegges i selskapet, og forskuddet du alt har betalt, regnes med.', 'Found a limited company, and it counts for the whole year from 1 January, as when a sole proprietorship is converted: the whole year\'s profit is taxed in the company, and the advance you have already paid counts.'],
       ['Et aksjeselskap som fikk forskuddsskatten trukket i inntektsåret etter de gamle reglene, får rentegodtgjørelse for pengene som ble trukket for tidlig.', 'A limited company that had its advance tax taken in the income year under the old rules gets interest for the money taken too early.'],
       ['Hver dag du er ute med båten, teller som en dag på fiske, ikke bare de dagene båten var ute ved midnatt. Årets leveringsdager regnes med.', 'Every day you are out in the boat counts as a day fishing, not only the days the boat was out at midnight. The year\'s landing days count.'],
       ['Båtenes skattemessige verdi er hele kjøpsprisen, så avskrivningen blir større.', 'The vessels\' tax value is the whole price, so the depreciation is larger.'],
       ['Som enkeltpersonforetak regnes skjermingsfradraget av båtene og kvoten minus lånet i banken, som i virkeligheten. Rentene trekkes fortsatt fullt fra overskuddet.', 'As a sole proprietor the shielding deduction is reckoned on the vessels and the quota less the bank loan, as in life. The interest is still deducted in full from the profit.'],
       ['Et aksjeselskap som betalte forskuddsskatt hvert kvartal før de nye skattereglene, får det trukket fra: skatten for året betales bare én gang, og skattekontoen setter ikke av mer enn det som gjenstår.', 'A limited company that paid advance tax every quarter before the new tax rules has it counted: the year\'s tax is paid only once, and the tax account sets aside no more than what is left.']]],
    ['p146', '27.10.2026', 'Første tur langs hele kysten', 'The first trip along the whole coast', [
       ['Første tur går til et felt like utenfor havna der du starter, uansett hvor på kysten det er. Feltet ligger der juksa får fiske den dagen, og fisken du får, er den som står der: sei og lyr der torsken er fredet, skrei der skreiet står.', 'The first trip goes to a patch just off the harbour where you start, wherever on the coast that is. The patch lies where the jig may fish that day, and the fish you get are the ones that stand there: saithe and pollack where the cod is protected, skrei where the skrei is.'],
       ['Første tur er kortere: én linje i naustet, ett tips på vei ut, og skjermen blir ikke mørk rundt det du skal trykke på. «Kast loss» sier selv hva som mangler.', 'The first trip is shorter: one line in the boathouse, one tip on the way out, and the screen no longer darkens round what to tap. «Cast off» says itself what is missing.']]],
    ['p145', '27.10.2026', 'Skum som blir liggende', 'Foam that stays', [
       ['Kjølvannet er laget på nytt: skummet baugen og hekken lager, blir liggende i sjøen i opptil et halvt minutt og trekker ut i et langt, bredt spor bak båten, også gjennom svinger. Skumtoppene i kuling etterlater seg striper med vinden.', 'The wake has been made anew: the foam the bow and the stern make stays in the sea for up to half a minute and draws out into a long, wide trail behind the boat, through turns too. The whitecaps in a gale leave streaks along the wind.']]],
    ['p144', '27.10.2026', 'Økonomien', 'The money', [
       ['Banken har fått regnskap: året med inntekter og kostnader per post, avskrivning, resultat før og etter skatt, og en kontoutskrift med hver bevegelse på kontoen.', 'The bank has accounts: the year with income and costs by kind, depreciation, the result before and after tax, and a statement with every movement on the account.'],
       ['Mannskapet går på lott etter oppgjørsavtalene i Norges Fiskarlag: turens felleskostnader (drivstoff, is, agn og egning, havneavgift, juksautstyr og tapt redskap) trekkes fra før fangsten deles, og mannskapets del står i avtalens tabeller etter fisket, båtens lengde og hvor mange som er om bord, på juksa etter antall juksamaskiner. En mann har 1 lott, en lærling 40–75 %. Skipperen får skippertillegg fra rederiet når du er i land, og en styrmann på døgndrift får bestmannshyre. Hyre er borte, og de som hadde det, går over på lott.', 'The crew fish on shares by the settlement agreements of Norges Fiskarlag: the trip\'s common costs (fuel, ice, bait and baiting, harbour dues, jig tackle and gear lost) come off before the catch is shared, and the crew\'s part is in the agreement\'s tables by the fishery, the length and how many are aboard, on the jig by the jigging machines. A hand has 1 share, an apprentice 40-75 %. The skipper gets an extra from the company while you are ashore, and a mate on a round-the-clock plan the mate\'s wage. Wages are gone, and those who had them move to shares.'],
       ['Nye kontoer i banken: skattekonto med automatisk avsetning etter hver levering, sparekonto med rente som regnes som egenkapital når du kjøper båt, og kassekreditt med rente når kontoen går i minus.', 'New accounts in the bank: a tax account with an automatic set-aside after each landing, a savings account with interest that counts as equity when you buy a vessel, and an overdraft with interest when the account goes below zero.'],
       ['Skatten følger reglene: som enkeltpersonforetak betaler du forskudd 15. mars, juni, september og desember og får oppgjøret i juni året etter. Et aksjeselskap betaler 15. februar og 15. april året etter og får oppgjøret i oktober. Underskudd føres videre, og Skatteetaten sier fra en uke før hver betaling.', 'The tax follows the rules: as a sole proprietor you pay the advance 15 March, June, September and December and get the settlement in June the year after. A company pays 15 February and 15 April the year after and gets the settlement in October. A loss is carried forward, and Skatteetaten tells you a week before each payment.'],
       ['Rederi-appen åpnes når du har mannskap eller flere båter, ikke bare med et AS. Håndboka har fått et kapittel om økonomien.', 'The Company app opens when you have crew or more vessels, not only with a company. The handbook has a chapter on the money.']]],
    ['p143', '27.10.2026', 'Driftsplanen laget på nytt', 'The operations plan made anew', [
       ['Driftsplanen er laget på nytt. Du svarer på sju spørsmål (hjem, redskap, plasser, levering, vær, rytme, mannskap), og planen legger dagen selv og viser den øverst: når båten går, setter og trekker, leverer og er hjemme. Plassene velges i kartplotteren med et trykk, og en nål kan dras. Alt som ikke kan gjøres nå, venter med grunn og klokkeslett i stedet for å stoppe. Gamle planer er slått av; lag en ny under Driftsplan. Redskapet i sjøen står der det står, og «Hent redskapet» henter det.', 'The operations plan has been made anew. You answer seven questions (home, gear, places, landing, weather, rhythm, crew), and the plan lays the day itself and shows it at the top: when the boat leaves, sets and hauls, lands and is home. The places are chosen in the chart plotter with a tap, and a pin can be dragged. What cannot be done now waits with a reason and an hour instead of stopping. Old plans are switched off; make a new one under Driftsplan. The gear in the sea stays where it is, and «Fetch the gear» brings it in.'],
       ['Døgndrift går med to vakter på tolv timer: skipperen om dagen, styrmannen om natta, og den som har fri sover i køya. Båten må ha køyer til alle om bord. Du regnes med: du og tre i mannskapet er nok.', 'Round-the-clock operation runs with two twelve-hour watches: the skipper by day, the mate by night, and the watch off sleeps in the bunks. The boat must have bunks for everyone aboard. You count: you and three crew are enough.'],
       ['Etter de første prøvingene: planen stopper ikke lenger på torskekvoten. Hvert felt har sin linetype (hyseline eller bankline) og kan aldri få flere stamper enn båten eier. Rekkefølgen på plassene er din: står juksplassen først, jukser båten mesteparten av dagen og setter lina før hjemturen. I kartkortet kan lenka gis retning, og lista der sier hvor lang dagen blir.', 'After the first trials: the plan no longer stops on the cod quota. Each field has its line kind (haddock or bank line) and can never get more tubs than the boat owns. The order of the places is yours: with the jig place first, the boat jigs most of the day and sets the line before going home. The chart card can give the string a heading, and the bar there says how long the day gets.']]],
    ['p142', '26.10.2026', 'Turoppdrag', 'Trip missions', [
       ['Turoppdrag der du fisker selv, får tid til fisket i fristen. Dekksdagboka sier fristen når du tar oppdraget.', 'Trip missions where you fish yourself get time for the fishing in the deadline. The deck log tells the deadline when you take the mission.']]],
    ['p141', '26.10.2026', 'Navn på kartet', 'Names on the chart', [
       ['De store navnene på kartet (byer, fjorder og øyer) vises alltid. Før kunne en lang havneetikett dekke dem, så «Senja» var borte fra kartet over regionen.', 'The big names on the chart (towns, fjords and islands) are always shown. Before, a long harbour label could cover them, so «Senja» was missing from the chart of the region.']]],
    ['p140', '25.10.2026', 'Flytebrygger', 'Floating docks', [
       ['Flytebryggene langs kysten er bygd av pontonger, med fingre der de finnes, endepontong med leider og livbøye, og landgang fra land. De følger tidevannet. Før var de grå kasser.', 'The floating docks along the coast are built of pontoons, with fingers where they have them, an end pontoon with a ladder and life ring, and a gangway from land. They ride the tide. Before, they were grey boxes.']]],
    ['p139', '25.10.2026', 'Plassene i driftsplanen', 'The places in the operations plan', [
       ['«Velg i kartet» i driftsplanen lager ikke lenger en rute. Trykket i kartet blir plassen til feltet eller juksplassen, og panelet med «Bruk plassen» kommer opp med en gang, også på telefonen. Trykker du igjen, flyttes plassen.', '«Choose in the chart» in the operations plan no longer makes a route. The tap in the chart becomes the place for the field or the jig place, and the panel with «Use the place» comes up at once, on the phone too. Tap again to move the place.']]],
    ['p138', '24.10.2026', 'Rettelser', 'Fixes', [
       ['Ruta kan avsluttes ved å trykke på havnas navn i kartet, også havna du startet fra. Et trykk ved havna tar ikke lenger utseilingspunktet.', 'A route can be ended by tapping the harbour\'s name in the chart, also the harbour you set out from. A tap by the harbour no longer takes the way-out point.'],
       ['Driftsplanen sier fra når båten ikke kan lande torsk, hyse og sei uten deg om bord, og at den fisker kveite med kveiteutstyr.', 'The operations plan tells you when the boat cannot land cod, haddock and saithe without you aboard, and that it fishes halibut with halibut gear.'],
       ['Båthandel viser hvilket utstyr som blir med den gamle båten ved innbytte.', 'The boat market shows which equipment goes with the old boat when you trade in.'],
       ['Fiskebåtene i Finnsnes ligger ikke lenger med skroget på land, og havnene i kartet har hvert sitt navn.', 'The fishing boats at Finnsnes no longer lie with the hull on land, and the harbours in the chart each have a name of their own.'],
       ['Fiskebåtene langs kysten ligger i vannet ved kaia i 3D, ikke oppå stranda, og de går ikke lenger gjennom brygger og land på vei ut av havna.', 'The coast\'s fishing boats lie in the water at the quay in 3D, not on the shore, and no longer go through piers and land on their way out of the harbour.'],
       ['Kulden om bord regner med klærne til dem som er med på turen.', 'The cold aboard counts the clothes of those on the trip.'],
       ['Kameraet i 3D går ikke lenger inn i andre båter.', 'The 3D camera no longer goes into other boats.'],
       ['Et sveip over fartsglideren i rutepanelet ruller panelet uten å endre farten.', 'A swipe over the speed slider in the route panel scrolls the panel without changing the speed.']]],
    ['p137', '24.10.2026', 'Ferskhet og frysing', 'Freshness and freezing', [
       ['Iset fisk holder seg nå som i virkeligheten: ekstra kvalitet i to døgn, A til seks døgn og B til tolv. Turer over flere døgn lønner seg med is om bord.', 'Iced fish now keeps as it does in real life: extra quality for two days, A to six days and B to twelve. Trips of several days pay with ice aboard.'],
       ['Uiset fisk holder seg dårligere jo varmere det er. Om sommeren holder den ekstra kvalitet i rundt et halvt døgn, om vinteren lenger.', 'Fish that is not iced keeps worse the warmer it is. In summer it keeps extra quality for about half a day, in winter longer.'],
       ['Skip med fryserom fryser fangsten om bord, og fryst fisk holder kvaliteten. Ringnotskipet kjøler fangsten i tankene idet den kommer om bord. Fryst fisk betales som fersk av samme kvalitet og står som fryst på sluttseddelen.', 'Ships with a freezer hold freeze the catch aboard, and frozen fish keeps its quality. The purse seiner chills the catch in its tanks as it comes aboard. Frozen fish is paid as fresh of the same quality and is marked frozen on the landing note.']]],
    ['p136', '24.10.2026', 'Liggeplass i havnene', 'A berth in the harbours', [
       ['Båten kan ligge ved kai eller flytebrygge i havnene langs hele kysten, på en ledig plass som passer båten og har vann nok ved fjære sjø. Havnene står i kartet, og Fortøy og Autonav tar deg helt inn til plassen.', 'The boat can lie at a quay or a floating dock in the harbours along the whole coast, at a free berth that fits her and has water enough at low tide. The harbours are in the chart, and Moor and Autonav take you all the way in to the berth.'],
       ['Plassen er din mens båten ligger der, eller når den er hjemmet i driftsplanen, og ingen andre spillere får den. Havneavgiften trekkes per døgn etter båtens lengde.', 'The berth is yours while the boat lies there, or while it is the home of the operations plan, and no other player gets it. The harbour due is drawn per day by the length of the boat.'],
       ['Driftsplanens Hjem har de nærmeste havneplassene, etter rorbuene og før mottak, butikk og verft.', 'The Home of the operations plan has the nearest harbour berths, after the rorbuer and before the plants, shops and yards.']]],
    ['p135', '23.10.2026', 'Ny driftsplan', 'A new operations plan', [
       ['Driftsplanen er laget på nytt: én side med Hjem, Fiske, Plasser, Levering, Vær, Rytme og Mannskap. Velg, trykk Start, og planen lager turene selv. «Nå» viser hva båten gjør, og stopper den, står grunnen der med en knapp som løser det.', 'The operations plan has been made anew: one page with Home, Fishing, Places, Landing, Weather, Rhythm and Crew. Choose, tap Start, and the plan makes the trips itself. «Now» shows what the boat is doing, and if she stops, the reason is there with a button that fixes it.'],
       ['Så mange felt og juksplasser du vil, hvert felt med eget antall og egen ståtid. Lina settes og trekkes på samme tur med juksa imellom, og garn og teiner trekkes og settes på nytt når ståtida er ute. Planen leverer alltid på nærmeste mottak.', 'As many fields and jig places as you like, each field with its own number and soak. The line is set and hauled on the same trip with the jig between, and nets and pots are hauled and set again when the soak is up. The plan always lands at the nearest plant.'],
       ['Tre rytmer: dagdrift med fast avgang, døgnet rundt 2 og 2, og turer over flere døgn for båter med køyer. Mannskapet hviler til de er uthvilt. Store båter fra 24 m kan ligge til ankers hjemme om natta.', 'Three rhythms: day trips at a set hour, round the clock 2 and 2, and trips of several days for boats with bunks. The crew rest until they are rested. Big boats from 24 m can lie at anchor at home at night.'],
       ['Uten deg om bord må både en skipper og en styrmann være utnevnt. Det gjør du på Mannskap-siden. En båt med plass til bare én i mannskapet går bare med deg om bord. Planen venter når du tar over båten, og stopper selv ved stengt felt og oppbrukt torskekvote.', 'Without you aboard, both a skipper and a mate must be appointed. You do that on the Crew page. A boat with room for only one crew runs only with you aboard. The plan waits when you take the boat over, and stops by itself at a closed field and a used-up cod quota.'],
       ['De gamle planene er slått av. Lag en ny under Driftsplan. Planen kan kopieres til en annen båt i flåten.', 'The old plans are switched off. Make a new one under Operations plan. The plan can be copied to another vessel in the fleet.']]],
    ['p134', '23.10.2026', 'Ny Mannskap-side', 'A new Crew page', [
       ['Mannskap-siden er ny. Øverst står stemningen om bord, og under den «På dekk nå», som viser hvem som står hvor. Hver person har sitt eget kort med hva de gjør og hvorfor, hvordan de jobber, energi og humør, det siste de sa og den faste plassen. Trykk på navnet for ferdighetene.', 'The Crew page is new. At the top is the mood aboard, and below it «On deck now» shows who stands where. Each person has a card of their own with what they do and why, how they are working, energy and mood, the last thing they said and their regular place. Tap the name for the skills.'],
       ['Folkene har fått hender med fingre og støvler formet etter foten. De holder ting slik man gjør: kniven i neven, koppen rundt koppen, telefonen med begge hender og flate hender på rekka.', 'The people have hands with fingers and boots shaped to the foot. They hold things the way you do: the knife in a fist, the mug round the cup, the phone in both hands and flat hands on the rail.'],
       ['Når en fisk glipper, ser du den fly over ripa og plaske i sjøen. Den som skjærer seg, rister hånda og går med teip rundt hansken en stund. De slitne jobber og går saktere og bøyer seg litt.', 'When a fish slips, you see it fly over the rail and splash into the sea. Whoever cuts a hand shakes it and wears tape round the glove for a while. The tired work and walk slower and stoop a little.'],
       ['Mannskapet legger fra seg kaffen eller telefonen før de går til arbeid, den ved haleren eller roret blir stående til avløseren er der, og de tar i døra før de går inn.', 'The crew put away the coffee or the phone before they go to work, the one at the hauler or the helm stays until relieved, and they reach for the door before going in.']]],
    ['p133', '23.10.2026', 'Pauser, feil og gode råd', 'Breaks, slips and good advice', [
       ['Når det er stille, tar mannskapet pause på hver sin måte: kaffe fra termosen, en prat ved rekka, en røyk eller en snus på dekk, telefonen, kikkerten eller matpakka. Noen spyler og koster dekket. Når båten går, holder de seg inne, og den som røyker, går akterut.', 'When it is quiet, the crew take a break each in their own way: coffee from the flask, a chat at the rail, a smoke or a snus on deck, the phone, the binoculars or a packed lunch. Some hose and sweep the deck. Under way they keep inside, and whoever smokes goes aft.'],
       ['Folk gjør feil av og til: en fisk glipper over rekka, en sløying blir ikke helt fin, eller noen skjærer seg og jobber saktere en stund.', 'People slip up now and then: a fish slides over the rail, a gutting is not quite right, or someone cuts a hand and works slower for a while.'],
       ['De erfarne sier fra om været som er på vei, og om bedre fiske et stykke unna når det har vært dårlig en stund.', 'The old hands speak up about weather on the way, and about better fishing a little way off when it has been poor for a while.'],
       ['Sløyingen er ny: snitt i buken, strupen og gjellene, innmaten ut, hodet kappes, og fisken skrapes ren før den legges i kassa.', 'The gutting is new: a cut in the belly, the throat and the gills, the guts out, the head off, and the fish scraped clean before it goes in the box.'],
       ['Mannskapet går ikke lenger gjennom vegger, rekka eller utstyr, verken i arbeid, i pause eller på vei. Der det er trangt, snur de seg sidelengs. På de store båtene går de gjennom huset mellom fordekket og akterdekket.', 'The crew no longer go through walls, the rail or the kit, at work, on a break or on the way. Where it is narrow, they turn sideways. On the big boats they go through the house between the foredeck and the after deck.']]],
    ['p132', '23.10.2026', 'Mannskapet tar tak selv', 'The crew pitch in', [
       ['Mannskapet fordeler arbeidet selv: de ser hva som må gjøres, hjelper hverandre og tar pause når det er stille. Fisken sløyes alltid før den ises.', 'The crew share out the work themselves: they see what needs doing, help each other and take a break when it is quiet. The fish is always gutted before it is iced.'],
       ['Under Mannskap står det hva hver enkelt gjør og hvorfor, og hvilken plass de har blitt faste på.', 'Under Crew it says what each one is doing and why, and which place they have settled into.'],
       ['Du kan gjøre én fra mannskapet til styrmann. Styrmannen tar roret når du ikke styrer selv. Når båten ligger stille, står du på dekk sammen med de andre.', 'You can make one of the crew the mate. The mate takes the helm when you are not steering yourself. When the boat lies still, you work on deck with the others.'],
       ['Innsatsen går opp og ned med slitenhet, humør, sult, sjøgang, mørke og hvor godt laget fungerer. Under Mannskap står det med ord hvordan hver enkelt jobber, og hvorfor.', 'Effort rises and falls with fatigue, mood, hunger, the sea, the dark and how well the team works. Under Crew it says in words how each one is working, and why.'],
       ['Samholdet om bord vokser med tid på sjøen sammen, god mat og folk som går godt sammen. En krangel som ikke blir løst, trekker det ned. Det står øverst under Mannskap.', 'Team spirit aboard grows with time at sea together, good food and people who get on. A quarrel left unsettled drags it down. It is shown at the top under Crew.']]],
    ['p131', '22.10.2026', 'Kroker og rorplass', 'Hooks and the helm', [
       ['Mannskapet bytter kroker fra lageret om bord også når kontoen er i minus. Det koster ikke penger, bare tid.', 'The crew changes hooks from the stock aboard also when the account is in the red. It costs no money, only time.'],
       ['Skipperen på sjarken styrer fra rattet og står ikke lenger oppå styrhustaket når båten går.', 'The skipper on the sjark steers from the wheel and no longer stands on the wheelhouse roof when the boat is under way.']]],
    ['p130', '21.10.2026', 'Til ankers', 'At anchor', [
       ['Båtene har fått sitt eget anker: plogankeret i baugrulla på sjarkene og snekkene, Hall-ankeret i klysset på kystbåtene og havbåtene, og dreggen på trebåten.', 'The boats have their own anchor: the plough anchor in the bow roller on the sjarks and the snekke, the Hall anchor in the hawse on the coastal and ocean boats, and the grapnel on the wooden boat.'],
       ['Kast anker: ankeret faller, kjettingen løper ut mens båten faller tilbake, og hun legger seg med baugen mot vind og strøm. Hun svinger rundt ankeret når vinden dreier eller tidevannet snur.', 'Drop anchor: the anchor falls, the chain runs out while the boat falls back, and she lies bow to the wind and the current. She swings round the anchor when the wind veers or the tide turns.'],
       ['Hiv anker tar den tiden kjettingen trenger. Båten kommer opp over ankeret, og ruta, Autonav og roret venter til ankeret er oppe.', 'Weighing the anchor takes the time the chain needs. The boat comes up over the anchor, and the route, Autonav and the helm wait until it is up.'],
       ['Registreringsmerket finner en fri plass på baugen og får farge etter malingen under. På kystbåten 15 m dekket klysset en del av merket, og på snekka og plastsjarken sto det på den mørke stripa.', 'The registration mark finds a clear place on the bow and takes its colour from the paint under it. On the 15 m coastal boat the hawse hid part of the mark, and on the snekke and the plastic sjark it stood on the dark stripe.'],
    ]],
    ['p129', '21.10.2026', 'Utsikt fra broa', 'A view from the bridge', [
       ['Bro-visningen ser ut av vinduene på den nye hurtigsjarken, kystbåten 15 m, den nye plastsjarken, autolineren, snøkrabbebåten, tråleren og ringnotbåten. Innsiden av styrhuset dekket vinduene.', 'The bridge view looks out of the windows on the new fast sjark, the 15 m coastal boat, the new plastic sjark, the longliner, the snow crab boat, the trawler and the purse seiner. The inside of the wheelhouse covered the windows.'],
       ['Styrhuset på den nye hurtigsjarken har fått lavere dørk, så den som står ved roret har hodet under taket. På den gamle kystbåten 21 m er styrhuset et rom med full takhøyde, og på snekka sitter den som styrer under hardtoppen.', 'The wheelhouse on the new fast sjark has a lower floor, so the one at the wheel has his head under the roof. On the old 21 m coastal boat the wheelhouse is a room with full headroom, and on the snekke the one steering sits under the hard top.'],
       ['Den nye hurtigsjarken har fått sammenleggbar kran på skapet i styrbord hekk.', 'The new fast sjark has a folding crane on the locker in the starboard quarter.'],
       ['Krabbekaret står bare på dekk når båten er rigget for teiner, og da på ledig dekk.', 'The crab tank is only on deck when the boat is rigged for pots, and then on clear deck.'],
       ['Kystradioen vises på skjermen i 15 sekunder og legges ikke lenger i Meldinger. Dagens værmeldinger står fortsatt i dekksdagboka.', 'The coast radio shows on the screen for 15 seconds and no longer goes into Messages. The day\'s forecasts are still in the deck log.'],
       ['Mannskapet går inn med en gang båten er underveis, i stedet for å bli stående og lene seg over rekka en stund.', 'The crew go inside as soon as the boat is under way, instead of staying to lean over the rail for a while.'],
       ['Utstyrssiden på verftet åpner igjen for båter med lasterom. «Isolert lasterom» manglet beskrivelsen sin, og siden stoppet.', 'The equipment page at the yard opens again for boats with a hold. «Insulated hold» was missing its description, and the page stopped.'],
       ['Mannskapet tar pausen ved rekka på dekket: ingen står lenger oppå rekka, inntil veggen med armene gjennom den, eller feier utenfor båten. Feiing og kveiling gjøres vendt mot dekket.', 'The crew take their break at the rail on deck: nobody stands on top of the rail, against the wall with their arms through it, or sweeps outside the boat any more. Sweeping and coiling are done facing the deck.'],
       ['Et sveip nedover i kartplotteren eller i 3D laster ikke lenger spillet på nytt.', 'A swipe down on the chart plotter or in 3D no longer reloads the game.'],
       ['Radarkuppelen på den nye hurtigsjarken står på radarplattformen i masta, ikke på taket.', 'The radome on the new fast sjark stands on the radar platform in the mast, not on the roof.'],
       ['Bunnstoffet og den hvite stripa går ikke lenger opp langs baugen på den nye hurtigsjarken, og stripa danner ikke lenger et hakk i stevnen. Det samme er rettet på plastsjarken og snekka.', 'The antifouling and the white stripe no longer run up the bow of the new fast sjark, and the stripe no longer makes a notch at the stem. The same is fixed on the plastic sjark and the snekke.'],
       ['Truckføreren på mottakskaia er en av havnearbeiderne og sitter i trucken mens den kjører.', 'The forklift driver at the plant is one of the harbour workers and sits in the truck while it drives.'],
       ['Hekkbølgene ut til sidene står i ro bak båten i stedet for å løpe av gårde, og sprøyten fra baugen er en fin dusj som følger båten.', 'The stern waves out to the sides stand still behind the boat instead of running off, and the spray from the bow is a fine mist that keeps up with the boat.'],
       ['Linekortet i utstyrsbutikken sier fra at line du ikke trenger, kan selges tilbake under Service.', 'The line card in the tackle shop says that line you do not need can be sold back under Service.']]],
    ['p128', '20.10.2026', 'Hver sin jobb på dekk', 'Everyone has a job on deck', [
       ['Mannskapet har faste plasser: én haler, én bløgger, én sløyer og én pakker og iser. Ingen står i hverandre, og ledige hender går dit det venter mest arbeid.', 'The crew have their places: one hauls, one bleeds, one guts and one packs and ices. Nobody stands inside anyone else, and free hands go where most work waits.'],
       ['Hver fisk går fra hånd til hånd: høttes eller plukkes inn, bløgges, sløyes, legges i kassa og ises. Full kasse bæres ned i rommet.', 'Every fish goes from hand to hand: gaffed or picked in, bled, gutted, laid in the crate and iced. A full crate is carried down to the hold.'],
       ['Egning, rensing av gammelt agn og bøting av garn vises på dekk, og flere sammen blir fortere ferdige.', 'Baiting, stripping old bait and mending nets show on deck, and several together finish sooner.'],
       ['Stampene vises i agnets farge. Du velger agn når du egner, kan ta av gammelt agn, og Sett ut viser hvilket agn som står i hver stamp.', 'Tubs show in the colour of their bait. You choose the bait when baiting, can strip old bait, and Set out shows the bait in each tub.'],
       ['Juksa viser hvilke arter utstyret tar, og kveitepilk krever kveiteutstyr.', 'The jig shows which species its tackle takes, and a halibut jig needs halibut gear.'],
       ['Ekkoloddet viser fisken som står der, likt enten båten er rigget for juksa, garn, line eller teiner. Fangsttall kommer bare fra det du har fått om bord, ved fangstprikkene i kartet.', 'The echo sounder shows the fish that are there, the same whether the boat is rigged for the jig, nets, line or pots. Catch figures come only from what you have taken aboard, by the catch marks on the chart.'],
       ['Hurtigsjarken har fått sammenleggbar kran, og havbåtene legger kranene i bomstøtte.', 'The fast sjark has a folding crane, and the ocean boats lay their cranes in boom rests.'],
       ['Siden zoomer ikke lenger når du kniper eller dobbelttrykker, og på smale telefoner i stående format legger knappene på sjøen seg i to rader i stedet for under dagboka og telefonen.', 'The page no longer zooms when you pinch or double-tap, and on narrow phones held upright the buttons at sea lie in two rows instead of under the deck log and the phone.'],
       ['Båtnavnet legges ikke lenger oppå registreringsmerket på baugen (havsjarken og flere): merket står på baugen og navnet akter for det.', 'The boat\'s name no longer lies on top of the registration mark on the bow (the havsjark and others): the mark stands on the bow and the name aft of it.']]],
    ['p127', '20.10.2026', 'Ekte utstyr på dekk', 'Real gear on deck', [
       ['Fisken hugges inn over rekka med høtt, bløgges med kniven og kastes i bløggekaret med blodvann.', 'The fish is gaffed in over the rail, bled with the knife and tossed into the bleeding tub.'],
       ['På de åpne båtene fylles fiskekarene på dekk med sløyd fisk under knust is. Avkappet fra sløyebordet går over rekka.', 'On the open boats the fish tubs on deck fill with gutted fish under crushed ice. The offal from the gutting table goes over the rail.'],
       ['Rigget for garn står garnkaret på dekk, og rigget for line stampene med lina og krokene på kanten. De tømmes og fylles når redskapen settes og trekkes.', 'Rigged for nets the net tub stands on deck, and rigged for line the tubs with the line and the hooks on the rim. They empty and fill as the gear is set and hauled.'],
       ['Redningsflåte i vugge og livbøyer med båtens navn og hjemhavn, så mange som reglene krever for båten.', 'A liferaft in its cradle and lifebuoys with the boat\'s name and home port, as many as the rules ask for the boat.'],
       ['Radar kan kjøpes i utstyrsbutikken: kuppel på styrhuset eller åpen antenne i masta. Den går rundt når du er ute.', 'A radar can be bought at the tackle shop: a dome on the wheelhouse or an open array on the mast. It turns while you are out.'],
       ['Frakt på dekk står i trekasser på paller, og kranen på kystbåtene folder seg ut, laster ved kaia og pakkes sammen igjen.', 'Freight on deck stands in wooden crates on pallets, and the crane on the coastal boats unfolds, loads at the quay and folds up again.']]],
    ['p126', '19.10.2026', 'Støt og grunnstøting får følger', 'Blows and groundings have consequences', [
       ['Under 1 knop tar fenderne et støt. Fra 1 knop blir det skrammer i malingen, og du ser dem på skroget. Fra 3 knop blir skroget skadet, og et hardt støt kan slå hull.', 'Under 1 knot the fenders take a blow. From 1 knot the paint gets scratches, and you see them on the hull. From 3 knots the hull is damaged, and a hard blow can hole her.'],
       ['Går du på grunn, er det forskjell på sand og fjell. Lekker båten, går lensepumpa. Tar den ikke unna, fylles motorrommet, og mannskapet ringer etter redningsskøyta.', 'Running aground, sand and rock are not the same. If she leaks, the bilge pump runs. If it cannot keep up, the engine room fills, and the crew calls the rescue boat.'],
       ['Verftet reparerer skroget under Vedlikehold, og der kan du tegne kasko som betaler det som går over egenandelen.', 'The yard mends the hull under Maintenance, and there you can take out hull insurance that pays what goes over the deductible.'],
       ['Skyene driver med vinden i ekte tid, raskere når det blåser, og hopper ikke lenger når vinden dreier.', 'The clouds drift with the wind in real time, faster when it blows, and no longer jump when the wind turns.']]],
    ['p125', '19.10.2026', 'Vinden og sjøen tar i båten', 'The wind and the sea take hold of the boat', [
       ['Båten kjenner vinden og sjøen: hun holder farten best med sjøen bakfra og dårligst rett mot den, driver litt av i sidevind, og propellen kan komme opp av vannet i grov sjø. Går du akterover, går hekken til babord.', 'The boat feels the wind and the sea: she holds her speed best with the sea astern and worst straight into it, makes a little leeway in a side wind, and the propeller can come out of the water in a heavy sea. Going astern, the stern walks to port.'],
       ['Ligger du stille, driver hun med vinden og legger seg tvers av den. Jukser du, kjører skipperen opp igjen når dere har drevet av feltet, og motoren holder henne unna land.', 'Lying still, she drifts with the wind and lies across it. Jigging, the skipper runs back up when you have drifted off the ground, and the engine holds her off the land.'],
       ['Kjører du inn i kaia eller brygga, tar fenderne imot og hun spretter av. I 3D ruller hun mer når hun ligger tvers av sjøen, og den korte sjøen møter skroget i riktig takt.', 'Run into the quay or a pier, and the fenders take it and she bounces off. In 3D she rolls more lying beam-on to the sea, and the short sea meets the hull at the right pace.'],
       ['De raske båtene svinger stramt også i havnefart.', 'The fast boats turn tightly at harbour speed too.']]],
    ['p124', '19.10.2026', 'Oppdragene betales for jobben', 'Missions are paid for the job', [
       ['Belønningen settes etter hva båten din tjener på vanlig fiske, og prisen du ser på tavla, er prisen du får. Nye oppdrag kommer etter hvert, høyst fire på tavla, og du kan ha to om gangen. Det som ligger på veien din, står først, med omveien det koster.', 'The reward is set by what your boat earns at ordinary fishing, and the price you see on the board is the price you get. New missions come as time goes, at most four on the board, and you can have two at a time. What lies on your way comes first, with the detour it costs.']]],
    ['p123', '19.10.2026', 'Båten beveger seg som en båt', 'The boat moves like a boat', [
       ['Båten din går nå etter en manøvreringsmodell: hun får fart gradvis med motorens krefter, svinger på sin egen radius (to båtlengder med fullt ror), skjærer med baugen inn i svingen og mister fart i den, og trenger plass til å stoppe. Ruta og Autonav styrer med autopilot langs streken, slakker av før skarpe svinger og stopper nøyaktig på punktet. Manuell styring går rett inn i samme modell. Hver båttype er kalibrert etter sine egne tall.', 'Your boat now moves by a manoeuvring model: she gathers way gradually with the engine\'s power, turns on her own radius (two lengths at full rudder), points her bow into the turn and loses speed in it, and needs room to stop. The route and Autonav steer with an autopilot along the line, ease off before sharp corners and stop exactly on the point. Manual steering goes straight into the same model. Every vessel type is calibrated from its own numbers.']]],
    ['p122', '19.10.2026', 'Sjøen rundt båten følger med', 'The sea round the boat keeps up', [
       ['Den korte sjøen, krusningene og skummet rundt skroget går nå med båten i fart, så sjøen ikke lenger stryker forbi skroget seks ganger for fort på skjermen. De lange bølgene og dønningen står i verden som før.', 'The short sea, the ripples and the foam round the hull now ride with the boat under way, so the sea no longer streams past the hull six times too fast on the screen. The long waves and the swell stand in the world as before.']]],
    ['p121', '18.10.2026', 'Landskapet får materiale', 'The land gets its surface', [
       ['Fjellet, bakken og strendene langs hele kysten har fått overflate: berg med sprekker og lav der det bratner, gress og lyng i tuer, myr på flat mark, flekkete snøkanter og åssider som ikke lenger er like. Detaljen legges på nær båten og koster ingenting på lav grafikk.', 'The mountains, ground and shores along the whole coast have a surface now: rock with joints and lichen where it steepens, grass and heather in tufts, bog on the flats, ragged snow edges and hillsides that no longer match. The detail comes in near the boat and costs nothing on low graphics.']]],
    ['p120', '18.10.2026', 'Båtene i havnene ligger riktig', 'The boats in the harbours lie right', [
       ['Båtene langs kysten ligger ikke lenger med skroget inne i land når de er i havn. Finnes det ikke plass ved kaia, ligger de mindre båtene ved en flytebrygge med landgang, og de større på en fortøyningsbøye ute på havna, aldri oppå andre båter, mottak, verft, butikker, naust eller rorbuer.', 'The coast\'s boats no longer lie with the hull ashore when they are in harbour. Where the quay has no room, the smaller boats lie at a floating dock with a gangway and the bigger ones on a mooring buoy out in the harbour, never on top of other boats, buying stations, yards, shops, boathouses or rorbuer.']]],
    ['p119', '18.10.2026', 'Rettinger på båtene', 'Fixes on the boats', [
       ['Ingen båt kommer lenger med haler ferdig montert: haleren du kjøper, står der den hører hjemme på rekka. Plastsjarken har fått vinduene på plass, styrhusdøra ved siden av dem i stedet for tvers gjennom, og en finere baug.', 'No boat comes with a hauler fitted any more: the hauler you buy stands where it belongs at the rail. The fibreglass sjark has her windows in place, the wheelhouse door beside them instead of through them, and a fairer bow.'],
       ['Databladet i Båthandelen sier nå lukket gruppe med hjemmelslengde og faktisk lengde for båter som selges med hjemmel, og åpen gruppe bare for dem uten.', 'The datasheet in the boat market now says closed group with quota length and actual length for boats sold with a right, and open group only for those without.']]],
    ['p118', '17.10.2026', 'Båtene får nye detaljer', 'The boats get their details', [
       ['Trebåten har fått ekte lanterner: rødt og grønt på rekka ved den fremre tofta, og den hvite lykta på en stake akter, slik en båt under sju meter fører dem. En livbøye henger innenfor ripa.', 'The wooden boat has real lanterns: red and green on the gunwales by the forward thwart, and the white lamp on a staff aft, as a boat under seven metres carries them. A lifebuoy hangs inside the gunwale.'],
       ['Snekka har fått sidelanterner på ruffen, akterlanterne på flaggstanga og navnet på hekken i tillegg til baugene. Mannskapet går inn gjennom den ekte nedgangen til kahytten. I Malerverkstedet kan ruffen og dekket males hver for seg på båter som har det.', 'The snekke has side lights on the trunk, a stern light on the flag staff and her name on the transom as well as the bows. The crew go in through the real companionway. In the paint shop the cabin and the deck can be painted on their own on boats that have them.'],
       ['Den nye hurtigsjarken er bygget om fra grunnen: ekte dører til kahytten og styrhuset, konsoll, ratt og stol bak vinduene, sløyebord og kasser på dekk, pullerter, fendere, slingrekjøler, ankervinsj, redningsflåte og livbøye, lanterner med farget glass, og navnet på baugene og hekken.', 'The new speed sjark is rebuilt from the keel up: real doors to the cabin and the wheelhouse, a console, wheel and chair behind the windows, a gutting table and boxes on deck, bollards, fenders, bilge keels, a windlass, a liferaft and a lifebuoy, lanterns with coloured glass, and her name on the bows and the transom.'],
       ['Den brukte hurtigsjarken har fått konsoll, ratt og stol bak vinduene, sidelanterner på taket med farget glass, navnet på den hvite skansen forut og på hekken, og kasser på dekk.', 'The used speed sjark has a console, wheel and chair behind her windows, side lights with coloured glass on the roof, her name on the white bulwark forward and on the transom, and boxes on deck.'],
       ['Sjarken på 36 fot har fått sløyebord under lyet, rødt fiskelys over det hvite på masta, navnet på hekken, og litt slitasje i malingen etter ti år på sjøen.', 'The 36 ft sjark has a gutting table under the shelter, a red fishing light over the white on the mast, her name on the transom, and a little wear in her paint after ten years at sea.'],
       ['Kystbåten på 14,99 m har fått leider fra halestasjonen opp til shelterdekket med nedgang og karm, ekte dører til dekket og styrhuset, konsoll og stol bak vinduene, sløyebord ved halestasjonen, lanterner med farget glass, fiskelys på masta, lyskastere, redningsflåte, pullerter, flaggstang med akterlanterne, og navnet på begge bauger og hekken.', 'The 14.99 m coastal vessel has a ladder from the hauling station up to the shelter deck with a well and coaming, real doors to the deck and the wheelhouse, a console and chair behind the windows, a gutting table by the hauling station, lanterns with coloured glass, fishing lights on the mast, floodlights, a liferaft, bollards, a flag staff with the stern light, and her name on both bows and the transom.'],
       ['Den gamle kystbåten på 21 m har fått rust og slitt maling slik en stålbåt fra syttitallet har det, teakdører i dekkshuset og styrhuset, bakkdør, det gamle rattet og konsollen bak vinduene, sløyebord ved galgen, lanterner og fiskelys, lyskastere, redningsflåte, pullerter, og navnet forut og rundt den runde hekken.', 'The old 21 m coastal vessel has rust and worn paint as a steel boat from the seventies has, teak doors in the deckhouse and the wheelhouse, a forecastle door, the old wheel and console behind the windows, a gutting table by the gallows, lanterns and fishing lights, floodlights, a liferaft, bollards, and her name forward and round the cruiser stern.'],
       ['Ny båt på verftet: plastsjarken på 31 fot (9,45 m) med styrhus akter, åpent arbeidsdekk og to køyer i ruffen, bygget etter den vanlige norske plastsjarken. Hjemmelen 8–8,9 m er tilbake i lukket gruppe, med denne båten.', 'A new boat at the yard: the 31 ft fibreglass sjark (9.45 m) with the wheelhouse aft, an open working deck and two berths in the cabin, built after the common Norwegian fibreglass sjark. The 8–8.9 m right is back in the closed group, with this boat.'],
       ['Havsjarken på 35 fot har fått lanterner med farget glass, rødt fiskelys på masta og navnet på hekken, og skiffen fører sidelanternene på baugen og den hvite lykta på stanga akter.', 'The 35 ft ocean sjark has lanterns with coloured glass, a red fishing light on her mast and her name on the transom, and the skiff carries her sidelights on the bow and the white light on the pole aft.'],
       ['Havbåtene (autolineren, snøkrabbebåten, tråleren og ringnotbåten) har fått ekte dører fra arbeidsdekket inn i overbygget og til styrhuset, lanterner med farget glass og to topplanterner slik store fartøy fører dem, og navnet på begge bauger og på hekken. Overbygg og dekk kan males hver for seg også på dem.', 'The ocean boats (the autoliner, the snow crab vessel, the trawler and the purse seiner) have real doors from the working deck into the superstructure and to the wheelhouse, lanterns with coloured glass and two masthead lights as large vessels carry them, and the name on both bows and on the stern. Superstructure and deck can be painted separately on them too.']]],
    ['p117', '17.10.2026', 'Lanterner etter Sjøveisreglene', 'Lights by the rules of the road', [
       ['Båtene fører lanterner etter Sjøveisreglene: rødt over hvitt når det fiskes, grønt over hvitt når det tråles, topplanterne, sidelanterner og akterlanterne under fart, ett hvitt lys til ankers, to røde ved motorstopp, og ingen ved kai. Det gjelder også båtene rundt deg.', 'The boats carry their lights by the rules of the road: red over white when fishing, green over white when trawling, masthead, side and stern lights under way, one white at anchor, two reds with the engine stopped, and none at the quay. The boats around you too.']]],
    ['p116', '17.10.2026', 'Samme stige i begge gruppene', 'The same ladder in both groups', [
       ['Hjemmelen 10–10,9 m fås nå også med sjarken på 36 fot og den nye hurtigsjarken, så valget mellom fart, plass og pris er det samme i lukket gruppe som i åpen. Neste mål peker på neste hjemmel.', 'The 10–10.9 m right now comes with the 36 ft sjark and the new speed sjark too, so the choice between speed, room and price is the same in the closed group as in the open. Next goals point to the next right.']]],
    ['p115', '17.10.2026', 'Maskiner og frakt på dekk', 'Machines and freight on deck', [
       ['Verftet monterer sløyemaskin og ismaskin på båter over 14,99 meter. Fraktegods går på dekk først og tar plass i lasterommet bare når dekket er fullt, og lasting og lossing tar tid: med kran går det fort, for hånd bæres det om bord i småkolli.', 'The yard fits a gutting machine and an ice machine on boats over 14.99 metres. Freight goes on deck first and takes hold room only when the deck is full, and loading and landing take time: fast with a crane, by hand it is carried aboard in small pieces.']]],
    ['p114', '17.10.2026', 'Mannskapet og båten', 'The crew and the boat', [
       ['På en båt med køyer kan du nå hvile i køya til ankers, og på sjøen når noen av mannskapet er våkne og har vakta (Hvil i skuffen). Mannskapet jobber videre mens du sover. Takk for tipset!', 'On a boat with berths you can now rest in the bunk at anchor, and at sea when someone of the crew is awake on watch (Rest in the dock). The crew work on while you sleep. Thanks for the tip!'],
       ['Båtens egne fasiliteter teller: uten bysse blir det matpakke og termos, en kokeplate gir enkle retter, bysse og messe løfter humøret; ly over arbeidsdekket og tørkerom tar av for kulda, en åpen båt sliter mer; sløyebordet har plass til så mange som databladet sier, og døgndrift 2+2 krever styrhus og køyer.', 'The boat\'s own facilities count: without a galley it is a packed lunch and a flask, a hotplate gives simple dishes, a galley and a mess lift the mood; a shelter deck and a drying room take the edge off the cold, an open boat tires more; the gutting table takes as many as the sheet says, and a 2+2 watch needs a wheelhouse and bunks.']]],
    ['p113', '17.10.2026', 'Båtene gjennomgått', 'The boats reviewed', [
       ['Alle båtene har fått samme skjema: skrogmateriale, lasterom eller dekkslast, plass til frakt på dekk, forbruk i liter per time, rekkevidde, lugarer, køyer og fasiliteter om bord. Forbruket følger nå motoren, så de større båtene bruker mer diesel i marsj enn før. Havsjarken sover fire, den nye hurtigsjarken fire, og den brukte hurtigsjarken går med to. Databladet i Båthandelen og under Beholdning → Båten viser de samme åtte delene for alle båter.', 'Every boat now has the same sheet: hull material, hold or deck load, room for freight on deck, burn in litres an hour, range, cabins, berths and the facilities aboard. The burn follows the engine, so the bigger boats use more diesel at cruising speed than before. The havsjark sleeps four, the new speed sjark four, and the used speed sjark runs with two. The spec sheet in the boat market and under Inventory → The boat shows the same eight sections for every boat.']]],
    ['p112', '17.10.2026', 'Plastsjarken går ut', 'The fibreglass sjark leaves', [
       ['Plastsjarken på 29 fot er tatt ut av Båthandelen. Den som eide en, har fått havsjarken på 35 fot i stedet, uten mellomlegg. En ny og bedre båt i samme størrelse kommer.', 'The 29 ft fibreglass sjark has left the boat market. Anyone who owned one has the 35 ft havsjark in her place, at no cost. A new and better boat of the same size is coming.']]],
    ['p111', '17.10.2026', 'Oppdragene', 'The missions', [
       ['Sesongoppdragene passer nå båten din: kiloene følger det du selv har levert ei vanlig uke, tida til reisen er trukket fra, og arten er en du har redskap og kvote igjen til. Takk for tipset!', 'The season missions now fit your boat: the kilos follow what you yourself land in a usual week, the time for the trip is taken off, and the species is one you have the gear and quota left for. Thanks for the tip!'],
       ['Belønningen for oppdrag følger det du selv tjener på fisket, og der du beholder fangsten, betaler oppdraget et tillegg i stedet for hele tida. Oppdrag du alt har tatt, er regnet om på samme måte.', 'The reward for missions follows what you yourself earn from fishing, and where you keep the catch, the mission pays a premium instead of the whole time. Missions you have already taken are worked out the same way.']]],
    ['p110', '17.10.2026', 'Mannskapet går på dekk', 'The crew walk the deck', [
       ['Folkene om bord står ikke lenger fast på plassene sine. De går over dekket mellom roret, sløyebordet, karet, haleren og juksamaskinene når arbeidet skifter, og tar seg en tur langs rekka når de er ledige. Under fart går mannskapet inn i styrhuset. Første steg av «mannskap med liv»; mer liv kommer.', 'The people aboard no longer stand fixed at their places. They walk the deck between the helm, the gutting table, the tub, the hauler and the jigging reels as the work changes, and take a turn along the rail when idle. Under way the crew go into the wheelhouse. First step of «crew with a life»; more life to come.'],
       ['Det samme gjelder båtene rundt deg: andre spilleres båter og båtene langs kysten har folk som går på dekk når du er nær nok til å se dem. Den som sløyer, bærer kassa til lasteluka, folk snur hodet når du kommer nær, og båtene uten innredning i styrhuset har fått ratt og stol.', 'The same goes for the boats around you: other players\' boats and the boats along the coast have people walking their decks when you are near enough to see them. The one gutting carries the box to the hatch, people turn their heads when you come close, and the boats with a bare wheelhouse have got a wheel and a chair.'],
       ['Mannskapet har fått et liv ved siden av arbeidet. Hver av dem har en familie, en drøm (egen båt, føre båt nummer to, eller et rolig liv) og sparepenger som vokser med det de tjener om bord. Kortet under Mannskap viser drømmen, hvor langt det er igjen, og de siste linjene i historien deres: bursdager, bryllup, barn, sykdom og et fall på dekk i grov sjø, som gir fri. Den som har spart nok til egen båt, sier opp med ei ukes varsel, går i land i havn, fisker fra hjemstedet sitt og tuter til deg når dere møtes, og kommer tilbake til Mannskapsbørsen etter et år eller to.', 'The crew have got a life beside the work. Each of them has a family, a dream (a boat of their own, skippering a second boat, or a quiet life) and savings that grow with what they earn aboard. The card under Crew shows the dream, how far there is to go, and the last lines of their story: birthdays, weddings, children, illness and a fall on deck in a heavy sea, which all give time off. One who has saved enough for a boat of their own gives a week\'s notice, goes ashore in port, fishes out of their home place and sounds the horn when you meet, and is back at the crew exchange after a year or two.']]],
    ['p109', '14.10.2026', 'Ekkoloddet når garna settes', 'The echo sounder when the nets are set', [
       ['Med flere slags garn om bord kunne fisken nesten forsvinne fra ekkoloddet når ei lenke ble satt ut, fordi kartet byttet til neste lenkes garntype. Kartet viser nå fisken for lenka du setter eller sist satte. Takk for tipset!', 'With several kinds of nets aboard, the fish could almost vanish from the echo sounder when a string was set, because the map switched to the next string\'s kind of net. The map now shows the fish for the string you are setting or set last. Thanks for the tip!']]],
    ['p108', '13.10.2026', 'Kartplotteren på smale telefoner', 'The chart plotter on narrow phones', [
       ['På de smaleste telefonene havnet knappene for innstillinger og lukk på en egen rad, og stripa med veipunkt og ETA dekket toppen av infoboksen, så den ikke kunne felles sammen. Alt får nå plass i baren igjen. Takk for tipset!', 'On the narrowest phones the settings and close buttons ended up on a row of their own, and the waypoint and ETA strip covered the top of the info box so it could not be folded away. Everything fits in the bar again. Thanks for the tip!']]],
    ['p107', '13.10.2026', 'Autonav, ruter og driftsplanen', 'Autonav, routes and the operations plan', [
       ['Autonav kunne stoppe uten rute når veien gikk langt til havs, der kystkartet slutter (for eksempel ut mot eggakanten). Dybden leses nå riktig helt ut til kanten.', 'Autonav could stop without a route when the way went far out to sea, where the coastal chart ends (for example out towards the shelf edge). The depth is now read right out to the edge.'],
       ['Spillet stopper ikke lenger når du tegner en rute over et område kartet ikke har lastet ennå. Advarslene for grunner og skjær kommer når kartet er lastet.', 'The game no longer stops when you draw a route over an area the map has not loaded yet. The warnings for shallows and rocks appear once the map is in.'],
       ['Planmakeren sier nå tydelig hva mannskapet gjør når lasten er full: de leverer og går ut igjen så mange turer som planen viser, venter ved kaia hvis mottaket er stengt, og hviler etter siste levering.', 'The plan maker now says clearly what the crew do when the hold is full: they land and go out again as many trips as the plan shows, wait at the quay if the plant is closed, and rest after the last landing.'],
    ]],
    ['p106', '12.10.2026', 'Køyene og juksamaskinene', 'The bunks and the jigging reels', [
       ['Ligger båten ved kai og har køyer, sover mannskapet i dem til de er uthvilt, i stedet for å stå ute på dekk. Takk for tipset!', 'When the boat lies at the quay and has bunks, the crew sleep in them until they are rested, instead of standing out on deck. Thanks for the tip!'],
       ['Når du jukser med juksamaskiner, står det over knappene hvor mange som er i bruk. Én mann passer tre maskiner, så «3 av 5» betyr at det trengs flere hender til resten.', 'When you jig with jigging reels, the line above the buttons says how many are in use. One hand tends three reels, so «3 of 5» means more hands are needed for the rest.']]],
    ['p105', '12.10.2026', 'Ekkoloddet og juksa', 'The echo sounder and the jig', [
       ['Ekkoloddet kunne stoppe for resten av økta hvis en kartbit ikke var lastet inn ennå. Nå hopper det over den biten og prøver igjen litt senere.', 'The echo sounder could stop for the rest of the session when a piece of the map was not loaded yet. It now skips that piece and tries again a little later.'],
       ['Når du jukser fra en båt med styrhus og har mannskap om bord, går skipperen nå ut på dekk og jukser selv, mens mannskapet sløyer. Før ble han stående i styrhuset.', 'When you jig from a boat with a wheelhouse and have crew aboard, the skipper now goes out on deck and jigs himself while the crew gut. Before, he stayed in the wheelhouse.'],
    ]],
    ['p104', '10.10.2026', 'Håndboka', 'The handbook', [
       ['Mannskap kan bare sies opp når båten ligger til kai (mottak, verft, naust, rorbu, butikk eller en annen kai), ikke mens hun er ute i drift eller ligger for anker.', 'Crew can only be let go with the boat at a quay (a plant, a yard, a boathouse, a rorbu, a shop or another quay), not while she is out working or at anchor.'],
       ['Den som sies opp eller mønstrer av med fangst om bord, får lotten sin av fangsten der og da, og den som går på hyre, får hyre for den delen av dagen som er gått. Mannskap som var med da fisken ble tatt, får lott ved levering selv om de har fått fri etterpå.', 'Crew let go or signing off with catch aboard are paid their share of it there and then, and those on a wage get the part of the day worked. Crew who were aboard when the fish was caught get their share at the landing even if given time off since.'],
       ['Stedsnavnene som fløt i lufta i 3D-visningen, er fjernet.', 'The place names floating in the air in the 3D view are gone.'],
       ['Kystradioen sender lokale værmeldinger på VHF kl. 09, 12, 15, 18 og 21: vinden og bølgene der båten er, og hvordan vinden går de neste tolv timene, med kulingvarsel når det trengs.', 'The coast radio sends local forecasts on VHF at 09, 12, 15, 18 and 21: the wind and the waves where the boat is, and how the wind goes the next twelve hours, with a gale warning when it is needed.'],
       ['Meldinger som dukker opp på skjermen, står i 10 sekunder. Fiskemottakene sender ikke lenger «God morgen» med dagens pris; prisene står i Salgslaget.', 'Messages that pop up on the screen stay for 10 seconds. The fish plants no longer send «Good morning» with the day\'s price; the prices are in Salgslaget.'],
       ['Nybygg fra verftet leveres med en gang, uten byggetid. En båt som allerede er bestilt, leveres nå.', 'New builds from the yard are delivered at once, with no building time. A vessel already on order is delivered now.'],
       ['Spillet styres fra én enhet om gangen, mens verden, klokka og driftsplanen går som vanlig, også med skjermen av. Åpner du det på en annen enhet, viser den første et kort med en gang, og du fortsetter akkurat der du slapp, med det siste som skjedde. Er den andre enheten av, tar den du åpner, over av seg selv. «Spill her i stedet» flytter spillet tilbake. Finnes det likevel to utgaver, viser valget begge med dag, penger og båt.', 'The game is run from one device at a time, while the world, the clock and the plan go on as usual, also with the screen off. Open it on another device and the first one shows a card at once, and you go on exactly where you left off, with the last thing that happened. If the other device is off, the one you open takes over by itself. «Play here instead» moves the game back. Should there still be two versions, the choice shows both with day, money and boat.'],
       ['Lagringen er tryggere når du bytter mellom enheter og faner: en fane som har stått åpen lenge, skriver ikke lenger et eldre spill over det nye, men sier fra og lar deg fortsette med spillet slik det er nå. Appen på hjemskjermen spør «Har du spilt før?» første gang, så du kan logge inn og fortsette der du slapp.', 'Saving is safer when you switch between devices and tabs: a tab left open for long no longer writes an older game over the newer one, but says so and lets you go on with the game as it is now. The app on the home screen asks «Have you played before?» the first time, so you can sign in and go on where you left off.'],
       ['Den brukte hurtigsjarken på 10,99 m har fått en ny og detaljert modell: gult skrog med hvit skansekledning, styrhus med gult tak, mast med radar og haleblokk, og et ryddig arbeidsdekk med luke og haler.', 'The used 10.99 m speed sjark has a new, detailed model: a yellow hull with white bulwarks, a wheelhouse with a yellow roof, a mast with radar and hauling block, and a tidy working deck with hatch and hauler.'],
       ['Plastsnekka på 26 fot har fått en ny og detaljert modell: klinkmønster i skroget, ruff med vinduer, vindskjerm med hardtopp over styreplassen og åpen cockpit akter.', 'The 26 ft fibreglass snekke has a new, detailed model: a clinker-look hull, a cabin with windows, a windscreen with a hard top over the helm and an open cockpit aft.'],
       ['Juksamaskinene på rekka er bygd på nytt i 3D: motorhus, åpen spole med sene, kontrollboks med skjerm og knapper mot fiskeren, og en arm ut over siden med rød blokk. Spolen rykker juksa opp og ned mens den fisker og spoler inn når det er fisk på. Alle båter utenom havflåten har dem nå på styrbord rekke når de har kjøpt maskiner.', 'The jigging machines on the rail are rebuilt in 3D: motor housing, open spool with line, a control box with display and keys facing the fisher, and an arm out over the side with a red block. The spool jerks the jig up and down while fishing and reels in when fish are on. Every boat outside the ocean fleet now carries them on the starboard rail once bought.'],
       ['Navigasjonsbaren i kartplotteren passer smale telefoner i stående format: den legger seg under kamera-øya på iPhone, og under en rute får veipunkt og ETA en egen stripe under kurs, fart, dybde og ekkolodd, så tallene ikke lenger går over hverandre.', 'The chart plotter\'s top bar fits narrow phones standing up: it sits below the camera island on iPhone, and on a route the waypoint and ETA get a strip of their own under heading, speed, depth and echo sounder, so the numbers no longer run into each other.'],
       ['Ny app på telefonen: Kaiboden samler Haill, Trim og den nye energidrikken Skippertak, en fane hver. Skippertak holder deg og mannskapet på hele flåten uthvilt i ett, to eller fire døgn, og driftsplanene går gjennom hviløktene mens den virker.', 'New app on the phone: Kaiboden gathers Luck, Tuning and the new energy drink Skippertak, a tab each. Skippertak keeps you and the crews of the whole fleet rested for one, two or four days, and the operations plans work through their rest sessions while it lasts.'],
       ['Autonav lager strammere ruter: hele ruta rettes ut der en rett etappe er trygg, også langs leia, så den ikke lenger svinger innom havner den bare passerer. Trange sund er åpne for de mindre båtene (Havøysund: 1,5 nm gjennom sundet i stedet for 7,5 rundt øya). Dybden regnes med dypgangen og den laveste vannstanden turen kan møte, så grunne sund er åpne ved flo og stengt ved fjære.', 'Autonav makes tighter routes: the whole route is straightened where a straight leg is safe, along the fairway too, so it no longer turns into harbours it only passes. Narrow sounds are open to the smaller boats (Havøysund: 1.5 nm through the sound instead of 7.5 round the island). The depth is reckoned with the draught and the lowest water the trip can meet, so shallow sounds are open at high water and shut at low.'],
       ['Fjæra i 3D er bygd om: land og sjø møtes på sjøkartets kystlinje, uten hull, trappetrinn eller brune streker i vannet. Fjæra skråner ned fra linja, så ved fjære sjø ligger tang og rur tørt og vannet står lenger ute, og ved flo står det på linja. Skumbeltet ligger på vannkanten og følger tidevannet.', 'The foreshore in 3D is rebuilt: land and sea meet on the sea chart coastline, with no holes, steps or brown lines in the water. The shore slopes down from the line, so at low tide the rockweed and barnacles lie dry and the water stands further out, and at high tide it stands on the line. The surf lies on the waterline and follows the tide.'],
       ['Fiskemottak, verft og butikker som sto ute i sjøen står nå inntil land (31 steder, mest i Troms, Finnmark og på Sørlandet). Landsdelene Vestlandet og Rogaland/Sørlandet i startlista kommer nå fram over «Start her»-linja. Kartet lastes ferdig før du slippes inn, med framdrift, og gir beskjed og «Prøv igjen» hvis nettet svikter, i stedet for å starte uten kart.', 'Fish plants, yards and shops that stood out in the sea now stand against the land (31 places, mostly in Troms, Finnmark and on the south coast). The regions Western Norway and Rogaland/the south coast in the start list now come up above the «Start here» bar. The chart is fully loaded before you are let in, with progress, and says so and offers «Try again» if the connection fails, instead of starting without a chart.'],
       ['Ny app på telefonen: Håndboka. Etter første tur kommer tipsene ett og ett, første gang noe skjer: egen rute, ekkoloddet, flo og fjære, hvile, diesel, driftsplanen, butikken, verftet, puben og mer. «Jeg kan dette» legger resten av kapittelet til ro, og i Håndboka kan du lese alle tipsene igjen og la dem peke på knappen («Vis meg»).', 'New app on the phone: the Handbook. After the first trip the tips come one by one, the first time something happens: your own route, the echo sounder, the tide, rest, diesel, the operations plan, the shop, the yard, the pub and more. «I know this» puts the rest of the chapter to rest, and in the Handbook you can read every tip again and let it point at the button («Show me»).'],
      ['Ny app på telefonen: Garderoben. Velg hår, skjegg, hatt, jakke, bukser og sko, og hudfarge og farger, og se figuren din bli kledd på mens du dreier den. Figuren din vises om bord. Mannskapet har fått hvert sitt utseende, og ingen to ser like ut: ulike frisyrer, skjegg, hatter, jakker og hudfarger, som kystfolk flest.', 'New app on the phone: the Wardrobe. Choose hair, beard, hat, jacket, trousers and shoes, and skin tone and colours, and watch your figure get dressed as you turn it. Your figure is seen aboard. The crew have each got their own look, and no two look alike: different hairstyles, beards, hats, jackets and skin tones, like coastal people generally.'],
       ['Juksa kan ikke lenger gå tapt i grov sjø. Fiskemottakene har ikke åpningstider, så du kan levere når som helst. Mannskapet har ikke lenger krav om hviletid; energien og slitenheten er som før. Liner, garn og teiner i sjøen kan fortsatt gå tapt i sterk storm.', 'The jig can no longer be lost in rough sea. The fish plants have no opening hours, so you can land at any time. The crew no longer has a rest-time requirement; energy and fatigue work as before. Line, nets and pots in the sea can still be lost in a strong storm.'],
       ['Innstillinger på telefonen har Konto øverst. Der kan du registrere deg, eller logge inn hvis du har konto fra før.', 'Settings on the phone has Account at the top. There you can register, or sign in if you already have an account.'],
       ['Spillet anbefaler nå å legge det på hjemskjermen, på iPhone og Android: etter første levering og som eget kort under Innstillinger. Fra ikonet starter det i fullskjerm, og kartet og lagringen blir værende på enheten.', 'The game now recommends putting it on the home screen, on iPhone and Android: after the first landing and as its own card under Settings. From the icon it starts in full screen, and the chart and the save stay on the device.'],
       ['Tryggere bytte mellom enheter: serveren teller lagringene, så en enhet som ikke har fått med seg det nyeste, kan ikke skrive over det. Er spillet spilt på en annen enhet, får du spørsmål om å fortsette med det siste, med hva hvert spill er. Når du kommer tilbake til spillet, sjekkes det om en annen enhet har spilt, før noe lagres. Spillet lagres også rett etter levering og avreise, og under Innstillinger › Konto står når det sist ble lagret, med «Lagre nå». Det andre spillet ligger under Tidligere lagringer.', 'Safer switching between devices: the server counts the saves, so a device that has not got the newest one cannot write over it. If the game has been played on another device you are asked whether to go on with the latest, with what each game is. When you come back to the game it checks whether another device has played before anything is saved. The game is also saved right after a landing and casting off, and under Settings › Account it says when it was last saved, with «Save now». The other game is kept under Earlier saves.'],
       ['Kortet som ber om registrering etter første levering kommer nå igjen hvis noe annet dekket det.', 'The card asking you to register after the first landing now comes again if something else covered it.'],
       ['Registrering er nå ett trykk: ingen felt før innloggingen. Brukernavnet foreslås for deg etterpå, og båten kan døpes i samme kort. På åpningsskjermen står «Har du spilt før? Logg inn» øverst til høyre. Åpner ikke innloggingen, får du beskjed, og spillet ditt ligger trygt.', 'Registering is now one tap: no fields before the sign-in. A player name is suggested for you afterwards, and the boat can be named in the same card. The opening screen has «Played before? Sign in» at the top right. If the sign-in does not open you are told, and your game is safe.'],
      ['Andre spillere ser nå figuren din og mannskapet ditt, med hår, hatt og klær, når de seiler forbi deg.', 'Other players now see your figure and your crew, with hair, hat and clothes, when they sail past you.'],
      ['Mannskapet sier fra når dieselen går under en fjerdedel og igjen under ti prosent, og når du selv er sliten og har under 25 % energi. Hver ting høyst én gang i døgnet.', 'The crew speaks up when the diesel falls under a quarter and again under ten per cent, and when you are worn out with under 25% energy. Each at most once a day.'],
      ['Mannskapet egner liner, bytter kroker og reparerer line og teiner også mens driftsplanen går, så lenge de ikke har noe annet å gjøre. Garn bøtes på sjøen bare når planen ikke fisker med garn.', 'The crew now baits lines, changes hooks and mends lines and pots while the operations plan runs, whenever they have nothing else to do. Nets are mended at sea only when the plan does not fish with nets.'],
      ['Når mannskapet er ferdig med å egne, bytte kroker eller bøte, kommer meldingen nå fra «Om bord» og ikke fra kaia, også når jobben gjøres på sjøen.', 'When the crew has finished baiting, changing hooks or mending, the message now comes from «Aboard» and not from the quay, also when the job is done at sea.'],
    ]],
    ['p103', '09.10.2026', 'Været flytter seg langs kysten', 'The weather moves along the coast', [
       ['Fars torsk henger i naustet: 24,6 kg, stoppet ut og montert over trofeveggen. Trykk på den, så får du historien, og får du en større, henger din ved siden av.', 'Father’s cod hangs in the boathouse: 24.6 kg, stuffed and mounted over the trophy wall. Tap it for the story, and land a bigger one and yours hangs beside it.'],
       ['Første tur begynner inne i fars naust. Du går ut, ser båten for første gang og legger fra kai med ett trykk på feltet. Underveis prøver du kino, bro og kikkert, og på vei inn får du kurslista, appene (vær, priser, regler, redning) og hva været betyr for båten. Ved sluttseddelen kan du skrive under i eget navn, og på kaia står en som vil mønstre på hvis du vil ha selskap i båten.', 'The first trip begins inside Father’s boathouse. You step out, see the boat for the first time and cast off with one tap on the ground. On the way you try the cinema, bridge and binoculars, and on the way in you get the course list, the apps (weather, prices, rules, rescue) and what the weather means for the boat. At the landing note you can sign in your own name, and on the quay stands someone who wants to sign on if you want company aboard.'],
       ['Når du velger hvor fars naust står, viser lista bare steder der været holder for første tur de neste timene. Steder med uvær står grått, med når det ventes å løye. Under første tur snur ikke båten av seg selv for været.', 'When you choose where Father’s boathouse stands, the list only offers places where the weather holds for the first trip the next hours. Places with heavy weather are grey, with when it is expected to ease. On the first trip the boat does not turn back by itself for the weather.'],
       ['Lavtrykkene kommer inn fra havet i sørvest og går nordover langs kysten med hvert sitt spor og hver sin fart. En storm når Vestlandet først og Finnmark et døgn senere, og det kan være storm ett sted og stille et annet. Vinden dreier forskjellig etter hvilken side av lavtrykket du er på.', 'The lows come in from the sea in the south-west and travel north along the coast, each on its own track and at its own speed. A gale reaches Western Norway first and Finnmark a day later, and there can be a storm in one place and calm in another. The wind turns differently depending on which side of the low you are.'],
       ['Snøen faller og smelter dag for dag der du er: den legger seg i kulda, ligger lenger til fjells og forsvinner flekkvis om våren. Bergen har sjelden snø ved sjøen, Nord-Norge har den ned til fjæra hele vinteren.', 'The snow falls and melts day by day where you are: it settles in the cold, stays longer up the hills and goes in patches in spring. Bergen rarely has snow by the sea, Northern Norway has it down to the shore all winter.'],
       ['Årstidene skifter gradvis: bjørka får løv når våren har vært varm nok, gresset grønnes, og om høsten gulner løvet og faller, tidligere i nord enn i sør.', 'The seasons change gradually: the birch comes into leaf when the spring has been warm enough, the grass turns green, and in autumn the leaves turn yellow and fall, earlier in the north than in the south.'],
    ]],
    ['p102', '09.10.2026', 'Kjentmannen, nordlyset og driftsplanen', 'The old hand, the northern lights and the operations plan', [
       ['Ny nattehimmel: stjernene står der de står på den ekte himmelen og dreier rundt Polarstjerna gjennom natta, i ulike størrelser og farger, og de blinker mer lavt på himmelen. Melkeveien går over himmelen med mørke støvfelt, og langs horisonten ligger en svak grønn luftglød.', 'A new night sky: the stars stand where they are in the real sky and turn round the Pole Star through the night, in different sizes and colours, twinkling more low in the sky. The Milky Way crosses the sky with dark dust lanes, and a faint green airglow lies along the horizon.'],
       ['Nordlyset er mykere i kantene og ser like bra ut fra alle kanter. Det blir ikke lenger til skarpe, sikksakkete bånd når du ser langs det.', 'The northern lights are softer at the edges and look as good from every side. They no longer turn into sharp zigzag bands when you look along them.'],
       ['CHIRP-ekkoloddet viser ikke lenger anslått fangst. Trykk på arten i ekkoloddboksen, så åpnes en liten liste der du velger hvilken art ekkoloddet viser.', 'The CHIRP echo sounder no longer shows an estimated catch. Tap the species in the echo sounder box to open a small list and pick the species it shows.'],
       ['Utsettsmenyen for liner og garn får plass i stående format, og ekkoloddet står i navigasjonsbaren øverst også på smale skjermer, ikke oppå kartet.', 'The menu for setting lines and nets fits when the screen is upright, and the echo sounder stays in the navigation bar at the top on narrow screens too, not on the chart.'],
      ['Når du zoomer langt ut, kommer ikke havet lenger gjennom lavt land langs kysten i blågrønne striper.', 'Zoomed far out, the sea no longer shows through low land along the coast in teal stripes.'],
      ['Du er skipper på din egen båt: i Driftsplan er «Meg» valgt som skipper når du er om bord, og mannskapet er mannskap. Er du ikke om bord, kjører den du velger av mannskapet.', 'You are the skipper of your own boat: in the Operations plan «Me» is the skipper when you are aboard, and the crew are crew. When you are not aboard, the one you pick from the crew runs it.'],
      ['Driftsplanen ser nå på sjøen der turen faktisk går (i fjorden er det roligere enn ute på havet), ikke bare på havet utenfor. Blir båten likevel liggende, sier skipperen hva som er over grensen, og om det er båtens egen grense som stopper turen.', 'The operations plan now looks at the sea where the trip actually goes (calmer in the fjord than out at sea), not only the open sea outside. If the boat still stays in, the skipper says what is over the limit, and whether it is the boat\u2019s own limit that stops the trip.'],
      ['Ruten fra fars naust ble meldt som «krysser land» fordi kontrollen regnet fra mottakets kai i stedet for fra naustet. Nå regnes den fra der båten faktisk ligger.', 'A route from Father\u2019s boathouse was flagged as crossing land because the check started at the plant\u2019s quay instead of the boathouse. It now starts where the boat actually lies.'],
      ['Fars naust står aldri lenger oppå kaier, moloer eller båter som ligger til kai. Står det et sted der noe er i veien, flyttes det til en ledig plass i nærheten.', 'Father\u2019s boathouse no longer stands on quays, breakwaters or moored boats. Where something is in the way, it moves to a free spot nearby.'],
      ['Lyd i naustet: inne dempes havet og været av veggen. Vedovnen knitrer og knirker, taket drypper så lenge det lekker, og regnet tromler på taket.', 'Sound in the boathouse: inside, the sea and the weather are muffled by the wall. The wood stove crackles, the roof drips as long as it leaks, and the rain drums on the roof.'],
      ['Naustet har fått et rom du kan gå inn i: trykk Naustet når du ligger ved fars naust. På trofeveggen henger den største fisken du har fått av hver art, med vekt, dato og sted. Taket, ovnen, benken og veggen ser du i rommet og kan sette i stand derfra.', 'The boathouse now has a room you can step into: tap Boathouse when you lie at Father\u2019s boathouse. On the trophy wall hangs the biggest fish you have landed of each species, with weight, date and place. You see the roof, the stove, the bench and the wall in the room and can set them to rights from there.'],
      ['Utstyr du får i gave (for eksempel brovaktsalarm) er montert med en gang. Ingen ventetid hos verftet.', 'Equipment you get as a gift (a bridge watch alarm, for example) is fitted at once. No wait at the yard.'],
      ['Rekordfisk: trofeveggen i fars naust og Rekordfisk-fanen viser nå den største fisken du har fått av hver art, med vekt, dato, sted, båt og redskap, også kongekrabbe. Fars notatbok og drømmefisken er tatt ut.', 'Record fish: the trophy wall in Father\u2019s boathouse and the Record fish tab now show the biggest fish you have landed of each species, with weight, date, place, boat and gear, king crab too. Father\u2019s notebook and the dream fish are gone.'],
      ['Når mannskapet egner, reparerer kroker eller bøter utstyr ved kai, står det nå «Mannskapet jobber til» i stedet for «Verksted til». Verkstedet nevnes bare når verftet faktisk jobber på båten.', 'When the crew baits, mends hooks or nets at the quay, it now says «Crew working until» instead of «Yard until». The yard is only named when the yard really is working on the boat.'],
      ['Slep mellom spillere vises nå i 3D: tauet går fra båten som sleper til den som blir slept, og båtene ligger 30 meter fra hverandre.', 'Towing between players now shows in 3D: the line runs from the towing boat to the one in tow, and the boats lie 30 metres apart.'],
      ['Slep mellom spillere: har båten stoppet, kan du spørre andre spillere innenfor 30 nm om slep i Redning-appen. Det er gratis for deg. Den som hjelper, får 25 000 kr når båten er slept til havn. Tar ingen det innen 20 minutter, kommer redningsskøyta.', 'Towing between players: if your boat has broken down, you can ask other players within 30 nm for a tow in the Rescue app. It is free for you. The one who helps gets NOK 25,000 when the boat is towed to harbour. If nobody takes it within 20 minutes, the rescue boat comes.'],
      ['Mannskapet jobber på sjøen: egning av line, bytte av kroker og bøting av garn og teiner går nå også mens båten går eller ligger i ro, når mannskapet er ledig. Jobben venter mens dere fisker og sløyer. Mannskapet sier fra når kroker eller agn begynner å ta slutt, og når redskapen er sliten.', 'The crew works at sea: baiting lines, changing hooks and mending nets and pots now also go on while the boat is under way or lying still, when the crew is free. The job waits while you fish and gut. The crew tells you when hooks or bait run low, and when the gear is worn.'],
      ['Tut og hilsener på sjøen: med en annen spillers båt innenfor 1 nautisk mil kommer «Tut» blant knappene, og den andre hører hornet. Båtkortet til en spiller innenfor 5 nm har seks faste hilsener. Det du får, kommer i meldingene og som tekst over båten i 3D.', 'Horns and hails at sea: with another player\'s boat within 1 nautical mile, «Horn» comes among the buttons and the other player hears it. The boat card of a player within 5 nm has six set greetings. What you get comes to your messages and as text over the boat in 3D.'],
      ['Gjestebøker i pubene og rorbuene langs kysten: skriv deg inn med en hilsen, og se hvem som har vært der før deg. Gjestebøkene du har skrevet i, samles i Kystfareren i Milepæler, landsdel for landsdel.', 'Guestbooks in the pubs and rorbuer along the coast: sign with a greeting, and see who has been there before you. The guestbooks you have signed are gathered in Coastfarer in Milestones, part of the coast by part.'],
      ['Del fangstmerker: trykk på et av dine egne fangstmerker i kartet og del det med vennene dine eller fiskarlaget. De ser det i kartet med navnet ditt i et døgn, og kan legge rute dit. Du kan dele fem merker i døgnet.', 'Share catch marks: tap one of your own catch marks on the chart and share it with your friends or the fishing club. They see it on the chart with your name for a day, and can route there. You can share five marks a day.'],
      ['Flere merker i Milepæler: fisk tatt, turer fullført, havner, verft, utstyrsbutikker, rorbuer og puber besøkt, og venner. Hvert trinn gir en gave.', 'More badges in Milestones: fish caught, trips completed, harbours, yards, tackle shops, rorbuer and pubs visited, and friends. Each step gives a gift.'],
      ['Ny app: Venner (der Folk var). Legg til en venn med vennekoden, ved å trykke på båten deres i kartet, eller i puben. Venner ser båten til hverandre i kartet i grønt, uansett hvor langt unna, og der den sist lå når spillet er lukket. Bonusen for fast kunde på mottakene står nå i Salgslaget.', 'New app: Friends (where People was). Add a friend with their friend code, by tapping their boat on the chart, or in the pub. Friends see each other\'s boat on the chart in green, however far apart, and where it last lay while the game is closed. The regular customer bonus at the plants is now in Sales.'],
      ['Merker-appen heter nå Milepæler og samler alt du har oppnådd: første uke, merkene, rekordfisken, det du har hørt fra gamle dager og tatoveringene. Sjømann-appen er borte. Papirene (blad B, ervervstillatelsen og foretaket) står i Kvote. Når du stifter rederiet, åpner Rederi-appen, og foretaket står der.', 'The Badges app is now Milestones and gathers all you have achieved: the first week, the badges, the record fish, what you have heard of the old ways and the tattoos. The Seaman app is gone. The papers (blad B, the fishing permit and the business) are in Quota. When you found the company, the Company app opens with the business in it.'],
      ['Fars notatbok og medene hans i kartet er tatt bort. Istandsettingen av naustet og trofeveggen finner du under Naustet når du ligger ved fars naust.', 'Father\'s notebook and his marks on the chart are gone. Setting the naust to rights and the trophy wall are under Naustet when you lie at Father\'s naust.'],
      ['Rettet: fiskebåtene, hurtigbåten og ferja ved Senja vistes i kartet uansett hvor langt unna du var. Nå vises de bare innen AIS-rekkevidden, som alle andre båter.', 'Fixed: the fishing boats, the express boat and the ferry at Senja showed on the chart however far away you were. Now they show only within AIS range, like every other boat.'],
      ['Rettet: veiene i byene (som i Tromsø) blinket av og på i kartplotteren når båten var langt unna.', 'Fixed: the roads in towns (as in Tromsø) blinked on and off in the chart plotter when the boat was far away.'],
      ['Søk i kartplotteren: trykk på forstørrelsesglasset og skriv et sted, et mottak, et verft, en rorbu, en fjord eller en posisjon. Kartet går dit, og «Autonav hit» legger ruta.', 'Search in the chart plotter: tap the magnifier and type a place, a fish plant, a yard, a rorbu, a fjord or a position. The chart goes there, and «Autonav here» lays the route.'],
      ['Den lille kartplotteren i 3D viser bunnen som den store: dybdelinjer, dybdetall og dybden i farger.', 'The little chart plotter in 3D shows the bottom as the big one does: depth lines, soundings and the depth in colours.'],
      ['Rederi-appen har fått et regnskap: inntekter, kostnader og resultat, hvert lån med restgjeld, rente, terminbeløp og betalte renter, og en balanse med flåtens verdi, gjeld og egenkapital.', 'The Company app has accounts: revenue, costs and result, each loan with its balance, rate, instalment and interest paid, and a balance sheet with the fleet\'s value, debt and equity.'],
      ['Rettet: når du drar i kartet med fingeren, står landet ikke lenger igjen mens navnene og båtene flytter seg, og det blir ikke tomme felt i kanten.', 'Fixed: when you drag the chart with a finger, the land no longer stays behind while the names and boats move, and no empty bands appear at the edge.'],
      ['Kartplotteren henter sjøkartet der du ser først, og tegner ikke hele kartet på nytt for hver bit som kommer. En linje øverst viser hvor langt den er kommet. Ruta du legger, hentes til enheten på forhånd.', 'The chart plotter fetches the chart where you look first, and no longer redraws the whole chart for every piece that arrives. A line at the top shows how far it has come. The route you lay is fetched to the device beforehand.'],
      ['Driftsplanen: velg opptil tre juksplasser etter hverandre. Mannskapet flytter seg når fangsten faller. Dagskortet viser når båten går ut igjen etter en levering. Er mottaket stengt når dagen er ferdig, hviler mannskapet ved kaia og leverer når det åpner, før neste tur.', 'Operations plan: choose up to three jig places in turn. The crew move on when the catch falls. The day card shows when the boat goes out again after a landing. If the plant is closed when the day is done, the crew rest at the quay and land when it opens, before the next trip.'],
      ['Kjentmannen ved disken på puben har vært ute med ekkoloddet. Én gang hver dag forteller han for spillpenger hvor arten du spør om står best innen 10 km, og hva annet som står der. Plassen står som et merke i kartet resten av dagen.', 'The old hand at the bar in the pub has been out with his echo sounder. Once a day, for game money, he tells you where the species you ask about stands best within 10 km, and what else is there. The place is a mark on the chart for the rest of the day.'],
      ['Nordlyset henger ikke lenger som et rett teppe over himmelen. Gardinene bøyer seg i buer og S-folder, brytes opp i biter, og underkanten bølger. Ser du en fold fra siden, ser du den to ganger, som i virkeligheten.', 'The northern lights no longer hang like a straight carpet across the sky. The curtains bend in arcs and S-folds, break into pieces, and the lower edge ripples. Seen from the side, a fold shows twice, as in real life.']]],
    ['p101', '09.10.2026', 'Kjølvann og kaier', 'Wake and quays', [
      ['Rettet: en hvit strek gikk på tvers av vannet ved hekken der hekkbølgen starter. Bølgen vokser nå jevnt fram bak båten.', 'Fixed: a white line ran across the water at the stern where the stern wave starts. The wave now grows smoothly behind the boat.'],
      ['Rettet: kaiflater fra kartet viste seg gjennom kaia ved utstyrsbutikker, verft og mottak, som i Hammerfest. Den delen som ligger under kaia, tegnes ikke lenger.', 'Fixed: quay areas from the map showed through the quay at tackle shops, yards and plants, as in Hammerfest. The part under the quay is no longer drawn.'],
      ['Rettet: navnet på havsjarken sto over et koøye i baugen. Nå står navnet dit ingenting stikker ut fra skutesida, på alle båter.', 'Fixed: the name on the sjark sat over a porthole in the bow. Now the name stands where nothing sticks out from the side, on every boat.'],
      ['Rettet: moloer og brygger fra kartet som gikk inn i havna ved et mottak eller verft, er tatt bort der.', 'Fixed: breakwaters and piers from the map that ran into the harbour at a plant or yard are gone there.'],
    ]],
    ['p100', '09.10.2026', 'Puben i bygda', 'The pub in the bygd', [
      ['Trykk på Pub i bygda, så sitter du på en krakk ved bardisken. Dra med fingeren for å se deg rundt, og trykk på det du vil.', 'Tap Pub in the bygd and you sit on a stool at the bar. Drag with a finger to look around, and tap what you like.'],
      ['Lykkehjulet henger på veggen og snurrer når du spanderer en runde, én gang hver kveld som før.', 'The wheel hangs on the wall and spins when you buy a round, once each evening as before.'],
      ['Bartenderen prater på stedets dialekt og vet hvor de betaler godt i dag. Har du mannskap, kan du spandere en runde på dem, og stemningen om bord stiger.', 'The bartender talks in the local dialect and knows where they pay well today. With a crew, you can buy them a round, and the mood aboard rises.'],
      ['På oppslagstavla henger Kystposten, ukas beste fiskere og turoppdragene. Ved det runde bordet sitter folk som ser etter hyre.', 'The notice board has Kystposten, the week\'s best fishers and the trip jobs. At the round table sit people looking for a berth.'],
      ['Se hvem som ligger i havna i kveld og hils på dem. Bli med i fiskarlaget i havna: laget har et felles mål hver uke, og alle får sin del når det nås.', 'See who lies in the harbour tonight and greet them. Join the harbour\'s fishing club: the club has a shared goal each week, and everyone gets a share when it is reached.'],
      ['Ny quiz på tavla hver uke, med fem spørsmål om fisk, sjø og kyst.', 'A new quiz on the board every week, with five questions about fish, sea and coast.']]],
    ['p99', '09.10.2026', 'Ny driftsplan: fem spørsmål', 'New operations plan: five questions', [
      ['Rettet: båten ristet i bro-visningen, verst i fart. Kameraet sitter nå helt fast i båten.', 'Fixed: the boat shook in the bridge view, worst at speed. The camera now sits firmly fixed to the boat.'],
      ['Driftsplanen lages nå med fem enkle spørsmål, ett om gangen: hvor båten hviler, hva den fisker med, hvor redskapet står og hvor dere jukser, hvor tøft vær den går ut i, og når dagen starter. Planen legger selv turene, stasjonene og leveringene.', 'The operations plan is now made with five simple questions, one at a time: where the boat rests, what she fishes with, where the gear stands and where you jig, how rough a weather she goes out in, and when the day begins. The plan lays out the trips, stations and landings itself.'],
      ['Arbeidsdagen holdes innenfor 14 timer, og mannskapet får alltid 10 timer hvile i strekk på hvileplassen før neste tur. Hindrer været turen hjem, hviler båten der den ligger.', 'The working day is kept within 14 hours, and the crew always get 10 hours of rest in one stretch at the resting place before the next trip. If the weather keeps her from going home, she rests where she lies.'],
      ['Rettet: å velge plass i kartet til driftsplanen og så avbryte flyttet startpunktet for ruter og Autonav til hvileplassen. Nå starter ruta alltid der båten er, og det finnes alltid en Avbryt-knapp.', 'Fixed: choosing a place in the chart for the plan and then cancelling moved the start of routes and Autonav to the resting place. Now the route always starts where the boat is, and there is always a Cancel button.'],
      ['Line kan settes, jukses rundt og trekkes samme dag. Garn og teiner trekkes og settes på nytt én gang i døgnet. Plassene du velger, avgjør fangsten, og fangstrapporten viser snitt og beste døgn etter hvert. Den gamle detaljvisningen ligger under «Flere valg».', 'Line can be set, jigged around and hauled the same day. Nets and pots are hauled and set again once a day. The places you choose decide the catch, and the catch report shows the average and best day as it goes. The old detailed view is under «More choices».']
    ]],
    ['p98', '09.10.2026', 'Jukse mens redskapet står', 'Jig while the gear stands', [
      ['Juksa er nå alltid med når båten ligger i ro, også når den er rigget for line, garn eller teiner. Når redskapet står i sjøen, kan mannskapet jukse i dødtiden. Under setting og haling går båten, og da jukses det ikke.', 'The jig is now always there when the boat lies still, also when she is rigged for line, nets or pots. While the gear stands in the sea the crew can jig in the dead time. While setting and hauling the boat is moving and there is no jigging.'],
      ['Plass i lasterommet holdes av til det redskapet i sjøen ventes å gi, så juksefangsten ikke fyller båten før redskapet er trukket. Rigg-valget heter nå «Bare juksa» når du ikke har noe redskap ute.', 'Room in the hold is kept for what the gear in the sea is expected to bring, so the jig catch does not fill the boat before the gear is hauled. The rig choice is now called «Jigging only» when you have no gear out.']
    ]],
    ['p97', '09.10.2026', 'Nye oppgraderinger på verftet', 'New upgrades at the yard', [
      ['Verftet bygger nå om selve båten i flere trinn: lugarer, messe og bysse, tørkerom og bad, isolert lasterom, større drivstofftank og stabilisering (slingrekjøl, og gyrostabilisator på de store båtene). Hver oppgradering finnes bare der båten har plass til den: lugar, messe og tørkerom bare på båter med køyer.', 'The yard now rebuilds the boat itself in steps: cabins, mess and galley, drying room and shower, insulated hold, a larger fuel tank and stabilisation (bilge keels, and a gyro stabiliser on the big boats). Each upgrade is only offered where the boat has room for it: cabins, mess and drying room only on boats with bunks.'],
      ['Bedre lugarer gjør at mannskapet blir mindre sliten på sjøen. En bedre bysse gir raskere mat og bedre humør. Tørkerom tar litt av kulden. Isolert lasterom sparer is, og stabilisering gjør at båten mister mindre fart i sjø.', 'Better cabins make the crew less tired at sea. A better galley gives faster meals and better spirits. A drying room takes some of the cold. An insulated hold saves ice, and stabilisation makes the boat lose less speed in a sea.'],
      ['Prisen på alle ombygginger følger båtens verdi, så en stor båt koster langt mer å bygge om enn en liten. Lasteromsutvidelsen er justert ned (+20 %, +40 % og +70 %), og en større motor gir +10 % og +20 % kraft mot mer diesel og dyrere service.', 'The price of every rebuild follows the boat\'s value, so a big boat costs far more to rebuild than a small one. The hold enlargement is tuned down (+20%, +40% and +70%), and a bigger engine gives +10% and +20% power for more diesel and a dearer service.']
    ]],
    ['p96', '08.10.2026', 'Driftsplan, og ryddigere knapper', 'Operations plan, and clearer buttons', [
      ['Appen Drift heter nå Driftsplan. Knappene for utstyr, dager og innstillinger er lette å lese også når de ikke er valgt, og bare de som ikke er klare ennå har stiplet ramme.', 'The Drift app is now called Operations plan. The buttons for gear, days and settings are easy to read even when not selected, and only those not ready yet have a dashed frame.'],
      ['Halerne heter nå bare linehaler, garnhaler og teinehaler. Den elektriske 12 V-haleren er borte; linehaler og teinehaler passer på alle båter.', 'The haulers are now just line hauler, net hauler and pot hauler. The electric 12 V hauler is gone; the line hauler and pot hauler fit every boat.'],
      ['Line, garn og teiner kan bare kjøpes når båten har haleren til dem. Kroker, blåsesett, dregger og agn kjøpes først når du eier utstyret de hører til.', 'Line, nets and pots can only be bought once the boat has the hauler for them. Hooks, buoy sets, anchors and bait are bought only once you own the gear they go with.'],
      ['Når telefonen åpnes igjen, starter den på hovedmenyen.', 'When the phone is opened again it starts on the home screen.'],
      ['Fem fiskemottak, verft og butikker ved broer er flyttet til nærmeste kai uten bro.', 'Five plants, yards and shops next to bridges have moved to the nearest quay without a bridge.']
    ]],
    ['p95', '08.10.2026', 'Utstyr som slites, og service i utstyrsbutikken', 'Gear that wears, and service at the tackle shop', [
      ['Lina har status: selve lina og krokene (i orden, bøyde og manglende). Nye liner kommer komplette. Slitte kroker byttes mot kroker du har kjøpt, og friske kroker fisker 5 % bedre de første trekkene. Er lina selv utslitt, lønner det seg å selge den og kjøpe ny.', 'The line has a status: the line itself and the hooks (fine, bent and missing). New line comes complete. Worn hooks are changed from hooks you have bought, and fresh hooks catch 5 % better for the first hauls. When the line itself is worn out, it pays to sell it and buy a new one.'],
      ['Kroker kjøpes i pakker på 100, 500 og 1000 i utstyrsbutikken og ligger i Beholdning sammen med resten av utstyret. Der ser du også status og tak for garn, line, teiner og juksa, og en oversikt over agnet om bord.', 'Hooks are bought in packs of 100, 500 and 1000 at the tackle shop and sit in Inventory with the rest of the gear. There you also see the condition and ceiling of nets, line, pots and the jig, and an overview of the bait aboard.'],
      ['Ny Service-knapp hos utstyrsbutikken: butikken reparerer line, bøter garn, reparerer teiner og bytter kroker på halve tiden mot et gebyr, og kjøper utstyret tilbake til en firedel av nypris ganger standen. Hver reparasjon senker taket litt, så alt må byttes ut en gang.', 'A new Service button at the tackle shop: the shop mends line, mends nets, mends pots and changes hooks in half the time for a fee, and buys the gear back at a quarter of the new price times its condition. Every repair lowers the ceiling a little, so everything has to be replaced once.'],
      ['Mannskapet vedlikeholder selv i havn når de ikke har noe annet å gjøre, så lenge du har kroker på lager. Det kan slås av i Beholdning.', 'The crew does the upkeep itself in port when they have nothing else to do, as long as you have hooks in the store. It can be turned off in Inventory.'],
      ['Pilk og markkroker til juksa og kveitepilken kjøpes som sett, slites ved fiske og byttes. Du velger i Beholdning hva du fisker med.', 'Pilk with fly hooks and the halibut pilk for the jig are bought as sets, wear with fishing and are changed. You choose under Inventory what to fish with.'],
      ['Du kan ikke kjøpe flere blåsesett og dregger enn du har line, garn og teiner til å bruke dem på.', 'You cannot buy more buoy sets and anchors than you have line, nets and pots to use them on.'],
      ['«Klargjøring til neste tur» er tatt ut av Vedlikehold på verftet.', '«Getting ready for the next trip» is gone from Maintenance at the yard.']]],
    ['p94', '08.10.2026', 'Krabbeteiner: én størrelse, plass etter båten', 'Crab pots: one size, room by the boat', [
      ['Det er nå bare én krabbeteine, den store (1,55 × 1,45 × 1,07 m). Den heter «Krabbeteiner». Små teiner du hadde, er blitt store.', 'There is now one crab pot, the big one (1.55 × 1.45 × 1.07 m). It is called "Crab pots". Any small pots you had have become big ones.'],
      ['Hyselina har nå 600 kroker per stamp (en stamp rommer 200–600, etter Fiskeridirektoratets redskapshefte), og et garn er 28 m. Kystbåtene har høyst 33 stamper (ca. 20 000 kroker), og den eldre 21-meteren har plass til 240 garn.', 'Haddock line now has 600 hooks a tub (a tub holds 200–600, after the Directorate of Fisheries gear booklet), and a net is 28 m. The coastal boats have at most 33 tubs (about 20,000 hooks), and the older 21 m boat has room for 240 nets.'],
      ['Kartet prøver på nytt hvis en kartpakke ikke kommer fram ved oppstart, i stedet for å stoppe på «Kartet lastet ikke».', 'The map tries again if a map pack does not arrive at start-up, instead of stopping at "The map did not load".'],
      ['Én lagring: har du spilt på to enheter, fortsetter spillet som har kommet lengst av seg selv, og det andre tas vare på under Innstillinger › Tidligere lagringer. Starter ikke spillet, kan du prøve igjen, starte uten 3D eller hente forrige lagring.', 'One save: if you have played on two devices, the game that has come furthest goes on by itself, and the other is kept under Settings › Earlier saves. If the game does not start, you can try again, start without 3D or take back the save before.'],
      ['Nytt bilde på innlastingsskjermen og innloggingen: sjarken fra app-ikonet i blåtimen, med de samme tekstene som før.', 'A new picture on the loading and sign-in screens: the sjark of the app icon at the blue hour, with the same texts as before.'],
      ['Snur båten av seg selv fordi vinden eller sjøen går over grensen, står det nå på skjermen hvorfor og hvor du kan endre grensen (Innstillinger › Snu ved).', 'When the boat turns back by itself because the wind or sea passes the limit, the screen now says why and where to change the limit (Settings › Turn back at).'],
      ['Brygger, kaiflater og veier fra kartet tegnes ikke lenger gjennom kaiene ved mottak, verft og butikker, eller gjennom rorbuer. Båtene seiler heller ikke inn i dem.', 'Piers, quay slabs and roads from the map are no longer drawn through the quays at receivers, yards and shops, or through rorbuer. The boats no longer sail into them.'],
      ['Ekkoloddet og fangstmerkene følger redskapet du er rigget for: juksa viser kg i timen, garn, line og teiner viser hvor mange kilo ett garn, én stamp eller én teine gir etter 24 timer, og fargene viser fangsten mot det redskapet vanligvis gir. Merket etter et trekk viser kilo per enhet og ståtiden.', 'The echo sounder and the catch marks follow the gear you are rigged for: the jig shows kg an hour; nets, line and pots show how many kilos one net, one tub or one pot gives after 24 hours, and the colours show the catch against what the gear usually gives. The mark after a haul shows kilos per unit and the soak.'],
      ['Spillet starter igjen for spillere som logger inn på en ny maskin med en lagring fra skyen, og 3D-visningen stopper ikke lenger av en mesh som ikke er bygd ennå.', 'The game starts again for players who sign in on a new machine with a cloud save, and the 3D view no longer stops on a mesh that is not built yet.'],
      ['To nye agn til linene: sild og lodde (best på hyse) og blekksprut (best på lange og brosme). Kroken avgjør hvilken fiskefamilie linen tar, agnet hvilken art.', 'Two new baits for the lines: herring and capelin (best for haddock) and squid (best for ling and tusk). The hook picks the family of fish the line takes, the bait the species.'],
      ['To nye garntyper i utstyrsbutikken: flytegarn (156 og 180 mm), som tar mest sei, og blåkveitegarn (360 mm), som tar blåkveite og kveite. Lenker av ulik type kan ikke slås sammen.', 'Two new kinds of net in the tackle shop: floating nets (156 and 180 mm), which take mostly saithe, and halibut nets (360 mm), which take Greenland halibut and halibut. Strings of different kinds cannot be joined.'],
      ['Hvor mange teiner en båt har plass til, følger nå dekket: fra 4 på skiffen til 30 på de to kystbåtene, som er grensen per fartøy. Teinene må trekkes med teinehaler.', 'How many pots a boat has room for now follows the deck: from 4 on the skiff to 30 on the two coastal boats, which is the limit per vessel. The pots must be hauled with a pot hauler or an electric hauler.']
    ]],
    ['p93', '08.10.2026', 'Drift: driftplan for hver båt', 'Drift: an operations plan for every boat', [
      ['Ny app, Drift, for driftsplanen til hver båt du eier. Du lager økter: turer med egen rute og avgangstid, og hvile ved kai eller rorbu. Flere turer i døgnet er mulig, så du kan levere mer fisk per døgn.', 'A new app, Drift, for the operations plan of each boat you own. You make sessions: trips with their own route and departure time, and rests at a quay or a rorbu. Several trips a day are possible, so you can land more fish per day.'],
      ['Én type utstyr per plan: juksa, line, garn eller teiner. Ved line, garn og teiner er ståtiden tiden mellom to runder, og appen sier fra om den blir for kort eller for lang. Trål, ringnot og snurrevad kommer med havsteget.', 'One type of gear per plan: jigging, longline, nets or pots. With line, nets and pots the soak is the time between two rounds, and the app tells you if it gets too short or too long. Trawl, purse seine and Danish seine come with the ocean step.'],
      ['«Tegn rute» åpner kartplotteren med start der turen begynner, ikke der båten ligger nå. Planen må ende der den begynner for å bli godkjent.', '"Draw route" opens the chart plotter starting where the trip begins, not where the boat lies now. The plan must end where it begins to be approved.'],
      ['Du setter grenser for vind og sjø. Blir været verre mens båten er ute, går den til nærmeste kai. Du velger selv om den skal bunkre is, diesel og agn på mottaket.', 'You set limits for wind and sea. If the weather worsens while the boat is out, it goes to the nearest quay. You choose whether it stocks ice, diesel and bait at the plant.'],
      ['Oversikten viser arbeidstid, turer og hvile i døgnet på en tidslinje. «Test planen» viser dagen time for time uten å sette båten i gang. Lagre planer som maler, og se dagsrapporten med levert fisk.', 'The overview shows working time, trips and rest in the day on a timeline. "Test the plan" shows the day hour by hour without starting the boat. Save plans as templates, and see the day report with the fish landed.'],
      ['Planen pauser seg selv etter tre mislykkede forsøk på rad, og sier hvorfor.', 'The plan pauses itself after three failed attempts in a row, and says why.'],
      ['Alle båter kan ligge til ankers: «Kast anker» i dokka når du er på sjøen. Ankeret holder så lenge været er innenfor det båten tåler, og slepper i vær over grensene. Er noen våkne, kastes det på nytt; i kuling går båten til nærmeste kai. I Drift kan en hviløkt legge seg til ankers nær havna, med skjermingen og grensene vist. Kai er standard.', 'Every boat can lie at anchor: "Drop anchor" in the dock when you are at sea. The anchor holds as long as the weather is within what the boat can take, and drags in weather over the limits. If someone is awake it is dropped again; in a gale the boat heads for the nearest quay. In Drift a rest can lie at anchor near the harbour, with the shelter and limits shown. The quay is the default.'],
      ['Ankerlys og ankeralarm: ved anker lyser båten bare med det hvite rundtlyset. Slepper ankeret, ringer alarmen med sirene og rødt banner, og lyset blinker rødt. Sover du, vekkes du av alarmen.', 'Anchor light and anchor alarm: at anchor the boat shows only the white all-round light. If the anchor drags, the alarm sounds with a siren and a red banner, and the light flashes red. If you are asleep, the alarm wakes you.'],
      ['Kommer du til en rorbu med Autonav og er sliten, begynner hvilen av seg selv ved ankomst.', 'If you arrive at a rorbu by Autonav and are tired, the rest starts by itself on arrival.'],
      ['Med fire mann kan du velge døgndrift 2+2: skipper og styrmann, hver med en på dekk. Vaktene bytter hver sjette time, og de som har fri sover i køyene. En båt med køyer hviler mannskapet ved kai like fort som på en rorbu.', 'With four hands you can choose round-the-clock 2+2: a skipper and a mate, each with a deckhand. The watches change every six hours, and the watch off sleeps in the bunks. A boat with bunks rests the crew at the quay as fast as at a rorbu.']]],
    ['p92', '08.10.2026', 'Autonav går aldri på land', 'Autonav never runs you aground', [
      ['Når sluttseddelen er utbetalt, ringer kassa, beløpet stiger grønt opp fra kontoen, og summen teller seg opp.', 'When the landing note is paid, the register rings, the amount rises in green from the account, and the sum counts up.'],
      ['Arbeiderne på fiskemottaket kommenterer fangsten din med tekst over hodet: mye eller lite, kveite og kongekrabbe, ferskhet, og et spørsmål om du har glemt haillen hjemme. Replikkene er på dialekten der mottaket ligger.', 'The hands at the fish plant comment on your catch with text over their heads: much or little, halibut and king crab, freshness, and a question about whether you left your luck at home. The lines are in the dialect of the plant’s place.'],
      ['Hviletidskravet for mannskapet gjelder først når du har startet rederi. Til da kan de jobbe så lenge de har energi.', 'The crew’s rest-time rule applies only once you have started a firm. Until then they can work as long as they have energy.'],
      ['Alle aktive spillere vises på kartet, uansett hvor langt unna de er.', 'All active players show on the chart, however far away they are.'],
      ['CHIRP og sonar viser nå lyr, lange, brosme, uer, kveite og blåkveite tydelig, hver mot sitt eget nivå, og kongekrabbe er kommet med i artsvalget.', 'CHIRP and sonar now show pollack, ling, tusk, redfish, halibut and Greenland halibut clearly, each against its own level, and king crab has joined the species picker.'],
      ['Blir det for mye vind, går båten til nærmeste kai med Autonav. Under Innstillinger kan du velge «Hjem samme vei» i stedet.', 'If the wind gets too strong, the boat goes to the nearest quay by Autonav. Under Settings you can choose «Home the same way» instead.'],
      ['Kaster du loss i vind over grensen, eller trykker Stopp når båten snur, snur den ikke igjen før vinden har løyet.', 'Cast off in wind over the limit, or press Stop when the boat turns back, and it will not turn again until the wind has eased.'],
      ['Sovner du alene om bord mens Autonav går, holder autopiloten kursen og båten går fram til ruta er slutt. Før lå den og drev, og kunne drive på land mens du sov.', 'If you fall asleep alone aboard while Autonav is running, the autopilot holds the course and the boat goes on to the end of the route. Before, she drifted, and could drift ashore while you slept.'],
      ['Driver båten mens du sover (uten rute), stopper den før den når land eller grunt vann. Ingen grunnstøting i søvne.', 'If the boat drifts while you sleep (with no route), she stops before she reaches land or shallow water. No grounding in your sleep.'],
      ['Grunt vann eller et skjær på en etappe ruta kalte trygg: båten stopper 25 m før, Autonav finner en vei rundt og går videre. Finner den ingen, ligger båten stille og resten av ruta ligger klar i kartplotteren.', 'Shallow water or a skerry on a leg the route called safe: the boat stops 25 m short, Autonav finds a way round and goes on. If none is found, the boat lies still and the rest of the route is ready in the chart plotter.'],
      ['Autonav følger Kystverkets hovedleder og bileder på lange turer, også fra Oslo til Finnmark. Fra trange havner og blant holmer finner den veien ut på et finere kart.', 'Autonav follows the main and secondary fairways on long trips, even from Oslo to Finnmark. From tight harbours and among islets it finds the way out on a finer chart.'],
      ['Lange ruter lages mye raskere: leia er sjekket mot kartet på forhånd, så Oslo–Finnmark tar noen sekunder.', 'Long routes are made much faster: the fairways are checked against the chart beforehand, so Oslo to Finnmark takes a few seconds.'],
      ['Finner ikke Autonav noen vei, står det nå «Fant ingen rute dit».', 'When Autonav finds no way, it now says «Found no route there».'],
      ['Autonav legger aldri ruta gjennom vann grunnere enn båten stikker, og sjekker dybden helt fram til hvert punkt. Et trykk nær land flyttes ut til dypere vann.', 'Autonav never routes through water shallower than the boat’s draught, and checks the depth all the way to each point. A tap near the shore is moved out to deeper water.'],
      ['Fristen på et oppdrag står stille mens båten står på grunn, slepes eller ligger på slippen etterpå. Pågående oppdrag får tilbake tiden en grunnstøting kostet, opptil to døgn.', 'A mission’s deadline stands still while the boat is aground, under tow or on the slip afterwards. Missions under way get back the time a grounding cost, up to two days.'],
      ['Redningsskøyta sleper deg til nærmeste verft, ikke nærmeste havn, siden skroget skal repareres etterpå.', 'The rescue boat tows you to the nearest yard, not the nearest harbour, since the hull needs mending afterwards.'],
      ['Sitter båten fast ved kaia eller et trangt sted? I Redning-appen flytter «Flytt båten ut på trygt vann» den ut like utenfor.', 'Is the boat stuck at the quay or in a tight spot? In the Redning app, «Move the boat out to safe water» moves her out just off it.']]],
    ['p91', '08.10.2026', 'Fars naust i Vangshamn', 'Father’s boathouse at Vangshamn', [
      ['Fars naust står nå i Vangshamn på Senja, ikke i Finnsnes. Første fangst leveres i Botnhamn, like ved. Har du spilt før, er hjemmet ditt flyttet til Vangshamn, og båten ligger der du forlot den.', 'Father’s boathouse now stands at Vangshamn on Senja, not in Finnsnes. The first catch is landed at Botnhamn, close by. If you have played before, your home has moved to Vangshamn, and the boat lies where you left her.'],
      ['Kartplotteren har en liten tab på kanten av rutelisten (ÅPNE/LUKK). Ett trykk skyver listen til siden, eller ned i stående format, så du ser hele kartet mens du seiler. Tab-en blir stående igjen, og et trykk henter listen tilbake. Knappen Rute øverst til høyre er borte i stående format.', 'The chart plotter has a small tab on the edge of the route list (OPEN/CLOSE). One tap slides the list aside, or down when upright, so you see the whole chart while you sail. The tab stays out, and a tap brings the list back. The Route button at the top right is gone when upright.'],
      ['Hver slags sted har eget ikon i kartplotteren: mottak, utstyrsbutikk, verft, rorbu og fars naust. Mottakene heter stedet og «fiskemottak», «mottak» eller «fiskebruk».', 'Each kind of place has its own sign on the chart plotter: plant, tackle shop, yard, rorbu and Father’s boathouse. The plants are named by their place and «fish plant», «plant» or «fishery».'],
      ['Mottak, verft, utstyrsbutikker og rorbuer står nå lenger fra hverandre, i ly for vær og vind, og det er seilbart vann fram til dem. Verftene er tynnet ut og lagt slik at det sjelden er langt til neste, og det er én utstyrsbutikk i hver by. Rorbuene ligger et stykke fra mottaket, så du ikke trenger å velge mellom to kaier.', 'Plants, yards, tackle shops and rorbuer now stand further apart, sheltered from weather and wind, with sailable water to them. The yards are thinned out and placed so the next one is seldom far, and there is one tackle shop in each town. The rorbuer lie a way from the plant, so you do not have to choose between two quays.'],
      ['Mannskapet snakker nå sin egen dialekt etter hvor de kommer fra, og det de sier, står som tekst over hodet på dem i 3D i ti sekunder.', 'The crew now speak their own dialect from where they come from, and what they say stands as text over their heads in 3D for ten seconds.'],
      ['Dybdelinjer langs hele kysten, helt ned til 1000 meter, og dybdetall her og der i kartet, så du ser hvor dypt det er der du vil fiske. De samme linjene som rundt Senja.', 'Depth lines along the whole coast, down to 1000 metres, and depth figures here and there on the chart, so you see how deep it is where you want to fish. The same lines as round Senja.'],
      ['Knappene på kartet er like store og firkantige: start/pause, slett ruta, angre, gjør om og «min posisjon» (nå en navigasjonspil). Zoomknappene er borte; du zoomer med to fingre.', 'The buttons on the chart are all one size and square: play/pause, delete the route, undo, redo and «my position» (now a navigation arrow). The zoom buttons are gone; you zoom with two fingers.'],
      ['Startskjermen har ikke kart lenger. Øverst står stedene der det er mest å tjene akkurat nå, og du kan søke etter et sted eller bla etter landsdel for å starte nær der du bor.', 'The start screen no longer has a map. At the top are the places with most to earn right now, and you can search for a place or browse by region to start near where you live.']
    ]],
    ['p90', '07.10.2026', 'Rettelser etter tilbakemeldinger', 'Fixes from your feedback', [
      ['Verftene har fått egen, stor kai med diesel og et skipsløft: båten løftes opp av vannet på en plattform når den har skrogarbeid eller reparasjon, og settes ned igjen når jobben er ferdig. Løftet tar alle båtene, også den største pelagiske tråleren (75 m). Utstyrsbutikkene har egen kai og bygning.', 'The yards now have a big quay of their own with diesel and a ship lift: the boat is raised out of the water on a platform when it has hull work or a repair, and let down when the job is done. The lift takes every boat, the biggest pelagic seiner (75 m) too. The tackle shops have a quay and a building of their own.'],
      ['Ny app: Fiskeguide. Velg måned og se hvilke arter som gir mest, hvor de står (dyp, åpen kyst, kanter og felt), hvilket redskap og agn som virker, hva de betaler og når de er fredet. Artene med egne områder, blåkveite og kongekrabbe, merkes når det er lite av dem der du er. Du finner den også fra Sesong-appen.', 'New app: Fish guide. Pick a month and see which species give the most, where they stand (depth, open coast, edges and grounds), which gear and bait work, what they pay and when they are closed. The species with areas of their own, Greenland halibut and king crab, are marked when there is little of them where you are. You can also reach it from the Season app.'],
      ['Varsler om båten: du får beskjed når båten er framme eller ruta er slutt, lasten er full, du eller mannskapet er uthvilt eller trøtt, montering og verftsjobb er ferdig, redskap har stått lenge, og når det blir kuling eller høye bølger mens du er ute eller redskap står i sjøen. De kommer også om natta, og det første kan komme fem minutter etter at du lukket appen. Hvor mange du får om dagen, følger hvor mye du spiller.', 'Notifications about the boat: you are told when the boat is in or the route is done, the hold is full, you or the crew are rested or tired, a fitting or yard job is done, gear has soaked for long, and when a gale or high waves are on the way while you are out or gear is in the sea. They come at night too, and the first can come five minutes after you closed the app. How many you get a day follows how much you play.'],
      ['Ukas beste fisker kommer som ett varsel hver mandag. Kystposten og resten av verden sender ingen varsler.', 'The week\'s best fisher comes as one notification every Monday. Kystposten and the rest of the world send none.'],
      ['Tre steder å handle, hver med sin knapp: fiskemottaket (Lever, Is, Agn og Bunkring), utstyrsbutikken (fiskeutstyr, elektronikk, haler og klær) og verftet (båter, motor, lasterom, vedlikehold, maling og Bunkring). Utstyrsbutikker og verft ligger nå langs hele kysten. Bygd finnes på alle. Står du på feil sted, sier siden hvor du finner det, med nærmeste sted og Autonav dit.', 'Three places to trade, each with its own button: the fish plant (Land, Ice, Bait and Fuel), the tackle shop (fishing gear, electronics, haulers and clothes) and the yard (boats, engine, hold, upkeep, paint and Fuel). Tackle shops and yards now lie along the whole coast. The village is at all of them. If you stand in the wrong place, the page tells you where to find it, with the nearest place and Autonav there.'],
      ['Fars naust er et hjem, ikke en butikk: der hviler du, ser til mannskapet og beholdningen og setter naustet i stand. Is og agn kjøper du på mottaket. Håndjuksa ligger nå montert i båten fra start, og første tur går uten is. Etter første levering viser mottaket deg hvor du fyller isen, og første fylling er på huset. Alle mottak selger nå is.', 'Father’s boathouse is a home, not a shop: there you rest, see to the crew and the inventory and put the boathouse right. You buy ice and bait at the plant. The hand jig now sits aboard from the start, and the first trip goes without ice. After the first landing the plant shows you where to fill the ice, and the first fill is on the house. All plants now sell ice.'],
      ['Du bytter nå rigg mellom juksa, line, garn og teiner om bord, i fanen «Rigg» under Beholdning, og det går an hvor som helst så lenge ingen av garnene, linene eller teinene dine står i sjøen. Du trenger ikke lenger legge til kai på verftet.', 'You now change the rig between jigging, longline, nets and pots aboard, in the «Rig» tab under Inventory, and you can do it anywhere as long as none of your nets, lines or pots are in the sea. You no longer have to go to a quay at the yard.'],
      ['Fiskemottakene heter nå bare etter stedet de ligger på, for eksempel «Mottaket i Båtsfjord». Der to mottak ligger i samme sted, får det andre siden av det første (Vardø øst). Når du velger startsted, ser du hvor mange mottak som er der og hvor mange tonn de tar imot i året.', 'The fish plants are now named only by the place they lie at, for example «The plant in Båtsfjord». Where two plants lie in the same place, the second gets its side of the first (Vardø east). When you pick a starting place you see how many plants are there and how many tonnes they take in a year.'],
      ['Når både du og mannskapet står på sløying, står nå begge på dekk: du ved bordet og en av mannskapet ved bløggekaret. Før ble du stående ved rattet mens mannskapet jobbet alene.', 'When you and the crew are both on gutting, both now stand on deck: you at the table and one hand at the bleeding tub. Before, you stayed at the wheel while the crew worked alone.'],
      ['Ligger du ved en rorbu, står båten nå ved rorbuas kai i kartet og i ruteleggingen, ikke ved fiskemottaket ved siden av. Det gjaldt alle rorbuer langs kysten.', 'Moored at a rorbu, the boat now lies at the rorbu\'s quay in the chart and when you plan a route, not at the fish plant next to it. It affected every rorbu along the coast.'],
      ['Autonav fra fars naust finner nå veien ut av havna også der naustet ligger i en trang vik (Øksfjord), så første tur kan legges til fiskefeltet.', 'Autonav from Father\'s boathouse now finds the way out of the harbour also where the boathouse lies in a narrow cove (Øksfjord), so the first trip can be laid to the fishing ground.'],
      ['Åpningen: konvoluttens klaff ligger nå riktig vei når den åpnes (tuppen vendt opp), og den blir liggende åpen mens konvolutten faller bort.', 'The opening: the envelope\'s flap now lies the right way when it opens (tip up), and stays open while the envelope falls away.'],
      ['Kartplotteren: COG og XTE er tatt bort fra navigasjonslinja. COG viste det samme som kursen, og XTE var alltid null fordi båten følger ruta nøyaktig.', 'The chart plotter: COG and XTE are gone from the navigation bar. COG showed the same as the heading, and XTE was always zero because the boat follows the route exactly.'],
      ['Bro-visningen: å dra fingeren ned ser nå ned, og å dra opp ser opp, slik at sideveis og opp og ned styres på samme måte.', 'The bridge view: dragging down now looks down and dragging up looks up, so sideways and up and down work the same way.'],
      ['Rutetabellen på mobil i stående format ligger nå nederst på skjermen, over hele bredden, i stedet for å dekke det meste av kartet. Veipunktene står i to kolonner.', 'On a phone held upright, the route table now sits at the bottom of the screen across its whole width, instead of covering most of the chart. The waypoints are in two columns.'],
      ['CHIRP-ekkoloddet og sonaren kan nå vise lyr, lange, brosme, uer og kveite hver for seg, i tillegg til torsk, hyse, sei og blåkveite. Velg arten med knappen på kartet eller under Innstillinger.', 'The CHIRP echo sounder and the sonar can now show pollack, ling, tusk, redfish and halibut each on its own, as well as cod, haddock, saithe and Greenland halibut. Pick the species with the button on the chart or under Settings.'],
      ['Snekka: de blå fiskekarene på dekk stikker ikke lenger ut gjennom skroget akterut.', 'The snekke: the blue fish tubs on deck no longer stick out through the hull aft.'],
      ['Du ser nå de andre spillernes garn, liner og teiner i havet: grå streker med bøyer i kartplotteren, og bøyene i 3D. Det vises ikke hvem som eier dem, så du kan sette uten å krysse andres redskap.', 'You now see the other players\' nets, lines and pots in the sea: grey lines with buoys in the chart plotter, and the buoys in 3D. It does not show who owns them, so you can set without crossing anyone else\'s gear.']]],
    ['p89', '07.10.2026', 'Blåkveite', 'Greenland halibut', [
      ['Blåkveite er ny art. Den står på eggakanten på 500–1000 m dyp, mest fra Lofoten til Tromsøflaket utenfor Vesterålen, Andøya og Senja, mindre langs Finnmark og lite fra Storegga til Helgeland. Fjordene i Troms har en liten bestand. Om vinteren trekker gytefisken nordover.', 'Greenland halibut is a new species. It stands on the shelf edge at 500–1000 m, most from Lofoten to Tromsøflaket off Vesterålen, Andøya and Senja, less along Finnmark and little from Storegga to Helgeland. The fjords of Troms have a small stock. In winter the spawning fish move north.'],
      ['Havdypet er lagt inn langs hele kysten, så ekkoloddet, sonaren og kartplotteren viser eggakanten også langt ute.', 'The depth of the open sea is in along the whole coast, so the echo sounder, the sonar and the chart plotter show the shelf edge far out too.'],
      ['Direktefisket for båter under 28 m åpner 25. mai og stoppes når gruppekvoten er tatt, varslet tre dager før. Maksimalkvoten følger båtens lengde, du må stå på blad B, og minstemålet er 45 cm. Utenom perioden er blåkveite bare lov som bifangst, høyst 7 % av ukas landinger. Kvoteappen og regelappen viser det.', 'The direct fishery for boats under 28 m opens on 25 May and is stopped when the group quota is taken, with three days\' notice. The maximum quota follows the boat\'s length, you must be on blad B, and the minimum size is 45 cm. Outside the period Greenland halibut is only allowed as bycatch, at most 7% of the week\'s landings. The quota and rules apps show it.'],
      ['Line og garn tar blåkveite, juksa nesten ikke. På dypt vann tar settingen og trekket lengre tid, og redskapen skal røktes annenhver dag. Ved Andøya kan spermhvalen ta fisk av lina, og håkjerringa kan gjøre det samme på dypet.', 'Line and nets take Greenland halibut, the jig hardly at all. On deep water setting and hauling take longer, and the gear must be tended every other day. Off Andøya the sperm whale can take fish off the line, and the Greenland shark can do the same in the deep.'],
      ['Alle mottak tar imot blåkveite. Mens direktefisket er åpent, legger mottakene nord for 62° N ut bestillinger på blåkveite under Oppdrag, hvis du har line eller garn og står på blad B.', 'Every plant takes Greenland halibut. While the direct fishery is open, the plants north of 62° N post orders for it under Orders, if you have line or nets and are on blad B.'],
      ['Kystposten skriver når blåkveitefisket åpner, når stoppen varsles og når det stopper, og om kvoterådet og totalkvoten. Kvote-appen viser bestanden og totalkvoten år for år, og fra 2027 følger kvotene bestanden.', 'The Coast Post reports when the Greenland halibut fishery opens, when the stop is announced and when it stops, and the advice and the total quota. The Quota app shows the stock and the total quota year by year, and from 2027 the quotas follow the stock.'],
      ['Ekkoloddet og sonaren kan vise blåkveita for seg, og den har fått sin egen modell i 3D, mørk på begge sider.', 'The echo sounder and the sonar can show it on its own, and it has its own model in 3D, dark on both sides.']]],
    ['p88', '07.10.2026', 'Rettinger', 'Fixes', [
      ['Fisken på line og garn kommer om bord og bløgges etter hvert som redskapet kommer over rekka: per hundre kroker på lina og i tredjedeler per garn. Bløggekaret fylles gradvis, og trekket går saktere jo fullere karet blir, til sløyinga har tatt unna. Flere fisk synes på krokene og i garna, etter det som faktisk sitter der. Når garn trekkes, står to ved haleren: en trekker og en bløgger, så sløyinga venter til karet må tømmes eller en tredje tar den.', 'The fish on line and nets come aboard and are bled as the gear comes over the rail: per hundred hooks on the line and in thirds per net. The bleeding tub fills gradually, and the haul goes slower the fuller the tub gets, until the gutting has caught up. More fish show on the hooks and in the nets, by what is actually on them. When nets are hauled, two stand at the hauler: one pulls and one bleeds, so the gutting waits until the tub has to be emptied or a third hand takes it.'],
      ['Knappen «Arbeid» heter nå «Mannskap» og samler alt om folkene og arbeidet: hvem som er mønstret på båten, hvor de er, hvor slitne de er, arbeidsfordelingen og driftsplanen. Driftsplanen lages og slås på der. Mannskapet er mønstret på båten og følger skipperen, så driftsplanen går også fra rorbua, og de hviler i rorbua sammen med deg. Ansettelser ligger under «Ansatte» i bygda.', 'The «Work» button is now «Crew» and gathers everything about the people and the work: who is signed on, where they are, how tired they are, the division of work and the operating plan. The operating plan is made and switched on there. The crew are signed on to the boat and follow the skipper, so the operating plan runs from the rorbu too, and they rest in the rorbu with you. Hiring is under «Employees» in the village.'],
      ['Om vinteren ligger snøen helt ned til fjæra, og langs hele kysten er det tang og rur i fjæresteinene. Snøgrensa følger klimaet langs kysten.', 'In winter the snow lies right down to the shore, and there is rockweed and barnacles on the shore rocks along the whole coast. The snow line follows the climate along the coast.'],
      ['Egning går dobbelt så fort med to om bord og to og en halv gang så fort med tre. Kranen på kaia svinger rett over og henter lasten, fortøying og kast loss går raskere, og tauene er brune.', 'Baiting goes twice as fast with two aboard and two and a half times as fast with three. The crane on the quay swings straight over for the load, mooring and casting off are quicker, and the lines are brown.'],
      ['Salgslaget viser åpningstidene til mottakene, også de lengre tidene i skreisesongen.', 'The Sales app shows the plants\' opening hours, the longer ones in the skrei season too.'],
      ['Om bord vises aldri flere folk enn mannskapet og deg. Den som iser, skuffer is fra iskassa over fisken med spade, og den første blåsa går ut akter når du setter.', 'Aboard there are never more people than the crew and you. Whoever ices shovels ice from the ice bin over the fish, and the first buoy goes out astern when you set.'],
      ['Fangstmerket etter et trekk viser kilo per line, per garn og per teine. Garn som er satt sammen, regnes som ett garn.', 'The catch mark after a haul shows kilos per line, per net and per pot. Nets joined together count as one net.'],
      ['Med Autonav til ei blåse starter båten å trekke lina, garna eller teinene selv når den er framme.', 'With Autonav to a buoy, the boat starts hauling the line, the nets or the pots by itself when she gets there.'],
      ['Redningsskøyta har stasjoner langs hele kysten, fra Hvaler til Kirkenes, og den nærmeste rykker ut. Mens den er ute etter deg, vises den på AIS.', 'The rescue boat has stations along the whole coast, from Hvaler to Kirkenes, and the nearest one turns out. While she is out for you, she shows on the AIS.'],
      ['Ligger båten ved fars naust, starter Autonav og ruta i kartplotteren ved naustet, og båten går rett derfra. Før startet ruta ved mottaket.', 'When the boat lies at Father\'s boathouse, Autonav and the route on the chart plotter start at the boathouse, and the boat leaves straight from there. Before, the route started at the plant.'],
      ['Ligger flere kaier innen rekkevidde, for eksempel rorbua og mottaket like ved, viser «Fortøy» alle, så du kan velge hvor båten skal legge til. Før gikk den alltid til den nærmeste.', 'When several quays are within reach, say the rorbu and the plant close by, «Moor» shows them all, so you can choose where the boat goes in. Before, she always went to the nearest.'],
      ['Den som får fri neste tur, blir på land den turen, også når fangsten fortsatt ble levert da du ga fri.', 'Crew given the next trip off stay ashore for that trip, also when the catch was still being landed when you gave them the time off.'],
      ['Skipperen går også på dekk og sløyer når linetrekket stopper fordi bløggekaret er fullt.', 'The skipper also goes on deck to gut when hauling the line stops because the bleeding tub is full.'],
      ['Registreringsmerket, navnet og logoen på skroget leses riktig vei på begge sider.', 'The registration mark, the name and the logo on the hull read the right way on both sides.'],
      ['Eget merke i kartet flytter seg opp over tastaturet mens du skriver navnet.', 'Your own mark on the chart moves up above the keyboard while you type its name.']]],
    ['p87', '07.10.2026', 'Kystposten', 'Kystposten', [
      ['Kystposten er avisa for hele kysten: båtkjøp, båtdåp, grunnstøtinger, redninger, berginger, storfisk, fyrbilder og dagens største landinger, også fra de andre båtene langs kysten.', 'Kystposten is the paper for the whole coast: boats bought and named, groundings, rescues, salvage, big fish, lighthouse pictures and the day\'s biggest landings, from the other boats along the coast too.'],
      ['Trykk på en sak for å lese mer. Fanen Lokalt viser det som skjer innen 150 km fra hjemhavna.', 'Tap a story to read more. The Local tab shows what happens within 150 km of your home harbour.'],
      ['Appen viser hvor mange saker du ikke har lest, og spillet sier fra når du er i avisa eller noe skjer i nærheten.', 'The app shows how many stories you have not read, and the game tells you when you are in the paper or something happens nearby.'],
      ['Nye saker: sesongfiske og lange turer, kjøp av strukturkvote, og ukas toppfisker fra topplista for hele kysten.', 'New stories: following the season and long trips, structure quotas bought, and the top boat of the week from the leaderboard for the whole coast.'],
      ['Er landingen din dagens største langs kysten, får du vite det, også med et varsel når du er borte fra spillet.', 'When your landing is the day\'s biggest along the coast, you hear of it, with a notification too when you are away from the game.'],
      ['Kystposten skriver om rekordpriser når torsk, hyse eller sei betales bedre enn på et helt år, og om årets første skrei når den første båten lander skrei nord for Stad.', 'Kystposten writes about record prices when cod, haddock or saithe pays better than at any time in a year, and about the year\'s first skrei when the first boat lands skrei north of Stad.'],
      ['Alene om bord: blir blødekaret fullt mens du haler, sløyer du først og haler videre etterpå. Før kunne halingen bli stående.', 'Alone aboard: when the bleeding tub fills while you haul, you gut first and haul on after. Before, the haul could stand still.']]],
    ['p86', '07.10.2026', 'Havforskere og fyr', 'Scientists and lighthouses', [
      ['Nytt på tavla: prøvefiske for Havforskningsinstituttet. Fisk ved en stasjon og mål ti fisk på målebrettet, eller kjør en ekkoloddlinje gjennom tre punkter. Fangsten er din.', 'New on the board: survey fishing for the Institute of Marine Research. Fish at a station and measure ten fish on the board, or run an echo sounder line through three points. The catch is yours.'],
      ['Kystposten vil ha bilder av fyrene langs kysten, noen ganger i lav sol, mens fyret lyser, under nordlyset eller i uvær. Trykk på utløseren når fyret er i bildet, så står bildet i avisa.', 'Kystposten wants pictures of the lighthouses along the coast, sometimes in low sun, with the light lit, under the northern lights or in heavy weather. Press the shutter when the lighthouse is in the picture, and it is printed in the paper.'],
      ['Fyrene langs kysten har fått ordentlige tårn i 3D, og lyset står i riktig høyde over havet.', 'The lighthouses along the coast have proper towers in 3D, and the light sits at the right height over the sea.']]],
    ['p85', '07.10.2026', 'Turer', 'Trips', [
      ['Nytt i Oppdrag-appen: turoppdrag laget ut fra der båten er. Korte og lange turer, bestillinger fra mottak lenger unna, frakt langs kysten, tapt redskap med fisk i, og sesongflytting når fisken står et annet sted.', 'New in the Orders app: trip missions made from where the boat is. Short and long trips, orders from plants farther off, freight along the coast, lost gear with fish in it, and following the season when the fish is somewhere else.'],
      ['Oppdragene passer båten og deg: rekkevidden på en tank, været, hva du pleier å lande og hvor lenge du har vært på sjøen. «Kjør dit» finner veien.', 'The missions suit the boat and you: the range on a tank, the weather, what you usually land and how long you have been at sea. «Go there» finds the way.'],
      ['Når du legger ut på en lengre tur, står det i loggen når du er framme.', 'When you set out on a longer trip, the log says when you will be there.'],
      ['Hjelp på sjøen: en båt med motorstopp driver mot land. Legg deg ved siden av henne, ta henne på slep til havn og få bergelønn fra forsikringen, etter båtens verdi, faren og tiden. Driver hun på land først, blir det ingen.', 'Help at sea: a boat with engine trouble drifts toward land. Lie beside her, tow her to harbour and get a salvage reward from the insurer, by the boat\'s value, the danger and the time. If she drifts ashore first, there is none.']]],
    ['p84', '07.10.2026', 'Merker', 'Badges', [
      ['Ny app: Merker. «Første uke på sjøen» har 21 milepæler i tre kapitler. Hver gir en gave fra noen på kysten, og hvert kapittel sin egen belønning: den norske vimpelen i masta, som andre ser og som blir lengre for hvert kapittel, en haill og skrogfargen «Kystfisker».', 'New app: Badges. «The first week at sea» has 21 milestones in three chapters. Each gives a gift from someone on the coast, and each chapter its own reward: the Norwegian pennant at the mast, which others see and which grows longer with each chapter, a luck and the hull colour «Kystfisker».'],
      ['Merkene går videre etter uka: største levering, levert i alt, fartstid, mottak, arter, sjømil og flere.', 'The badges go on after the week: biggest landing, landed in all, sea time, plants, species, miles and more.'],
      ['Tatoveringene og fartstiden ligger nå i Merker-appen.', 'The tattoos and the sea time are now in the Badges app.'],
      ['Det første slepet og den første reparasjonen er gratis.', 'The first tow and the first repair are free.'],
      ['Flagget følger flaggtidene: opp kl. 08 (kl. 09 om vinteren) og ned ved solnedgang, senest kl. 21, og i Nord-Norge kl. 10–15 om vinteren. Vimpelen henger oppe hele døgnet.', 'The flag keeps the flag hours: up at 08 (09 in winter) and down at sunset, at 21 at the latest, and in Northern Norway 10 to 15 in winter. The pennant flies day and night.']]],
    ['p83', '07.10.2026', 'Synlig på sjøen', 'Seen at sea', [
      ['De andre spillerne er nå gule med en ring i kartet og kartplotteren, større enn de andre båtene, og navnet vises tidligere.', 'The other players are now gold with a ring on the chart and the plotter, larger than the other boats, and their names show sooner.'],
      ['Trykk på en spillers båt for å se hvem som eier den og hvor mye fartstid de har. Brukernavnet står også på topplista.', 'Tap a player\'s boat to see who owns it and how much sea time they have. The player name is on the leaderboard too.'],
      ['Alle registrerte spillere er synlige for hverandre, slik båter med AIS er det. Valget for å skjule båten er fjernet.', 'All registered players are visible to each other, as boats with AIS are. The choice to hide the boat is gone.']]],
    ['p82', '07.10.2026', 'Båten etter far', 'Father\'s boat', [
      ['Båten etter far har ikke noe navn på skroget når du tar henne over. Til da kjennes hun på registreringsmerket.', 'Father\'s boat has no name on her hull when you take her over. Until then she goes by her registration mark.'],
      ['Når du blir ført i fiskermanntallet etter den andre leveringen, døper du båten selv og velger et brukernavn som andre spillere ser.', 'When you are entered in the fishermen\'s register after the second landing, you name the boat yourself and choose a player name other players see.'],
      ['Alle registrerte spillere har et brukernavn. Har du konto fra før, blir du bedt om å velge et. Det kan endres under Innstillinger, Konto.', 'Every registered player has a player name. If you already have an account, you are asked to choose one. It can be changed in Settings, Account.']]],
    ['p81', '07.10.2026', 'Fartstid', 'Sea time', [
      ['Du samler nå fartstid, fra 0 til 40 år. Den tjenes om bord, med hver time til sjøs og hver levering. Det mannskapet ditt gjør mens du er borte, teller også, men mindre. Fartstiden står på telefonen og i Sjømann-appen.', 'You now gather sea time, from 0 to 40 years. It is earned aboard, with every hour at sea and every landing. What your crew does while you are away counts too, but less. Your sea time is on the phone and in the Seaman app.'],
      ['Når du har vært borte, er du uthvilt: de neste timene til sjøs gir dobbel fartstid.', 'After time away you are rested: the next hours at sea give double sea time.'],
      ['«Mens du var borte» viser nå hva som ble levert, fartstiden du fikk og det viktigste som skjedde.', '«While you were away» now shows what was landed, the sea time you gained and the main things that happened.']]],
    ['p80', '07.10.2026', 'Rederilogo', 'Company logo', [
      ['I Malerverkstedet kan du lage en rederilogo av et tegn, bokstaver og to farger, eller laste opp et eget bilde. Logoen står midtskips på skroget til båtene dine, og kan heises som rederiflagg.', 'In the paint shop you can make a company logo from a sign, letters and two colours, or upload a picture of your own. The logo sits midships on the hull of your boats and can be flown as a house flag.'],
      ['Andre spillere i nærheten ser logoen og flagget ditt.', 'Other players nearby see your logo and flag.'],
      ['Et trykk på «Språk» i Innstillinger bytter ikke lenger språk. Det gjør bare knappen.', 'Tapping «Language» in Settings no longer switches the language. Only the button does.']]],
    ['p79', '07.10.2026', 'Registreringsmerke', 'Registration mark', [
      ['Båten har fått registreringsmerke ved baugen på begge sider, slik forskriften krever: fylkets bokstaver, et løpenummer og kommunens bokstaver, med hjemhavna som utgangspunkt. Merket står også på ervervstillatelsen under Papirer.', 'The boat now carries a registration mark near the bow on both sides, as the regulations require: the county\'s letters, a serial number and the municipality\'s letters, from the home harbour. The mark is on the fishing permit under Papers too.'],
      ['I Malerverkstedet kan du velge løpenummeret selv, så lenge ingen annen båt har det.', 'In the paint shop you can choose the serial number yourself, as long as no other boat has it.']]],
    ['p78', '07.10.2026', 'Flagg', 'Flags', [
      ['Velg flagget i akterenden i Malerverkstedet: over 40 nasjoner, også det samiske og det kvenske, som rektangel, vimpel eller splitt. Flagget blafrer i vinden som før.', 'Choose the flag at the stern in the paint shop: over 40 nations, the Sámi and the Kven flags too, as a rectangle, a pennant or a swallowtail. The flag flutters in the wind as before.']]],
    ['p77', '07.10.2026', 'Malingsdesign', 'Paint designs', [
      ['Malerverkstedet har fått malingsdesign: ripestripe, totone, vannlinjestripe, stripefarge og nylakkert. Velg fargen selv og prøv designet på båten din før du bestemmer deg. Linjene følger skroget.', 'The paint shop has paint designs: a sheer stripe, two-tone, a boot stripe, a stripe colour and fresh gloss. Choose the colour yourself and try the design on your boat before you decide. The lines follow the hull.']]],
    ['p76', '07.10.2026', 'Malerverkstedet og båtnavn', 'The paint shop and boat names', [
      ['Nytt under Verft: Malerverkstedet. Velg blant 16 skrogfarger og se fargen på båten din i 3D før du maler.', 'New under Yard: the paint shop. Choose from 16 hull colours and see the colour on your boat in 3D before you paint.'],
      ['Trebåten kan nå males, også plankene.', 'The wooden boat can now be painted, planks and all.'],
      ['Båtnavnet står på skroget på alle båtene, lyst på et mørkt skrog og mørkt på et lyst. Båtene rundt deg viser også navnet sitt.', 'The boat\'s name is on the hull of every boat, light on a dark hull and dark on a light one. The boats around you show their names too.'],
      ['Andre spillere ser fargen på båten din.', 'Other players see the colour of your boat.']]],
    ['p75', '06.10.2026', 'Hele kysten', 'The whole coast', [
      ['Nyhetene i Kystposten, topplista, nye folk på Mannskapsbørsen og mottakene i nyhetene følger nå hjemhavna di, hvor du enn starter langs kysten. Ingen tekster later lenger som om spillet bare er på Senja.', 'The news in the Coast Post, the leaderboard, new hands at the crew exchange and the plants in the news now follow your home harbour, wherever you start along the coast. No text pretends any more that the game is only on Senja.']]],
    ['p74', '06.10.2026', 'Spill som gjest', 'Play as a guest', [
      ['Nye spillere kan begynne rett på brevet fra far, uten å logge inn. Senere registrerer du deg i fiskermanntallet med Google, Apple eller e-post, og spillet ditt blir med.', 'New players can start right at Father’s letter without signing in. Later you register in the fishermen’s register with Google, Apple or e-mail, and your game comes along.']]],
    ['p73', '06.10.2026', 'Mannskapet hviler med deg', 'The crew rest with you', [
      ['Når du hviler på rorbua eller i naustet, går mannskapet også i land, og de hviler seg opp like fort som deg: fra helt utslitt til uthvilt på seks timer.', 'When you rest at the rorbu or in the boathouse, the crew go ashore too, and they recover as fast as you: from worn out to rested in six hours.']]],
    ['p72', '06.10.2026', 'Rederi-appen kommer med rederiet', 'The Company app comes with the company', [
      ['Rederi-appen ligger på telefonen først når du har stiftet Rederi AS i banken, eller har mer enn én båt. Lånene står i Bank-appen som før.', 'The Company app is on the phone once you have founded a company in the bank, or own more than one vessel. The loans are in the Bank app as before.']]],
    ['p70', '06.10.2026', 'Sluttseddelen og kaia', 'The landing note and the quay', [
      ['Første tur kunne stå fast på «Vis sluttseddelen» hvis det gikk noen timer etter leveringen. Nå vises seddelen til veiledningen har vist den, og veiledningen går videre uansett. Takk for tipset!', 'The first trip could get stuck on «Show the landing note» if a few hours passed after the landing. Now the note stays until the guide has shown it, and the guide moves on whatever happens. Thanks for the tip!'],
      ['Store bygg fra kartdataene kunne stå oppå kaimottaket, så båten lå inntil en høy vegg (Kjøllefjord). Nå tas de bort der mottaket står, slik det alt var gjort på Senja.', 'Large buildings from the map data could stand on top of the fish plant quay, so the boat lay against a tall wall (Kjøllefjord). Now they are left out where the plant stands, as was already done on Senja.']]],
    ['p69', '06.10.2026', 'Juksamaskin og egne merker', 'Jigging machines and your own marks', [
      ['Med juksamaskiner om bord passer du maskinene, så «Jukse selv» er borte. På båter uten maskin jukser du selv som før.', 'With jigging machines aboard you tend the machines, so «Jig yourself» is gone. On boats without machines you jig by hand as before.'],
      ['Egne merker i kartplotteren: hold fingeren stille på kartet, så settes et flagg. Trykk på det for å gi det navn, legge rute dit eller slette det. Merkene blir liggende.', 'Your own marks in the chart plotter: hold a finger still on the chart to set a flag. Tap it to name it, lay a route to it or delete it. The marks stay.']]],
    ['p68', '06.10.2026', 'Husene står på bakken', 'The houses stand on the ground', [
      ['Husene langs kysten sank av og til ned i bakken og snøen, fordi de ble bygd før terrenget rundt var lastet. Nå venter de på terrenget og bygges på nytt når det kommer. Takk for tipset!', 'The houses along the coast sometimes sank into the ground and the snow, because they were built before the terrain round them had loaded. Now they wait for the terrain and are built again when it comes. Thanks for the tip!']]],
    ['p67', '06.10.2026', 'Plass i styrhuset', 'Room in the wheelhouse', [
      ['Styrhuset på plastsnekka er høyere, så skipperen ikke lenger stikker hodet gjennom taket.', 'The wheelhouse on the fibreglass snekke is taller, so the skipper no longer puts his head through the roof.'],
      ['Når du jukser fra en åpen båt med styrhus, eller er alene om bord, står skipperen ute ved rekka og ikke ved rattet. Takk for tipsene!', 'When you jig from an open boat with a wheelhouse, or are alone aboard, the skipper stands out at the rail and not at the wheel. Thanks for the tips!']]],
    ['p66', '06.10.2026', 'Naustet og mottakskaia', 'The boathouse and the plant’s quay', [
      ['I hjemhavna står det over knappene om båten ligger ved naustet eller ved mottakskaia. Under Bygd er det en ny knapp, Naustet, som åpner notatboka der du setter i stand naustet. Når du hviler i naustet, ser du hvor mye raskere tett tak og vedovn gjør det.', 'In the home harbour the line above the buttons says whether the boat lies at the boathouse or at the plant’s quay. Under Village there is a new button, Boathouse, that opens the notebook where you put the boathouse to rights. Resting in the boathouse, you see how much faster the tight roof and the stove make it.']]],
    ['p65', '06.10.2026', 'Den nye hurtigsjarken fra Blender', 'The new speed sjark from Blender', [
      ['Ny hurtigsjark 10,99 m er bygget i Blender etter en ekte tegning: hardt slag, styrhus forut og et fritt arbeidsdekk akter med luke, kran og haler. Den har tegningens mål, 4,68 m bred og 2,06 m dypgående. Petrolblått skrog med hvite overbygg. Bare utsiden er modellert.', 'The new 10.99 m speed sjark is built in Blender from a real drawing: a hard chine, the wheelhouse forward and a clear working deck aft with a hatch, a crane and a hauler. She has the drawing\'s size, 4.68 m wide and a 2.06 m draft. A petrol hull with white superstructure. Only the outside is modelled.']]],
    ['p64', '06.10.2026', 'Kystbåten på 14,99 m fra Blender', 'The 14.99 m coastal vessel from Blender', [
      ['Kystbåt 14,99 m er bygget i Blender: rødt skrog, hvitt baksdekk med åpen halestasjon på styrbord side, styrhus forut, rød kran og mesanmast med rødt seil. Bare utsiden er modellert.', 'The 14.99 m coastal vessel is built in Blender: a red hull, a white shelter deck with an open hauling station on the starboard side, the wheelhouse forward, a red crane and a mizzen with a red sail. Only the outside is modelled.']]],
    ['p63', '06.10.2026', 'Den eldre kystbåten fra Blender', 'The older coastal vessel from Blender', [
      ['Eldre kystbåt 21 m er bygget på nytt i Blender: en stålbåt fra 70-tallet med hvit bakk, rundgatt, galge, mast med lastebom, styrhus i teak akter og skorstein. Skroget er oksblodrødt med hvit ripestripe. Bare utsiden er modellert.', 'The older 21 m coastal vessel is rebuilt in Blender: a steel boat from the seventies with a white forecastle, a cruiser stern, a gallows, a mast with a derrick, a teak wheelhouse aft and a funnel. The hull is oxblood with a white sheer line. Only the outside is modelled.']]],
    ['p62', '06.10.2026', 'Snøkrabbefartøyet fra Blender', 'The snow crab vessel from Blender', [
      ['Snøkrabbefartøyet er bygget på nytt i Blender: lavt teinedekk under tak akter, portal og kraner for teinene, bakk med styrhus på toppen. Antrasittgrått skrog med okergul stripe og kremhvite overbygg. Bare utsiden er modellert.', 'The snow crab vessel is rebuilt in Blender: a low pot deck under a roof aft, a portal and cranes for the pots, a forecastle with the wheelhouse on top. An anthracite hull with an ochre stripe and cream superstructure. Only the outside is modelled.']]],
    ['p61', '06.10.2026', 'Autolineren fra Blender', 'The autoliner from Blender', [
      ['Autolineren er bygget på nytt etter en ekte generaltegning: 45 m med rund forfot, haleport på styrbord side der lina kommer inn, styrhus midtskips med radarkupler, skorstein, MOB-båt og skrå formast. Hun har tegningens mål, 45,4 × 10,45 m og 3,8 m dypgående. Bare utsiden er modellert.', 'The autoliner is rebuilt from a real general arrangement: 45 m with a round forefoot, a hauling port on the starboard side where the line comes in, a wheelhouse amidships with radar domes, a funnel, a rescue boat and a raked foremast. She has the drawing\'s size, 45.4 × 10.45 m and a 3.8 m draft. Only the outside is modelled.']]],
    ['p60', '06.10.2026', 'Ringnotsnurperen fra Blender', 'The purse seiner from Blender', [
      ['Ringnot- og pelagisk tråleren er bygget på nytt etter ekte tegninger: blått skrog, notbinge med kraftblokk akter, trålrull og tråldører, styrhus midtskips og formast. Bare utsiden er modellert.', 'The purse seiner and pelagic trawler is rebuilt from real drawings: a blue hull, the seine bin with the power block aft, the trawl drum and doors, the wheelhouse amidships and the foremast. Only the outside is modelled.']]],
    ['p59', '06.10.2026', 'Frysetråleren fra Blender', 'The freezer trawler from Blender', [
      ['Frysetråleren er bygget på nytt etter en ekte generaltegning: 60 m med akterslipp, galge med tråldører på hekken, nettrommel, trålvinsjer og styrhus på toppen. Den heter nå «Frysetråler 60 m» og har tegningens mål.', 'The freezer trawler is rebuilt from a real general arrangement: 60 m with a stern ramp, a gantry with the trawl doors on the stern, a net drum, trawl winches and the wheelhouse on top. It is now the «60 m freezer trawler», with the drawing\'s size.']]],
    ['p58', '06.10.2026', 'Båten følger rutestreken', 'The boat follows the route line', [
      ['Båten i 3D følger nå streken i kartplotteren nøyaktig: ut fra kaia, langs ruta med myke, men presise svinger, og inn til kaia. Den slakker av og stopper akkurat på siste punkt, uten å gli forbi og hoppe tilbake.', 'The boat in 3D now follows the line on the chart plotter exactly: out from the quay, along the route with smooth but precise turns, and in to the quay. It eases off and stops right on the last point, without sliding past and jumping back.'],
      ['Stopp underveis bråstopper ikke lenger. Båten slakker av og stopper litt lenger fram på ruta.', 'Stop under way no longer stops dead. The boat eases off and stops a little further along the route.'],
      ['Båten henger ikke lenger ved mottakskaia i Senjahopen når du går til rorbua. Takk for tipset!', 'The boat no longer hangs at the plant quay in Senjahopen when you go to the rorbu. Thanks for the tip!'],
      ['Egen båt flytter seg jevnt i kartplotteren, flere ganger i sekundet.', 'Your own boat moves smoothly on the chart plotter, several times a second.']]],
    ['p57', '06.10.2026', 'Været etter hvor du er', 'The weather where you are', [
      ['Været og sjøen følger nå klimaet der du er langs kysten: mildere og våtere vintre i sør, kaldere sjø i øst, mer nedbør på Vestlandet og mindre i Finnmark. Ved Senja er alt som før.', 'The weather and the sea now follow the climate where you are along the coast: milder, wetter winters in the south, a colder sea in the east, more rain in the west and less in Finnmark. At Senja everything is as before.']]],
    ['p56', '06.10.2026', 'Takk-haill for gode tips', 'Thank-you luck for good tips', [
      ['Hjelper en tilbakemelding oss å gjøre spillet bedre, får du 12 timer med fullt haill (+100 % fiskelykke) som takk, like sterkt hele tida. Det kommer i Haill-appen, og du aktiverer det når du vil.', 'If your feedback helps us make the game better, you get 12 hours of full luck (+100 % catch luck) as a thank-you, as strong all the time. It comes in the Luck app, and you switch it on when you like.'],
      ['Spillet minner deg av og til på Tilbakemelding-appen, etter en levering og når noe har gått galt.', 'The game now and then reminds you of the Feedback app, after a landing and when something has gone wrong.']]],
    ['p55', '06.10.2026', 'Nordlyset', 'The northern lights', [
      ['Nordlyset er nytt: grønne draperier med stråler som folder seg og flimrer, rødt høyt oppe og en lilla kant når det er sterkt. Svakt nordlys er en lav bue i nord, og sterkt nordlys kommer over hodet. Lenger sør ser du det sjeldnere.', 'The northern lights are new: green curtains with rays that fold and shimmer, red high up and a purple fringe when strong. Weak lights are a low arc in the north, and strong ones come overhead. Further south you see them less often.']]],
    ['p54', '05.10.2026', 'Regler før du gjør feil', 'Rules before you make a mistake', [
      ['Et fiskepunkt i ruta der båten din ikke får fiske, er merket med grunnen, og «Kast loss» spør først.', 'A fishing point on the route where your boat may not fish is marked with the reason, and «Cast off» asks first.'],
      ['Autonav går til nærmeste sted der du kan fiske, og sier hvorfor. Trykk samme sted igjen for å gå helt dit.', 'Autonav goes to the nearest place where you may fish, and says why. Tap the same place again to go all the way.'],
      ['Kaia sier hvor mye som blir inndratt før du leverer, og hvorfor.', 'The quay tells you how much will be confiscated before you land, and why.'],
      ['Første gang en regel gjelder båten din, får du et tips i telefonen.', 'The first time a rule concerns your boat, you get a tip in the phone.']]],
    ['p53', '05.10.2026', 'Feilrettinger', 'Fixes', [
      ['Mister PC-en eller telefonen 3D-visningen midt i spillet, lagres spillet og lastes på nytt av seg selv. PC-er som ikke fikk 3D i det hele tatt, prøver nå enklere innstillinger først.', 'If the PC or phone loses the 3D view in play, the game is saved and loads again by itself. PCs that got no 3D at all now try plainer settings first.']]],
    ['p52', '05.10.2026', 'Teiner og regler', 'Pots and rules', [
      ['Kongekrabbeteinene er nye fra Blender. Med teinehaler kommer teina opp over blokka på davitten, svinges inn på dekk, tømmes i krabbekaret, agnes og stables akter. Ved setting vippes den ut over rekka og synker.', 'The king crab pots are new from Blender. With a pot hauler the pot comes up over the block on the davit, swings in on deck, is emptied into the crab tank, baited and stacked aft. Setting, it is tipped over the rail and sinks.'],
      ['Regler-appen sier nå tydelig at reglene i spillet er forenklet, og at Fiskeridirektoratets regler gjelder til ekte fiske.', 'The Regler app now says plainly that the rules in the game are simplified, and that the Directorate of Fisheries\' rules apply to real fishing.']]],
    ['p51', '05.10.2026', 'Mer fisk og mer fart', 'More fish and more speed', [
      ['Haill gir nå dobbel fiskelykke et helt døgn, og luksushaill tredobbel. Så blekner den i døgn-trinn: luksushaill varer i fire døgn og vanlig haill i tre. Tida er spilltid.', 'Luck now gives double luck for a whole day, and luxury luck triple. Then it fades a day at a time: luxury luck lasts four days and luck three. The time is game time.'],
      ['Trim gir båten mye mer fart for en tid: +50 % i et døgn, +75 % i to døgn eller dobbel fart i tre døgn.', 'Tuning gives the boat much more speed for a while: +50% for a day, +75% for two days or double speed for three days.'],
      ['Nytt på verftet: «Ferdig nå» gjør alle jobbene på båten ferdig med én gang.', 'New at the yard: «Done now» finishes all the jobs on the boat at once.']]],
    ['p50', '05.10.2026', 'Feilrettinger', 'Fixes', [
      ['Lyden på iPhone kommer tilbake ved neste trykk etter en samtale eller når appen har vært i bakgrunnen, i stedet for å gi en feilmelding.', 'The sound on iPhone comes back with the next tap after a call or when the app has been in the background, instead of giving an error.'],
      ['Havet i 3D er skrevet om, så flere Android-telefoner og PC-er med Windows skal få det fulle havet. Går ikke det, prøves et lettere hav før det flate.', 'The sea in 3D is rewritten so more Android phones and Windows PCs should get the full sea. If not, a lighter sea is tried before the flat one.'],
      ['Skriftene ligger nå i appen, så spillet henter ingenting fra Google og ser likt ut uten nett. På kontokortet i Innstillinger finner du vilkår, personvern, kilder og kontakt.', 'The fonts are now in the app, so the game fetches nothing from Google and looks the same offline. On the account card in Settings you find the terms, privacy, sources and contact.']]],
    ['p49', '05.10.2026', 'Varsler som betyr noe', 'Notifications that matter', [
      ['Slår du på varsler under Innstillinger, får du bare beskjed om det som betyr noe: redskap som har stått lenge nok, fisk som snart blir dårligere, båten framme med fangst, verftet ferdig, kvotestopp i åpen gruppe, når noen går forbi deg på topplista, hvordan uka endte, og sesongene.', 'If you turn on notifications in Settings, you are only told what matters: gear that has soaked long enough, fish about to lose quality, the boat in with its catch, the yard done, a quota stop in the open group, someone passing you on the leaderboard, how the week ended, and the seasons.'],
      ['Høyst fire i døgnet, aldri mellom 22 og 08, og det som kommer samtidig, samles i ett varsel. Du velger selv hvilke typer du vil ha.', 'At most four a day, never between 22 and 08, and what comes at once is gathered in one. You choose which kinds you want.'],
      ['Etter første tur spør spillet om du vil ha varsler. Har telefonen allerede gitt lov, slås de på av seg selv.', 'After the first trip the game asks whether you want notifications. If the phone already allows them, they are turned on by themselves.']]],
    ['p48', '05.10.2026', 'Norges beste båter', 'Norway\'s best boats', [
      ['Ekkoloddet i kartplotteren har fem trinn som et ekte ekkolodd: hvitt der det er lite eller ingen fisk, så blått, grønt, gult og rødt der det står tettest.', 'The echo sounder on the chart plotter has five steps like a real one: white where there is little or no fish, then blue, green, yellow and red where it is densest.'],
      ['Topplista i Salgslaget gjelder nå hele kysten, med de ekte spillerne. Den har to lister: åpen gruppe, der båtene står med navnet sitt, og lukket gruppe, der både fartøy og rederi står. Den som ligger øverst, har Norges beste båt den uka.', 'The leaderboard in Sales now covers the whole coast, with the real players. It has two lists: the open group, where the boats are listed by name, and the closed group, where both vessel and company are shown. The one at the top has Norway\'s best boat that week.']]],
    ['p47', '05.10.2026', 'Toppliste for åpen gruppe', 'Leaderboard for the open group', [
      ['Salgslaget → Toppliste viser nå de ekte spillerne i åpen gruppe, rangert etter hvor mye de har landet denne uka og forrige uke. Alle står med båtnavnet sitt og mottaket de har levert mest til, ikke med firmanavnet.', 'Sales → Leaderboard now shows the real players in the open group, ranked by how much they have landed this week and last week. Everyone is listed by their boat\'s name and the plant they delivered most to, not by the company name.'],
      ['Har du skrudd av «Vis båten min for andre spillere», står du som ukjent båt for de andre.', 'If you have turned off «Show my boat to other players», you show as an unknown boat to the others.'],
      ['Kompasslinja går over hele toppen på telefon i stående format igjen. Før var den klemt sammen i hjørnet.', 'The compass line runs along the whole top again on a phone held upright. It had been squeezed into the corner.'],
      ['Båtene til andre spillere vises med sin egen båtmodell i 3D, så en venn i samme gamle trebåt som deg ser ut som den, ikke som en hvit plastbåt.', 'Other players\' boats show with their own boat model in 3D, so a friend in the same old wooden boat as you looks like it, not like a white plastic boat.']]],
    ['p46', '05.10.2026', 'Video og flere bilder i Tilbakemelding', 'Video and more pictures in Feedback', [
      ['I Tilbakemelding kan du nå legge ved opptil fire bilder og to videoer, for eksempel et skjermopptak av en feil. Store opptak gjøres mindre før de sendes, og du ser hvor langt sendingen har kommet.', 'In Feedback you can now add up to four pictures and two videos, for example a screen recording of a bug. Large recordings are made smaller before they are sent, and you see how far the sending has come.'],
      ['Skjermbilde: av/på og volum ned samtidig. Skjermopptak: dra ned hurtigmenyen og velg «Skjermopptak».', 'Screenshot: power and volume down together. Screen recording: pull down the quick settings and choose «Screen recorder».']]],
    ['p45', '05.10.2026', 'Én sjø, én kvote og ett marked', 'One sea, one quota and one market', [
      ['Fisken de andre spillerne tar, er borte fra sjøen din også. Fisker noen et felt tomt, er det tomt for alle til det har vokst til igjen.', 'The fish the other players take is gone from your sea too. If someone fishes a ground empty, it is empty for everyone until it has grown back.'],
      ['Torsken spillerne lander i åpen gruppe, teller med i gruppekvoten, så stoppen kan komme tidligere. Kvote-appen viser hvor mye de andre spillerne har landet i år.', 'The cod the players land in the open group counts in the group quota, so the stop can come earlier. The Quota app shows how much the other players have landed this year.'],
      ['Leverer mange til samme mottak, går prisen der ned for alle. Et annet mottak kan gi bedre betalt.', 'When many deliver to the same plant, its price goes down for everyone. Another plant may pay better.']]],
    ['p44', '05.10.2026', 'Fra spillerne: røyk, sløying og tips', 'From the players: smoke, gutting and tips', [
      ['Røyken fra semidieselen er myke, grå dotter som blekner, ikke svarte prikker, og den tegnes ikke langt unna.', 'The semi-diesel\'s smoke is soft grey puffs that fade, not black dots, and it is not drawn far off.'],
      ['Statuslinja viser hvor fullt bløggekaret er, og når du sløyer: hvor lenge det tar i ekte tid, og at du fisker videre etterpå. Du får beskjed når sløyingen starter og slutter.', 'The status line shows how full the bleeding tub is, and when you gut: how long it takes in real time, and that you fish on after. You are told when the gutting starts and ends.'],
      ['Rykker du ikke på to napp etter hverandre når du jukser selv, fisker juksa av seg selv igjen.', 'If you do not strike at two bites in a row when you jig yourself, the jig fishes on its own again.'],
      ['Små tips i første tur, som «Båten er på vei ut», forsvinner etter noen sekunder eller når du trykker på dem.', 'Small tips on the first trip, like «The boat is on its way out», go after a few seconds or when you tap them.']]],
    ['p43', '05.10.2026', 'Du ser de andre spillerne', 'You see the other players', [
      ['Båtene til andre spillere i nærheten vises nå på sjøen i 3D og som AIS-mål i kartplotteren, med båtnavnet. De har sin egen gule farge, og AIS-kortet viser båttypen.', 'The other players\' boats near you now show on the water in 3D and as AIS targets on the chart plotter, with the boat\'s name. They have their own yellow colour, and the AIS card shows the boat type.'],
      ['Under Innstillinger, på kontokortet, kan du skru av «Vis båten min for andre spillere».', 'In Settings, on the account card, you can turn off «Show my boat to other players».']]],
    ['p42', '05.10.2026', 'Én klokke for hele verden', 'One clock for the whole world', [
      ['Nå går alle spillerne på nøyaktig samme klokke og dato, på alle enheter. Klokka hentes fra serveren, så en telefon med feil tid er likevel i takt. Verden startet 1. mars 2027 kl. 06 i dag kl. 17 norsk tid, og går 6 ganger fortere enn virkeligheten.', 'Now every player is on exactly the same clock and date, on every device. The clock comes from the server, so a phone with the wrong time is still in step. The world began at 06:00 on 1 March 2027 today at 17:00 Norwegian time, and runs 6 times real time.'],
      ['Kvoteårene, bestandene, ferskfiskordningen og kjøperne er de samme for alle.', 'The quota years, the stocks, the fresh-fish scheme and the buyers are the same for everyone.'],
      ['Spill fra før som lå foran verdens klokke, går med halv fart til verden har tatt dem igjen. Spill som lå bak, spoles fram.', 'Games from before that were ahead of the world\'s clock go at half pace until the world has caught up. Games that were behind are played forward.']]],
    ['p41', '05.10.2026', 'Rykk-knappen og ny konto', 'The strike button and a new account', [
      ['Når du jukser selv, står knappen høyere opp, over statuslinja. Det står «Vent på napp …» over den, og på knappen står det «Rykk». Den blir rød når fisken biter.', 'When you jig yourself, the button sits higher, above the status line. «Wait for a bite …» stands above it and «Strike» on it, and it turns red when the fish bites.'],
      ['Sletter du kontoen, slettes også spillet på enheten. Neste gang begynner du på nytt med brevet fra far og naustet.', 'Deleting the account also deletes the game on the device. Next time you begin again with Father’s letter and the boathouse.'],
      ['Stopper båten midt i første tur, viser veiledningen deg hvordan du lager ruta på nytt i stedet for å låse deg.', 'If the boat stops in the middle of the first trip, the guide shows you how to make the route again instead of locking you in.']]],
    ['p40', '05.10.2026', 'Første tur viser mer', 'The first trip shows more', [
      ['Når du kommer fram til feltet første gang, får du vite hva fiskelykke er, før du henter haillen i Haill-appen.', 'When you reach the grounds the first time, you learn what luck is before you fetch the haill in the Luck app.'],
      ['På vei inn til mottaket viser veiledningen deg rundt: statusboksen, dekksdagboka, kameraet og broa, appene på telefonen, været og innstillingene.', 'On the way in to the plant the guide shows you round: the status box, the deck log, the camera and the bridge, the apps on the phone, the weather and the settings.']]],
    ['p39', '05.10.2026', 'Verkstedet på en halvtime', 'The yard in half an hour', [
      ['Montering av utstyr, service, skrogrens, lasterom og motorbytte tar nå 30 minutter hver, og alle jobbene i køen går samtidig.', 'Fitting equipment, servicing, cleaning the hull, the hold and an engine change now take 30 minutes each, and all the jobs in the queue run at the same time.'],
      ['Overtid kan kjøpes for hver jobb for seg. Service du gjør selv, er billigere og tar en time.', 'Overtime can be bought for each job on its own. Servicing it yourself is cheaper and takes an hour.']]],
    ['p38', '05.10.2026', 'Skiffen kjøpes på verftet', 'The skiff is bought at the yard', [
      ['Aluminiumsskiffen er ikke lenger startbåt for noen. Hadde du den fra starten, har du nå fars gamle trebåt. Påhengsmotoren på 90 hk, som ikke passer i henne, er betalt tilbake. Skiffen kan kjøpes på verftet.', 'The aluminium skiff is no longer anyone’s start boat. If you had it from the start, you now have Father’s old wooden boat. The 90 hp outboard, which does not fit her, has been paid back. The skiff can be bought at the yard.']]],
    ['p37', '05.10.2026', 'Lagringen på kontoen er tryggere', 'Safer saves on your account', [
      ['Spiller du på flere enheter, skriver ikke lenger én enhet over spillet på en annen. Er det spilt begge steder, velger du selv hvilket spill du vil fortsette med, og ser dag, penger og båt for begge.', 'If you play on several devices, one no longer writes over the game on another. If both have been played, you choose which game to go on with, seeing the day, money and boat of each.'],
      ['Under Innstillinger → kontoen ligger «Tidligere lagringer». Der kan du hente tilbake et av de ti siste spillene på kontoen, eller det enheten hadde før.', 'Under Settings → the account is «Earlier saves». There you can take back one of the last ten games on the account, or the one the device had before.'],
      ['Spillet lastes opp hvert minutt mens du spiller, og når du legger appen bort.', 'The game is uploaded each minute while you play, and when you put the app away.']]],
    ['p36', '05.10.2026', 'Snø ved rorbua, Fortøy, og mindre HUD', 'Snow at the rorbu, Moor, and a smaller HUD', [
      ['Rorbuene og fars naust har snø på bakken og taket om vinteren, som terrenget rundt, i stedet for grønt gress.', 'The rorbuer and Father’s boathouse have snow on the ground and the roof in winter, like the land around, instead of green grass.'],
      ['Ligger du stille nær en kai, en rorbu eller naustet, står «Fortøy» i knapperaden. Båten finner veien inn og legger til, så du kan hvile.', 'Lying still near a quay, a rorbu or the boathouse, «Moor» is in the button row. The boat finds the way in and moors, so you can rest.'],
      ['Trykk «–» på statusboksen eller det lille kartet for å gjøre dem til en tynn stripe. Under Innstillinger kan du skjule HUD helt.', 'Tap «–» on the status box or the little chart to fold it to a thin strip. In Settings you can hide the HUD altogether.']]],
    ['p35', '05.10.2026', '3D på Windows-PC', '3D on Windows PCs', [
      ['3D-visningen startet ikke på noen Windows-PC-er (Chrome og Firefox): sjøen ble for tung for grafikkdriveren. Nå starter de med en litt enklere sjø, og går driveren likevel i stå, prøver spillet en enklere neste gang.', 'The 3D view did not start on some Windows PCs (Chrome and Firefox): the sea was too heavy for the graphics driver. They now start with a slightly simpler sea, and if the driver still gives up, the game tries a simpler one next time.'],
      ['Står det «ingen WebGL-kontekst», har nettleseren slått av 3D etter en driverfeil. Lukk nettleseren helt og åpne den igjen.', 'If it says «no WebGL context», the browser has turned 3D off after a driver error. Close the browser fully and open it again.']]],
    ['p34', '05.10.2026', 'Ny app: Tilbakemelding', 'New app: Feedback', [
      ['Si fra om feil, ønsker og ideer rett fra telefonen i spillet: velg hva det gjelder, skriv, gi stjerner og legg ved et bilde fra galleriet eller av spillet.', 'Report bugs, wishes and ideas straight from the phone in the game: pick what it is about, write, give stars and add a picture from your gallery or of the game.'],
      ['Nederst i appen ser du det du har sendt, om det er lest eller fikset, og svaret fra oss.', 'At the bottom of the app you see what you have sent, whether it is read or fixed, and our answer.']]],
    ['p33', '05.10.2026', 'Fangstprikkene blekner', 'The catch dots fade', [
      ['De fargede prikkene med kilo i timen i kartplotteren forsvinner 12 spilltimer etter fisket, så kartet viser bare det som er ferskt.', 'The coloured dots with kilos per hour on the chart plotter are gone 12 game hours after the fishing, so the chart shows only what is fresh.']]],
    ['p32', '05.10.2026', 'Første tur kan ikke hoppes over', 'The first trip cannot be skipped', [
      ['Veiledningen «Første tur» må gjøres steg for steg. Knappen «Hopp over veiledningen» er borte. Lukker du spillet midt i, fortsetter den der du slapp.', 'The «First trip» guide is done step by step. The «Skip the guide» button is gone. If you close the game halfway, it goes on where you left off.']]],
    ['p31', '05.10.2026', 'Én klokke for alle', 'One clock for everyone', [
      ['Alle spillerne går på samme klokke og dato, så ingenting spoler tiden fram lenger: «Vent til åpning» ved et stengt mottak og «Spol fram til havn» under slep er fjernet. Mottaket viser når det åpner, og slepet tar den tiden det tar.', 'Every player is on the same clock and date, so nothing moves time on any more: «Wait for opening» at a closed plant and «Fast forward to harbour» under tow are gone. The plant shows when it opens, and the tow takes the time it takes.']]],
    ['p30', '05.10.2026', 'Mindre vinduer på telefonen', 'Smaller boxes on the phone', [
      ['Fart, kurs og posisjon står nå nederst i den lille kartplotteren, med neste veipunkt og ETA på en rute. GPS-boksen under er borte, bortsett fra når telefonen ligger, der kartplotteren er skjult.', 'Speed, course and position are now along the foot of the little chart plotter, with the next waypoint and ETA on a route. The GPS box under it is gone, except with the phone on its side, where the little chart is hidden.'],
      ['På en stående telefon tar statusboksen og den lille kartplotteren rundt en tredjedel av bredden, ikke halve skjermen.', 'On a standing phone the status box and the little chart plotter take about a third of the width, not half the screen.']]],
    ['p29', '05.10.2026', 'Rorbuer langs kysten, og hvile i land', 'Rorbuer along the coast, and rest ashore', [
      ['535 rorbuer langs hele kysten: én ved hvert fiskevær med mottak, og flere på lune steder mellom. De står i kartplotteren som små røde hus med navn, og Autonav kan ende ved kaia deres.', '535 rorbuer (fishermen’s cabins) along the whole coast: one by each fishing village with a plant, and more in sheltered spots between. They show in the chart plotter as little red houses with names, and Autonav can end at their quay.'],
      ['Du kan ikke hvile i en åpen båt. Seil hjem til naustet og trykk «Hvil», eller legg til ved en rorbu og ta inn for 150 kr natta. På rorbua er du uthvilt fra 0 til 100 % på seks timer. Båter med køyer hviler deg om bord ved kai som før.', 'You cannot rest in an open boat. Sail home to the boathouse and press «Rest», or moor at a rorbu and take a room for 150 kr a night. At the rorbu you go from 0 to 100 % in six hours. Boats with bunks rest you aboard at the quay as before.'],
      ['Mens du hviler, er skipperen borte fra båten. «Gå om bord» eller å kaste loss avslutter hvilen. Ved rorbua ligger båten trygt til kai i uvær.', 'While you rest, the skipper is gone from the boat. «Go aboard» or casting off ends the rest. At the rorbu the boat lies safe at the quay in bad weather.']]],
    ['p28', '05.10.2026', 'Ultra-grafikk', 'Ultra graphics', [
      ['Nytt nivå i Grafikk i 3D: Ultra, for de kraftigste telefonene og PC-ene. Det gir skjermens fulle oppløsning, tettere terreng og sjø med bølger hver 2. meter, og terreng 160 km bredt. Sikten er opptil 90 km i klarvær, og bygg, trær og båter vises i full detalj lenger ut. Slå på «Vis bildetakt» for å se hvor mye telefonen tåler.', 'New level in 3D graphics: Ultra, for the most powerful phones and PCs. It gives the screen’s full resolution, denser terrain and a sea with waves every 2 metres, and terrain 160 km wide. The view reaches up to 90 km in clear weather, and buildings, trees and boats show in full detail further out. Turn on «Show frame rate» to see how much the phone can take.']]],
    ['p27', '05.10.2026', 'Sjømerker langs hele kysten', 'Sea marks along the whole coast', [
      ['Lykter med sektorer og blink, fyr, staker, bøyer, kardinalmerker, varder og skjær langs hele kysten, ikke bare på Senja. De står i 3D, blinker om natta, vises i kartplotteren, og Autonav går utenom dem. Skjærene kan du gå på grunn på. Dataene kommer fra OpenStreetMap, som har dem fra Kystverket.', 'Lights with sectors and flashes, lighthouses, stakes, buoys, cardinal marks, cairns and rocks along the whole coast, not only on Senja. They stand in 3D, flash at night, show on the chart plotter, and Autonav keeps clear of them. You can run aground on the rocks. The data comes from OpenStreetMap, which has it from the Norwegian Coastal Administration.']]],
    ['p26', '05.10.2026', 'Mottakene langs hele kysten', 'The plants along the whole coast', [
      ['Alle de 153 fiskemottakene langs kysten har fått kaimottaket fra Blender, med kran, truck, is og bunkers, der mottaket ligger på ekte. Det finnes i tre utgaver: dagens mottak, et gammelt fiskebruk i rødmalt tre og et stort anlegg med fryselager. Hvert mottak får én av dem tilfeldig. Folkene og kranen arbeider når du leverer, som på Senja.', 'All 153 fish plants along the coast now have the harbour unit from Blender, with crane, forklift, ice and bunkers, where the plant really is. It comes in three looks: today’s plant, an old red-painted fish plant and a big plant with a cold store. Each plant gets one at random. The people and the crane work when you land your catch, as on Senja.']]],
    ['p25', '05.10.2026', 'Start ved fars naust', 'Start at Father’s boathouse', [
      ['Et nytt spill starter med båten ved fars naust, ikke ved mottaket. Utstyrsbutikken står et steinkast unna, uansett hvor langs kysten du starter, og mottaket er i nærheten, så første tur blir kort.', 'A new game starts with the boat at Father’s boathouse, not at the plant. The gear shop is a stone’s throw away wherever along the coast you start, and the plant is near by, so the first trip is short.'],
      ['Solveig i butikken har ei juksa og is til deg. Far betalte for dem i fjor høst, «til den som tar over».', 'Solveig in the shop has a jig and ice for you. Father paid for them last autumn, «for whoever takes over».'],
      ['Ingen hurtigreise: båten flyttes aldri for deg. Du seiler fra naustet til mottakskaia for å levere og fylle diesel, og tilbake. Trykk ved naustet i kartplotteren eller med Autonav, så ender ruta der.', 'No fast travel: the boat is never moved for you. You sail from the boathouse to the plant’s quay to land and fill diesel, and back. Tap by the boathouse on the chart plotter or with Autonav, and the route ends there.'],
      ['Hjemsted i Innstillinger flytter ikke lenger båten. Hjemhavna og naustet flyttes, og så seiler du dit selv.', 'Home in Settings no longer moves the boat. The home harbour and the boathouse move, and you sail there yourself.'],
      ['Autonav og rutene går ikke lenger gjennom bropilarer, kaier på påler eller sjømerker. Under en bro velger båten et løp mellom pilarene der brua er høy nok, og andre ting går den rundt. Det gjelder bruer og kaier langs hele kysten. Sjømerkene gjelder foreløpig bare Senja.', 'Autonav and the routes no longer go through bridge piers, piers on piles or sea marks. Under a bridge the boat picks a span between the piers where the bridge is high enough, and it goes round anything else. This holds for bridges and piers along the whole coast; the sea marks for now only on Senja.']]],
    ['p24', '05.10.2026', 'Ny innlasting og innlogging', 'New loading and sign-in screens', [
      ['Lyden: havet rumler ikke lenger. Det er et svakt sus med små bølgeskvulp mot skroget og kaia. Sjøen, vinden og regnet dør ut når kameraet går høyt opp i lufta, så bare musikken høres der oppe.', 'Sound: the sea no longer rumbles. It is a soft hiss with small waves lapping against the hull and the quay. The sea, the wind and the rain die away as the camera rises high into the air, so only the music is heard up there.'],
      ['3D på PC med Intel-grafikk: spillet starter med en enklere sjø der. Gir grafikkdriveren opp mens 3D starter, husker spillet det og prøver en enklere sjø neste gang siden lastes.', '3D on PCs with Intel graphics: the game starts with a simpler sea there. If the graphics driver gives up while 3D starts, the game remembers it and tries a simpler sea the next time the page loads.'],
      ['Innlastingen og innloggingen har fått et bilde fra Blender: fars naust i blåtimen, med lampa tent og trebåten fortøyd, og Senjas tinder med snø bak. Ny skrift og en tynn lysstripe som viser at spillet laster.', 'The loading and sign-in screens have a picture from Blender: Father’s boathouse at the blue hour, the lamp lit and the wooden boat moored, with Senja’s snowy peaks behind. New type, and a thin running light while the game loads.']]],
    ['p23', '05.10.2026', 'Fars naust og butikken på kaia', 'Father’s boathouse and the shop on the quay', [
      ['Fars gamle naust står ved hjemhavna di i 3D, med den slitne kaia på påler, på en rett strekning av fjæra like ved mottaket. I kartplotteren står det som «Fars naust».', 'Father’s old boathouse stands by your home harbour in 3D, with its worn pile quay, on a straight stretch of shore near the plant. On the chart plotter it is marked «Father’s boathouse».'],
      ['Utstyrsbutikken og båtforhandleren står på kaia i Finnsnes, med plassen foran planert og kartets hus flyttet bort.', 'The gear shop and boat dealer stand on the quay in Finnsnes, with the yard in front levelled and the map’s houses moved out of the way.'],
      ['Sett i stand naustet, i Notatbok: tett taket og sett inn vedovn, så hviler du raskere i hjemhavna. Fars arbeidsbenk gjør juksa og kveiteutstyr billigere der, og storfisken kan henge på en trofévegg.', 'Put the boathouse to rights, in Notebook: make the roof tight and put in a stove, and you rest faster in the home harbour. Father’s workbench makes jigs and halibut gear cheaper there, and the big fish can hang on a trophy wall.']]],
    ['p22', '05.10.2026', 'Sesonger og folk på kaia', 'Seasons and people on the quay', [
      ['Sesongene kommer som hendelser: «Skreien er kommet» på VHF, i Kystposten og på puben, og så høysesong, loddetorsk i Finnmark, seisommer, høsthyse, sild og hval, og julefiske. Datoene flytter seg litt fra år til år.', 'The seasons come as events: «The skrei has come» on the VHF, in Kystposten and at the pub, then the high season, capelin cod in Finnmark, the saithe summer, autumn haddock, herring and whales, and the Christmas fishing. The dates shift a little from year to year.'],
      ['Skreifestivalen andre helg i mars: største torsk fra lørdag til søndag kl. 18 vinner 15 000 kr. Andreplass gir 7 500 og tredjeplass 3 000.', 'The skrei festival on the second weekend of March: the biggest cod from Saturday to Sunday 18:00 wins NOK 15,000. Second place gets 7,500 and third 3,000.'],
      ['Ny app: Sesong. Den viser hva som er i gang, hva som kommer, og en fiskekalender med de beste månedene for hver art.', 'New app: Season. It shows what is on, what is coming, and a fish calendar with the best months for each kind.'],
      ['Ny app: Folk. Gamle Edvard, som kjente far, sitter på kaia i hjemhavna og har noe å si hver dag. Mottakssjefen gir faste leverandører 1–3 % bedre pris etter 2, 10 og 30 tonn. Solveig i butikken gir 10 % på isen etter 15 kjøp.', 'New app: People. Old Edvard, who knew Father, sits on the quay in your home harbour and has something to say each day. The plant manager gives regular suppliers 1–3 % more after 2, 10 and 30 tonnes. Solveig in the shop gives 10 % off the ice after 15 purchases.'],
      ['Oppdrag: starter du langs kysten, kommer bestillingene fra mottakene i nærheten, ikke fra Senja.', 'Orders: if you start along the coast, the orders come from the plants near by, not from Senja.']]],
    ['p21', '05.10.2026', 'Fars notatbok og storfisken', 'Father’s notebook and the big fish', [
      ['Ny app på telefonen: Notatbok. Far skrev ned fem méd rundt havna di, med retning, avstand, dybde i favner og et råd om fisken. Fisk innen 400 m fra et méd for å finne det. Der biter fisken 30 % bedre, og far skrev en liten historie ved hvert av dem. Finner du alle fem, får du fars gamle pilk.', 'New app on the phone: Notebook. Father wrote down five marks round your harbour, with the bearing, distance, depth in fathoms and a word about the fish. Fish within 400 m of a mark to find it. There the fish bite 30 % better, and Father wrote a little story beside each. Find all five and you get his old jig.'],
      ['«Vis i kartet» tegner sirkelen méden ligger i på kartplotteren. Funne méd får et blyantkryss med navnet.', '«Show on the chart» draws the circle the mark lies in on the chart plotter. Found marks get a pencil cross with the name.'],
      ['Storfisk: nå og da tar noe stort juksa. Det kan være en kveite på opptil 180 kg, en skrei på over 30 kg eller en stor lange, sei, uer eller brosme. Hold «Sveiv» for å ta inn line, og slipp når fisken drar eller belastningen blir rød. På fars Kveitebakke kommer storfisken oftere.', 'Big fish: now and then something big takes the jig. It can be a halibut of up to 180 kg, a skrei of over 30 kg, or a big ling, saithe, redfish or tusk. Hold «Reel» to take in line, and let go when the fish runs or the strain goes red. On Father’s halibut bank the big fish comes more often.'],
      ['Trofeveggen i notatboka viser all storfisken du har fått, med rekorden for hvert slag. Kveite i fredningstida settes ut igjen, men kommer likevel på veggen. Uten deg om bord tar mannskapet storfisken, og de får den inn halvparten av gangene.', 'The trophy wall in the notebook shows every big fish you have landed, with the record for each kind. Halibut in the closed season goes back, but still goes on the wall. Without you aboard the crew takes the big fish, and they get it in half the time.']]],
    ['p20', '05.10.2026', 'Hele kysten', 'The whole coast', [
      ['Nye spillere velger selv hvor fars naust står: alle fiskemottakene langs kysten som tar imot fisk fra små båter, på et kart og i en liste etter region. Stjernene er de to beste stedene for torsk i hver region.', 'New players choose where Father’s boathouse stands: every fish plant along the coast that takes fish from small boats, on a map and in a list by region. The stars are the two best places for cod in each region.'],
      ['153 nye mottak langs hele kysten, fra Lindesnes til Kjøllefjord, med kai, drivstoff og priser etter hva mottaket betaler. Du kan levere ved alle.', '153 new plants along the whole coast, from Lindesnes to Kjøllefjord, with a quay, fuel and prices after what the plant pays. You can land at all of them.'],
      ['Salgslaget viser de 10 nærmeste mottakene med avstand og pris for torsk, hyse og sei.', 'Salgslaget shows the 10 nearest plants with distance and price for cod, haddock and saithe.'],
      ['«Første tur» går fra stedet du valgte: til det beste torskefeltet i nærheten, og inn til mottaket der.', '«First trip» goes from the place you chose: to the best cod ground near by, and in to the plant there.'],
      ['Har du et spill fra før, kan du flytte til et annet sted langs kysten én gang gratis, under Innstillinger.', 'If you already have a game, you can move elsewhere along the coast once for free, in Settings.']]],
    ['p19', '05.10.2026', 'Mobil, nettbrett og musikk', 'Phones, tablets and music', [
      ['Spillet er gått gjennom på telefon, nettbrett og PC. På telefon fyller telefonen i spillet hele skjermen, handlingsknappene får plass, kartplotterens toppfelt vises helt, og kompasset ligger over infoboksen.', 'The game has been gone through on phones, tablets and PCs. On a phone the phone in the game fills the screen, the action buttons fit, the chart plotter’s top fields show in full, and the compass lies above the info box.'],
      ['Knappene i appene er store nok for fingeren, og på en telefon på siden er infoboksen mindre og minikartet borte, så alt får plass.', 'The buttons in the apps are big enough for a finger, and on a phone on its side the info box is smaller and the mini chart gone, so everything fits.'],
      ['Rolig musikk i bakgrunnen, laget mens den spiller: myke akkorder og en klokke nå og da, mørkere om natta og i dårlig vær. Skru den av eller opp i Innstillinger.', 'Quiet music in the background, made as it plays: soft chords and a bell now and then, darker at night and in bad weather. Turn it off or up in Settings.'],
      ['3D på telefoner som ikke tar sjøen: sjøen har fått egne bølgetabeller, og får telefonen ikke til noen av sjøene, tegnes en enkel sjø i stedet for at 3D slutter å virke.', '3D on phones that will not take the sea: the sea has its own wave tables now, and if the phone can do none of the seas, a simple sea is drawn instead of 3D giving up.'],
      ['Sjømann-appen viser bare lista med tatoveringer.', 'The Seaman app shows only the list of tattoos.'],
      ['Admin: «Vis brevet» spiller åpningsscenen igjen, og «Start nytt spill» begynner helt på nytt, slik en ny spiller gjør.', 'Admin: «Show the letter» plays the opening again, and «Start a new game» begins all over, as a new player does.']]],
    ['p18', '05.10.2026', 'Fars gamle trebåt', "Father's old wooden boat", [
      ['Nye spillere starter med fars gamle trebåt: 23 fot, klinkbygd og spissgattet, med rorkult og en 8 hk semidiesel som går i 7 knop.', "New players start with Father's old wooden boat: 23 ft, clinker-built and double-ended, with a tiller and an 8 hp semi-diesel that makes 7 knots."],
      ['Semidieselen dunker i takt med turtallet, 340 på tomgang og 850 på det meste, og for hvert tenn kommer en liten svart sky ut av eksosrøret.', 'The semi-diesel thumps with its revs, 340 at idle and 850 at most, and every firing puts a small black puff out of the exhaust.'],
      ['Om bord står fiskekassene foran midttofta, og sløyebordet ligger over babord rekke. Roret svinger med rorkulten.', 'Aboard, the fish crates stand forward of the middle thwart, and the gutting table lies across the port gunwale. The rudder swings with the tiller.'],
      ['Har du et spill fra før, beholder du båten din.', 'If you already have a game, you keep your boat.']]],
    ['p17', '05.10.2026', 'Brevet fra far', 'The letter from Father', [
      ['Et nytt spill begynner med en slitt konvolutt i mørket. Trykk på den, så åpner du brevet fra far.', 'A new game opens on a worn envelope in the dark. Tap it to open the letter from Father.'],
      ['Nye spillere gir bare båten et navn. Rederiet opprettes når du kjøper din første båt i lukket gruppe.', 'New players only name the boat. The company is founded when you buy your first boat in the closed group.'],
      ['Autonav ligger nå nede ved siden av knappene for zoom, og +, − og ◎ står helt ute ved kanten.', 'Autonav now sits at the bottom beside the zoom buttons, and +, − and ◎ stand right at the edge.'],
      ['3D på telefoner med Adreno-grafikk: Vil ikke telefonen ta sjøen, prøver spillet en enklere sjø i stedet for å gi opp.', '3D on phones with Adreno graphics: if the phone will not take the sea, the game tries a simpler sea instead of giving up.']]],
    ['p16', '05.10.2026', 'Kaia på Finnsnes', 'The quay at Finnsnes', [
      ['Båten lå inne i et bygg ved kaia på Finnsnes. Bygg på kaidekket og over liggeplassen er borte, så du ser båten og kaia når du starter.', 'The boat lay inside a building at the Finnsnes quay. Buildings on the quay deck and over the berth are gone, so you see the boat and the quay when you start.'],
      ['Snøen er stille. Før suste den som hvit støy.', 'Snow is silent. It used to hiss like white noise.'],
      ['Admin-appen på telefonen er bare for utvikleren. Den er borte for alle andre kontoer.', 'The Admin app on the phone is for the developer only. It is gone for every other account.'],
      ['3D på telefoner: Shaderne ber bare om høy presisjon der telefonen har det. Mister telefonen grafikken før 3D er i gang, prøver den igjen, og feilmeldingen sier mer.', '3D on phones: the shaders ask for high precision only where the phone has it. If the phone loses its graphics before 3D has started, it tries again, and the error message says more.']]],
    ['p15', '05.10.2026', 'Det Store Blå', 'Det Store Blå', [
      ['Spillet heter nå Det Store Blå. Lagringen din er den samme.', 'The game is now called Det Store Blå. Your save is the same.'],
      ['Ny logo og nye app-ikoner, laget i Blender: sjarken i blåtimen under tindene på Senja.', 'A new logo and new app icons, made in Blender: the sjark at the blue hour under the peaks of Senja.'],
      ['På detstorebla.no logger du inn med Google eller e-post, og spillet lagres på kontoen din, så du kan fortsette på en annen enhet. «Ja, del» i spørsmålet om statistikk lukker nå vinduet som det skal.', 'On detstorebla.no you sign in with Google or e-mail, and the game is saved to your account, so you can go on from another device. «Yes, share» in the statistics question now closes the window as it should.']]],
    ['p14', '05.10.2026', 'Kongekrabbe', 'King crab', [
      ['Taskekrabben er ute av spillet. Teinene fisker kongekrabbe, som nesten bare finnes i Vest-Finnmark. Vest for 26° Ø er fisket fritt, uten kvote og minstemål, men all krabbe skal landes. Øst for linja er kvoteområdet for dem som bor i Finnmark.', 'Brown crab is out of the game. The pots fish king crab, found almost only in West Finnmark. West of 26° E the fishing is free, with no quota and no minimum size, but all crab must be landed. East of the line is the quota area for those who live in Finnmark.'],
      ['Krabben leveres levende og betales etter Råfisklagets minstepris for klassen sin, og prisen følger måneden: høyest rundt nyttår, lavest i april. Død krabbe er verdiløs. Krabbekaret med sjøvann i Utstyr holder den levende i flere døgn.', 'The crab is landed alive and paid at least the minimum price of its class, and the price follows the month: highest round New Year, lowest in April. Dead crab is worthless. The live crab tank in Equipment keeps it alive for days.'],
      ['Kongekrabbeteinene er store og dyre, og det er plass til færre om bord. Kongekrabben er ny fra Blender.', 'King crab pots are big and dear, and fewer fit aboard. The king crab is new from Blender.']]],
    ['p13', '05.10.2026', 'Kysten', 'The coast', [
      ['Landet i kartplotteren følger kystlinja helt ut, med moloer og skjær, og det uskarpe landet ved siden av er borte. Spillet bruker den samme kystlinja når det avgjør hva som er land, så en rute som ser klar ut i kartet, er klar.', 'The land on the chart plotter follows the coastline exactly, with breakwaters and skerries, and the blurred land beside it is gone. The game decides what is land by the same coastline, so a route that looks clear on the chart is clear.'],
      ['I 3D møter landet sjøen der kystlinja går, og rundt båten er terrenget finere, så moloer og skjær får sin form.', 'In 3D the land meets the sea where the coastline runs, and round the boat the ground is finer, so breakwaters and skerries get their shape.']]],
    ['p12', '05.10.2026', 'Økonomien', 'The economy', [
      ['Sluttseddelen har de ekte trekkene fra Råfisklaget: lagsavgift, pensjonstrekk, produktavgift, forskningsavgift og ressursavgift, rundt 4 % til sammen. Lotten regnes av det som er igjen.', 'The landing note has the real deductions of the sales organisation: its levy, the pension, product, research and resource levies, about 4 % in all. The crew\'s share is reckoned on what is left.'],
      ['Papirer har ervervstillatelse for hver båt. Når salget passerer 50 000 kr på tolv måneder, blir fisket et enkeltpersonforetak med MVA, og MVA-en står på seddelen og går videre til staten.', 'Papers has the fishing permit for each boat. When the sales pass NOK 50,000 in twelve months, the fishing becomes a sole proprietorship with VAT, which stands on the note and goes on to the state.'],
      ['Mannskapet kan gå på hyre i stedet for lott: en fast dagslønn som betales hver natt, uansett fangst. Byttes på mannskapskortet i Rederi.', 'The crew can go on a wage instead of a share: a fixed day wage paid every night, whatever the catch. Switched on the crew card in Company.'],
      ['Skatten kommer: forskuddsskatt hvert kvartal og skatteoppgjør ved nyttår, med fiskerfradrag når du har fisket minst 130 dager. Du kan stifte Rederi AS fra skattekortet i Rederi.', 'Tax arrives: advance tax every quarter and a settlement at the new year, with the fisherman\'s deduction after 130 days fishing. You can found a limited company from the tax card in Company.']]],
    ['p11', '05.10.2026', 'Havn og sjø', 'Harbour and sea', [
      ['Mottakene står på en fylling inn til land, og havna rundt er hevet over flo, så det er ikke lenger vann bak kaia.', 'The fish plants stand on a fill in to the shore, and the harbour round them is raised above high tide, so there is no more water behind the quay.'],
      ['Hekkbølgene blekner gradvis og er like lange på begge sider, og propellstrømmen viser bare skumboblene.', 'The stern waves fade out gradually and are as long on both sides, and the prop wash shows only its foam bubbles.'],
      ['Båten snurrer ikke lenger rundt før den kommer fram til et stopp i høy fart.', 'The boat no longer spins round before it reaches a stop at speed.'],
      ['Kino-visningen holder båten i bildet også i høy fart, og bytter opptak når land kommer imellom.', 'The cinema view keeps the boat in the picture at speed too, and changes shot when land comes between.'],
      ['Når 3D-visningen ikke kan starte, sier meldingen hva som stoppet den.', 'When the 3D view cannot start, the message tells what stopped it.'],
      ['Ved rattet står båten stille rundt deg; bare blikket dempes mot stamp og rull.', 'At the wheel the boat stands still round you; only your gaze is steadied against pitch and roll.']]],
    ['p10', '05.10.2026', 'Regler langs hele kysten', 'Rules along the whole coast', [
      ['Fjordlinjene for kysttorsk gjelder langs hele kysten, rett fra Fiskeridirektoratet, og vises i kartet.', 'The fjord lines for coastal cod hold along the whole coast, straight from the Directorate of Fisheries, and show on the chart.'],
      ['Båtlengden avgjør hvor du kan fiske torsk, hyse og sei: innenfor fjordlinjene fra 15 m, innenfor grunnlinja fra 21 m og innenfor 4 nm fra 28 m, med unntakene i forskriften.', 'The boat\'s length decides where you may fish cod, haddock and saithe: inside the fjord lines from 15 m, inside the baseline from 21 m and within 4 nm from 28 m, with the regulation\'s exceptions.'],
      ['Stengte felt, Henningsværboksen, Borgundfjorden, Oslofjorden og gytefeltene i sør gjelder også. Sluttseddelen får Fiskeridirektoratets lokasjon.', 'Closed fields, the Henningsvær box, Borgundfjorden, the Oslo fjord and the spawning areas in the south apply too. The landing note gets the Directorate\'s location.'],
      ['Ny app: Regler. «Kan jeg fiske her?» med alle arter og redskap, Sjekk for andre steder og måneder, og reglene forklart enkelt. Linja «Regler» i statusboksen åpner den.', 'New app: Rules. «Can I fish here?» with every species and gear, Check for other places and months, and the rules told plainly. The «Rules» line in the status box opens it.'],
      ['Kartplotteren har et regellag: rødt der din båt ikke kan fiske med redskapet sitt i dag, gult der det er grenser. Det slås av og på under innstillingene.', 'The chart plotter has a rule layer: red where your boat may not fish with her gear today, yellow where there are limits. It is switched on and off in the settings.']]],
    ['p9', '05.10.2026', 'Rettinger', 'Fixes', [
      ['Alene i båten sløyer skipperen selv, og den som haler, er skipperen når det er hans jobb, i stedet for en annen figur.', 'Alone in the boat the skipper guts the catch himself, and the one hauling is the skipper when it is his job, not another figure.']]],
    ['p8', '05.10.2026', 'Kvotesystemet', 'The quota system', [
      ['Kvotene følger forskriften fra 1. oktober 2026 (J-161-2026), og regnes ut år for år fra totalkvoten og bestanden.', 'The quotas follow the regulation from 1 October 2026 (J-161-2026), worked out year by year from the total quota and the stock.'],
      ['Rundt 2 100 båter fisker ned gruppekvoten i åpen gruppe. Stoppen kommer når kvoten er tatt, med en ukes varsel. Noen år blir det ingen stopp, og maksimalkvotene kan økes.', 'About 2,100 boats fish down the open group\'s quota. The stop comes when it is taken, with a week\'s notice. Some years there is no stop, and the maximum quotas may be raised.'],
      ['Ferskfisktillegget kan økes om høsten, som det ofte er i virkeligheten.', 'The fresh-fish allowance may be raised in the autumn, as it often is.'],
      ['Kvote-appen har fanene Åpen gruppe, Bestand og Marked: strukturkvote, særlig kvoteordning og kvotesamarbeid.', 'The Quota app has the tabs Open group, Stock and Market: structure quotas, the special scheme and quota cooperation.'],
      ['Kystbåtene på 15 og 21 m selges med hjemmel. Hver hjemmel du kjøper, kommer fra en NPC-eier som går ut.', 'The 15 m and 21 m coastal vessels are sold with a right. Every right you buy comes from an NPC owner who leaves.'],
      ['Kvoten følger deg når du bytter båt (§ 29), og hyse og sei i lukket gruppe har maksimalkvote og bifangstgrense.', 'Your quota follows you when you change boats (§ 29), and haddock and saithe in the closed group have a maximum quota and a bycatch limit.']]],
    ['p7', '05.10.2026', 'Fra forslagslista', 'From the wish list', [
      ['Båten snurrer ikke lenger rundt siste veipunkt. Den bremser inn og stopper der.', 'The boat no longer spins round the last waypoint. It slows down and stops there.'],
      ['Håndjuksa og juksamaskinene fisker dobbelt så mye som før.', 'The hand jig and the jigging reels catch twice as much as before.'],
      ['Stanga er borte. «Jukse selv»: når det napper, trykk «Rykk» mens nåla er midt på. Midt på gir to fisk, bom gir halvparten.', 'The rod is gone. «Jig yourself»: when it bites, tap «Strike» as the needle is in the middle. The middle gives two fish, a miss half.'],
      ['Nattmodus i kartplotteren: mørke farger etter sola, eller Dag/Natt under Innstillinger i kartet.', 'Night mode in the chart plotter: dark colours by the sun, or Day/Night under the chart\'s settings.'],
      ['Kikkert i bro-visningen: dra to fingre fra hverandre for opptil 8×. Dobbelttrykk går tilbake.', 'Binoculars in the bridge view: spread two fingers for up to 8×. A double tap goes back.'],
      ['Fiskemottakene har åpningstider: hverdager 06–18, lørdag 08–14, og 05–22 hver dag i skreisesongen. «Vent til åpning» spoler fram.', 'The fish plants have opening hours: weekdays 06–18, Saturday 08–14, and 05–22 every day in the skrei season. «Wait for opening» runs the clock on.'],
      ['Dieselprisen endrer seg hver uke og er litt ulik fra havn til havn. Se Vær-appen.', 'The diesel price changes every week and differs a little between ports. See the Weather app.'],
      ['Nye kartdata (kart-7): rundt 4 100 fiskebåter langs kysten, med felt minst 600 m fra land.', 'New map data (kart-7): about 4,100 fishing boats along the coast, with grounds at least 600 m from land.'],
      ['Ny haill: Haill gir +100 % i 48 t og blir så mellomhaill og gammelhaill. Luksushaill gir +200 % de første 48 t. Kveithaill er borte.', 'New luck: Luck gives +100% for 48 h, then middle and old luck. Luxury luck gives +200% for the first 48 h. The halibut luck is gone.'],
      ['Haill du får eller vinner på puben, ligger i beholdningen til du trykker «Aktiver».', 'Luck you get or win at the pub waits in store until you tap «Switch on».'],
      ['Verftet: større lasterom i tre trinn (+25 %, +60 %, dobbelt) og større motor i to trinn (+20 % og +40 % effekt).', 'The yard: a bigger hold in three steps (+25%, +60%, double) and a bigger engine in two (+20% and +40% power).'],
      ['Last og vekt koster fart og drivstoff, mest på planende båter.', 'Load and weight cost speed and fuel, most on planing boats.'],
      ['Skroget gror til (raskest om sommeren) og koster opptil 15 % fart. Skrogrens på slipp under Vedlikehold, og antigro-belegg under Oppgrader.', 'The hull fouls (fastest in summer) and costs up to 15% speed. Hull cleaning on the slip under Maintenance, and an antifouling coat under Upgrade.'],
      ['Ny app «Trim»: justert dieselpumpe, ladeluftkjøling og økt turbotrykk for båter med dieselmotor.', 'New app «Tuning»: a tuned injection pump, charge air cooling and higher boost pressure for diesel boats.'],
      ['Fem slag agn til line og teiner: reke (torsk og skrei), krabbe (billig, ok på alt), krill (uer), makrell (sei) og sei (kveite og krabbe). Egen sei og krabbe kan bli agn før levering.', 'Five kinds of bait for line and pots: shrimp (cod and skrei), crab (cheap, fair on everything), krill (redfish), mackerel (saithe) and saithe (halibut and crab). Own saithe and crab can be bait before landing.'],
      ['Båten finner veien inn til kaiplassen og ut igjen uten å gå gjennom land, brygger og kaier, og går baklengs ut fra kaia.', 'The boat finds its way in to the berth and out again without going through land, piers and quays, and backs out from the quay.'],
      ['Nye fiskemodeller fra Blender: torsk, sei, hyse, lyr, lange, brosme, uer, kveite og taskekrabbe, i baljen, på jukselina og på dekk.', 'New fish models from Blender: cod, saithe, haddock, pollack, ling, tusk, redfish, halibut and brown crab, in the tub, on the jig line and on deck.'],
      ['Redningsskøyta kommer ut fra stasjonen i 25 knop og sleper deg inn i 6 knop. Du kan spole fram til havn.', 'The rescue boat comes out from its station at 25 knots and tows you in at 6 knots. You can fast forward to harbour.'],
      ['Garn og line går ut over hekken når du setter, med dregg og blåsestake. Fisken kommer opp i maskene og på krokene når du trekker.', 'Nets and lines run out over the stern when you set, with the grapnel and the marker buoy. The fish come up in the meshes and on the hooks when you haul.'],
      ['Fly og helikoptre over kysten mellom flyplassene og basene, med lys om natta og lyd.', 'Planes and helicopters over the coast between the airports and the bases, with lights at night and sound.']]],
    ['p6', '04.10.2026', 'Færre fiskebåter, spredt utover', 'Fewer fishing boats, spread out', [
      ['Rundt 4 300 båter langs kysten i stedet for 19 000, omtrent som de 4 614 aktive fiskefartøyene i 2024.', 'About 4,300 boats along the coast instead of 19,000, close to the 4,614 active fishing vessels of 2024.'],
      ['Hver båt fisker på sin egen plass på feltet, og driften går aldri opp på land.', 'Each boat fishes its own spot on the ground, and the drift never goes ashore.'],
      ['Flere fridager, og avreisen spres over morgenen.', 'More days off, and the departures spread over the morning.'],
      ['Navnene i kartplotteren vises når du zoomer inn, uten å ligge oppå hverandre.', 'The names in the chart plotter show when you zoom in, without lying on top of each other.']]],
    ['p5', '04.10.2026', 'Fiskebåter langs hele kysten', 'Fishing boats along the whole coast', [
      ['Havnene langs kysten har sin egen flåte. Du ser båtene innenfor AIS-rekkevidden (15 km).', 'The harbours along the coast have their own fleet. You see the boats within AIS range (15 km).'],
      ['De ligger ved kai om natta og i dårlig vær, går ut på feltene om morgenen og kommer hjem på ettermiddagen.', 'They lie at the quay at night and in bad weather, go out to the grounds in the morning and come home in the afternoon.'],
      ['Hver båt ligger ved en kai som er lang og dyp nok for henne.', 'Each boat lies at a quay that is long and deep enough for her.'],
      ['Trykk på en båt i kartplotteren for AIS-kortet med størrelse, dypgående og spor.', 'Tap a boat in the chart plotter for the AIS card with size, draught and track.']]],
    ['p4', '04.10.2026', 'Hus, veier, bruer og moloer langs kysten', 'Houses, roads, bridges and breakwaters along the coast', [
      ['Bygninger, veier og bruer langs hele kysten, ikke bare på Senja.', 'Buildings, roads and bridges along the whole coast, not only on Senja.'],
      ['Bruene går jevnt opp og ned, og tunnelene tegnes ikke over fjellet.', 'The bridges rise and fall smoothly, and the tunnels are not drawn over the mountain.'],
      ['Moloene er bygd av stein, med vei på toppen.', 'The breakwaters are built of stone, with a road on top.'],
      ['Brygger og kaier med lengde og dybde. Kartplotteren viser veiene og bruene.', 'Piers and quays with length and depth. The chart plotter shows the roads and bridges.']]],
    ['p3', '03.10.2026', 'Appen på hjemskjermen', 'The app on the home screen', [
      ['Spillet kan legges på hjemskjermen fra GitHub Pages og virker uten nett når kartet er lastet.', 'The game can go on the home screen from GitHub Pages and works offline once the map is loaded.'],
      ['Flytt spillet mellom artifacten og appen med lagringskoden under Innstillinger → Lagret spill.', 'Move the game between the artifact and the app with the save code under Settings → Saved game.']]],
    ['p2', '03.10.2026', 'Lyd', 'Sound', [
      ['Motor, sjø, vind og regn, måker, havna og arbeidet om bord.', 'Engine, sea, wind and rain, gulls, the harbour and the work aboard.'],
      ['Lyden blir svakere og mattere langt unna, og kommer fra venstre eller høyre. De andre båtene har egen motorlyd.', 'Sounds get fainter and duller far away, and come from the left or the right. The other boats have their own engines.']]],
    ['p1', '03.10.2026', 'Om bord og på broa', 'Aboard and on the bridge', [
      ['Manuell styring med gass og ratt i 3D, «Kast loss» og «Fortøy».', 'Manual steering with throttle and wheel in 3D, «Cast off» and «Moor».'],
      ['Lys om natta: lyktene lyser opp rundt seg, og fyrene sveiper.', 'Lights at night: the lamps light up round them, and the lighthouses sweep.'],
      ['Kino-visning der kameraet filmer turen selv.', 'A cinema view where the camera films the trip by itself.'],
      ['Garnhaler og linehaler som drar redskapet opp over skiva, og måker som flakser.', 'Net and line haulers that pull the gear up over the roller, and gulls that flap.'],
      ['Søvn med «Spol fram til du våkner», og brovaktsalarm som piper til du kvitterer.', 'Sleep with «Fast forward until you wake», and a bridge watch alarm that beeps until you acknowledge.'],
      ['Admin: «Fyll tanken» og «Skru av energi» for lange turer og testing.', 'Admin: «Fill the tank» and «Turn off energy» for long trips and testing.']]],
    ['p0', '02.–03.10.2026', 'Hele kysten', 'The whole coast', [
      ['Du kan seile langs hele norskekysten, med Kartverkets dybde.', 'You can sail the whole Norwegian coast, with the Norwegian Mapping Authority\'s depths.'],
      ['Tidevann for stedet du er, og sol og måne der båten er.', 'The tide where you are, and the sun and moon where the boat is.'],
      ['Autonav over hele kysten, og en kartplotter uten mørke felt når du drar i kartet.', 'Autonav along the whole coast, and a chart plotter without dark patches when you drag the map.']]]];
  const patchNew = () => { const i = PATCH.findIndex(p => p[0] === S.settings.patchSeen); return i < 0 ? PATCH.length : i; };
  function patch(){
    const seen = S.settings.patchLast, h = ['<div class="ph-c">'];
    for (const [id, date, no, en, lines] of PATCH)
      h.push('<div class="ph-card patchc"><h4>' + L(no, en) + (seen && PATCH.findIndex(p => p[0] === id) < PATCH.findIndex(p => p[0] === seen) ? ' <span class="pnew">' + L('Ny', 'New') + '</span>' : '') + '</h4><p class="ph-note">' + date + '</p><ul>' + lines.map(l => '<li>' + L(l[0], l[1]) + '</li>').join('') + '</ul></div>');
    h.push('</div>');
    return h.join('');
  }
